/* Flash cards USMLE: Biochemistry (1326 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["biochemistry"] = [{"name":"Molecular","cards":[["igw0m09rj","What is the basic repeating unit of chromatin?","The nucleosome: about 147 bp of DNA wrapped around a histone octamer (2 each of H2A, H2B, H3, H4).","Nucleossomo."],["6dsdhzn5l","Which histone is NOT part of the nucleosome core and ties nucleosomes together?","Histone H1 (linker histone).","Histona H1."],["pkectb55m","Why do histones bind DNA tightly?","Histones are rich in positively charged lysine and arginine, which bind the negatively charged phosphate backbone of DNA.","Histonas são positivas."],["1557d491k","Heterochromatin vs euchromatin: which is transcriptionally active?","Euchromatin (less condensed, 'Eu = truly transcribed'). Heterochromatin is condensed and largely silent.","Eucromatina é ativa."],["1s6430kkk","What appearance does heterochromatin have on electron microscopy?","Darkly staining, condensed chromatin (e.g., Barr body in females).","Densa e escura."],["gespam1sz","What effect does DNA methylation of CpG islands in a promoter have?","Represses (silences) transcription.","Silencia o gene."],["inzn9f1ig","What effect does histone acetylation have on gene expression?","Relaxes chromatin (removes positive charge) and increases transcription.","Ativa a expressão."],["14tfdhe1d","What effect does histone deacetylation have on gene expression?","Tightens chromatin and decreases transcription.","Reprime a expressão."],["1bot8d1c9","What effect does histone methylation usually have?","Usually represses transcription (can activate depending on the residue).","Geralmente reprime."],["9teq061hi","Name the purine bases.","Adenine and guanine (two rings). Mnemonic: PURe As Gold.","Adenina e guanina."],["5w83xfsor","Name the pyrimidine bases.","Cytosine, uracil, thymine (one ring). Mnemonic: CUT the PY (pie).","Citosina, timina, uracila."],["t2gn6h1xh","Which base is found in RNA but not DNA?","Uracil (replaces thymine).","Uracila."],["m38n2x22z","How does thymine differ structurally from uracil?","Thymine has a methyl group (5-methyluracil).","Timina tem metil."],["8jv0etkpi","Deamination of cytosine produces which base?","Uracil.","Uracila."],["sfx43t17n","Deamination of adenine produces which base?","Hypoxanthine.","Hipoxantina."],["v41mhu5qw","Which base pair has 3 hydrogen bonds and raises DNA melting temperature?","G-C (G-C has 3 H-bonds; A-T has 2).","G-C."],["f33dcy1c4","What is the difference between a nucleoside and a nucleotide?","Nucleoside = base + sugar. Nucleotide = base + sugar + phosphate.","Nucleotídeo tem fosfato."],["1sqmvtyc9","What bond links nucleotides in a DNA strand?","3'-5' phosphodiester bond.","Ligação fosfodiéster."],["9x5lupvju","What are the key amino acids needed for purine synthesis?","Glycine, aspartate, and glutamine (plus CO2 and THF one-carbon units).","Glicina, aspartato, glutamina."],["1d5fljvnm","What are the key molecules needed for pyrimidine synthesis?","Aspartate, glutamine, and CO2 (carbamoyl phosphate).","Aspartato, glutamina, CO2."],["icuj09ar7","In de novo purine synthesis, is the base built on the sugar or made first?","Purines are built on ribose-5-phosphate (PRPP) step by step.","Construída sobre o açúcar."],["gsbcn0iws","In de novo pyrimidine synthesis, is the base built on the sugar or made first?","The pyrimidine ring (orotate) is made first, then attached to PRPP.","Base feita antes."],["exo4xk179","What is the rate-limiting enzyme of de novo purine synthesis?","Glutamine-PRPP amidotransferase.","Glutamina-PRPP amidotransferase."],["1wvmsn11e","What is the rate-limiting enzyme of de novo pyrimidine synthesis?","Carbamoyl phosphate synthetase II (cytosol).","CPS II."],["d0vtammad","Carbamoyl phosphate synthetase I vs II: location and pathway?","CPS I: mitochondria, urea cycle, uses NH3. CPS II: cytosol, pyrimidine synthesis, uses glutamine.","CPS I mitocôndria/ureia; II citosol/pirimidinas."],["129if9zs4","Which enzyme converts ribonucleotides to deoxyribonucleotides?","Ribonucleotide reductase.","Ribonucleotídeo redutase."],["it6qyj1yf","Which drug inhibits ribonucleotide reductase?","Hydroxyurea.","Hidroxiureia."],["5xfhq11ia","Which enzyme converts dUMP to dTMP?","Thymidylate synthase (uses N5,N10-methylene THF).","Timidilato sintase."],["1532icmei","Which drugs inhibit thymidylate synthase?","5-fluorouracil (5-FU) and capecitabine.","5-FU."],["1myav6ut3","Which drugs inhibit dihydrofolate reductase (DHFR)?","Methotrexate (human), trimethoprim (bacterial), pyrimethamine (protozoal).","Metotrexato, trimetoprima, pirimetamina."],["1eyna6vnv","Why does DHFR inhibition reduce DNA synthesis?","Less THF is regenerated, so less one-carbon donor for thymidylate and purine synthesis.","Falta timidina."],["tcb8awiye","Which drug inhibits dihydroorotate dehydrogenase?","Leflunomide.","Leflunomida."],["hdxr5b14s","Which drugs inhibit IMP dehydrogenase (purine synthesis)?","Mycophenolate and ribavirin.","Micofenolato e ribavirina."],["zel9ov14b","Which drugs inhibit de novo purine synthesis as purine analogs?","6-mercaptopurine and its prodrug azathioprine.","Azatioprina e 6-MP."],["vl1mrij79","Which enzyme inactivates 6-mercaptopurine, causing toxicity when inhibited?","Xanthine oxidase (allopurinol/febuxostat raise 6-MP levels). TPMT also inactivates it.","Xantina oxidase."],["fqoslheiu","Which enzyme defect causes hereditary orotic aciduria?","UMP synthase (bifunctional: orotate phosphoribosyltransferase + OMP decarboxylase).","UMP sintase."],["1eu0m5sgl","How does orotic aciduria present?","Megaloblastic anemia not corrected by B12 or folate, failure to thrive, orotic acid in urine, normal ammonia.","Anemia megaloblástica sem B12."],["1dng4lu1n","Treatment of hereditary orotic aciduria?","Uridine (bypasses the enzyme block).","Uridina."],["k68ti010i","How do you distinguish orotic aciduria from OTC deficiency?","OTC deficiency has hyperammonemia and no megaloblastic anemia; orotic aciduria has normal ammonia and megaloblastic anemia.","OTC tem hiperamonemia."],["12rszsb1j","What is the inheritance of adenosine deaminase (ADA) deficiency?","Autosomal recessive.","Autossômica recessiva."],["18gjtm7dc","How does ADA deficiency cause immunodeficiency?","Excess dATP inhibits ribonucleotide reductase, blocking DNA synthesis and killing lymphocytes (SCID).","Acúmulo tóxico em linfócitos."],["xdljzs1l1","Which enzyme is deficient in Lesch-Nyhan syndrome?","HGPRT (hypoxanthine-guanine phosphoribosyltransferase).","HGPRT."],["1bfcfwvj9","What is the inheritance of Lesch-Nyhan syndrome?","X-linked recessive.","Ligada ao X."],["otu3q01cq","Classic findings of Lesch-Nyhan syndrome?","Hyperuricemia, gout, self-mutilation, aggression, intellectual disability, dystonia. Mnemonic: HGPRT (Hyperuricemia, Gout, Pissed off, Retardation, dysTonia).","Gota, automutilação, distonia."],["1wwhtk7k8","Treatment of hyperuricemia in Lesch-Nyhan?","Allopurinol or febuxostat (do not fix the neurologic symptoms).","Alopurinol ou febuxostate."],["t2p5v4ptx","What does the purine salvage pathway do?","Recycles free bases (hypoxanthine, guanine) back to nucleotides using PRPP via HGPRT; adenine via APRT.","Recicla bases."],["1f46558pc","What is the end product of purine degradation in humans?","Uric acid (via xanthine oxidase).","Ácido úrico."],["1l83ffxtp","Which enzyme converts hypoxanthine to xanthine and xanthine to uric acid?","Xanthine oxidase.","Xantina oxidase."],["scfoul187","What does it mean that the genetic code is 'degenerate'?","Most amino acids are coded by more than one codon (exceptions: methionine and tryptophan have one codon each).","Vários códons por aminoácido."],["r1j0v4e6t","What does it mean that the genetic code is 'unambiguous'?","Each codon codes for only one amino acid.","Cada códon um aminoácido."],["16kq8v835","What does it mean that the genetic code is 'commaless' and 'nonoverlapping'?","It is read from a fixed start point as continuous triplets, with no punctuation or overlap (some viruses are exceptions).","Leitura contínua sem sobreposição."],["dlkiru1gt","What does it mean that the genetic code is 'universal'?","Nearly the same in all organisms (exceptions: mitochondria, archaea, Mycoplasma, some yeasts).","Igual em quase todos."],["149enlo1o","Which amino acids have only one codon?","Methionine (AUG) and tryptophan (UGG).","Metionina e triptofano."],["1hw24x1pb","What is the start codon and which amino acid does it code in eukaryotes?","AUG; methionine (may be removed later).","AUG; metionina."],["14342m41e","What amino acid does AUG code in prokaryotes as the start codon?","N-formylmethionine (fMet), which stimulates neutrophil chemotaxis.","Formil-metionina."],["1arznpv11","What are the three stop codons?","UGA, UAA, UAG. (U Go Away, U Are Away, U Are Gone).","UAA, UAG, UGA."],["10s7zqr16","What is a silent mutation?","Nucleotide substitution that codes for the same amino acid, often at the third (wobble) position.","Mesmo aminoácido."],["12s0v1z12","What is a missense mutation? Give an example.","Substitution producing a different amino acid. Example: sickle cell disease (glutamate to valine in beta-globin).","Troca de aminoácido."],["1cfydjv1r","What is a nonsense mutation?","Substitution that creates a premature stop codon, usually producing a truncated, nonfunctional protein.","Códon de parada precoce."],["iw41831gk","What is a frameshift mutation? Give an example.","Insertion/deletion of a number of nucleotides not divisible by 3, altering the reading frame downstream. Example: Duchenne muscular dystrophy.","Muda a leitura."],["10pp8i04i","Why is Becker muscular dystrophy milder than Duchenne?","Becker usually has in-frame deletions, producing a partially functional dystrophin.","Mantém a leitura."],["uxdwz91qm","What is a transition mutation?","Purine replaced by purine or pyrimidine replaced by pyrimidine.","Purina por purina."],["txkxrus63","What is a transversion mutation?","Purine replaced by a pyrimidine or vice versa.","Purina por pirimidina."],["cju7s5113","Rank point mutations by usual severity.","Nonsense > missense > silent.","Nonsense > missense > silenciosa."],["158glc21r","What is a splice-site mutation? Give examples of diseases.","Mutation that alters splicing, causing retained introns or lost exons. Examples: some beta-thalassemias, Gaucher disease, Marfan syndrome.","Erro de splicing."],["1lvymh4ee","What is a trinucleotide repeat expansion?","Increase in the number of repeated triplets, often worsening over generations (anticipation). Examples: Huntington, fragile X, myotonic dystrophy, Friedreich ataxia.","Repetição de trincas."],["ev0tygxbl","In which direction is DNA synthesized?","5' to 3' (new nucleotides are added to the 3'-OH).","5' para 3'."],["qtylg517r","In which direction is mRNA read during translation?","5' to 3'.","5' para 3'."],["478kqg1c2","In which direction is protein synthesized?","N-terminus to C-terminus.","N para C."],["y7n9iqgh1","What is the origin of replication?","Specific sequence where DNA replication begins; prokaryotes have one, eukaryotes have many. Often AT-rich.","Início da replicação."],["1vim2hzkm","What is a replication fork?","Y-shaped region where leading and lagging strands are synthesized.","Forma de Y."],["1p03vx61t","What does helicase do?","Unwinds the DNA double helix at the replication fork (needs ATP).","Abre a dupla hélice."],["1fgfon216","Which syndrome involves a mutated DNA helicase and premature aging?","Werner syndrome (WRN helicase).","Werner."],["1cyfv2p2v","What do single-stranded binding proteins do?","Prevent separated strands from reannealing and protect them from degradation.","Impedem reanelamento."],["5fdgfl1mp","What does DNA topoisomerase do?","Creates single- or double-strand breaks to relieve supercoils ahead of the replication fork.","Alivia torção."],["qvq2bnq3u","Which drugs inhibit human topoisomerase I?","Irinotecan and topotecan.","Irinotecano, topotecano."],["ypjgmi95d","Which drugs inhibit human topoisomerase II?","Etoposide and teniposide (also doxorubicin/anthracyclines).","Etoposídeo, teniposídeo."],["1xlksel1g","Which drugs inhibit prokaryotic topoisomerase II (DNA gyrase) and IV?","Fluoroquinolones.","Fluoroquinolonas."],["14l1q471m","What does primase do?","Makes a short RNA primer that provides a free 3'-OH for DNA polymerase.","Faz primer de RNA."],["o3ksda12o","What does prokaryotic DNA polymerase III do?","Main elongating polymerase: 5' to 3' synthesis and 3' to 5' exonuclease proofreading.","Sintetiza e revisa."],["k3do1q1g3","What does prokaryotic DNA polymerase I do?","Removes RNA primers with 5' to 3' exonuclease and fills the gaps with DNA; also proofreads 3' to 5'.","Remove primer."],["y5pp3s15f","What does DNA ligase do?","Seals nicks with a phosphodiester bond (joins Okazaki fragments).","Une fragmentos."],["1k604cn1u","Which strand is synthesized continuously?","The leading strand.","Fita líder."],["1xlbqp5ic","What are Okazaki fragments?","Short DNA fragments made discontinuously on the lagging strand.","Pedaços da fita atrasada."],["1jjtxw927","What does telomerase do?","Adds TTAGGG repeats to the 3' ends of chromosomes using an RNA template (reverse transcriptase), preventing shortening.","Estende telômeros."],["17qe3g31g","In which cells is telomerase typically active?","Stem cells, germ cells, and many cancer cells (allows immortality).","Células-tronco e câncer."],["1np7a5bfe","What does dyskeratosis congenita involve?","Defective telomere maintenance: nail dystrophy, leukoplakia, reticulated skin pigmentation, bone marrow failure.","Telomerase defeituosa."],["11k0ich1v","Which eukaryotic DNA polymerases are the main replicative enzymes?","Polymerase delta (lagging, also leading) and epsilon (leading); alpha has primase activity.","Delta e épsilon."],["i0g31h9xn","Which eukaryotic DNA polymerase replicates mitochondrial DNA?","Polymerase gamma.","Gama."],["rcql5k13d","Which antiviral class targets viral DNA polymerase as chain terminators?","Nucleoside analogs, e.g., acyclovir (lacks 3'-OH).","Análogos de nucleosídeo."],["5efwzhi5u","What is nucleotide excision repair (NER) used for?","Bulky helix-distorting lesions such as pyrimidine (thymine) dimers from UV light. Occurs in G1.","Reparo de dano volumoso."],["1tq87sj1h","Which disease is caused by defective nucleotide excision repair?","Xeroderma pigmentosum.","Xeroderma pigmentoso."],["1c0kf0see","Clinical features of xeroderma pigmentosum?","Extreme UV sensitivity, freckling, early skin cancers (SCC, BCC, melanoma), corneal ulcers.","Sensibilidade ao sol e câncer de pele."],["g2jgp213v","What is base excision repair (BER) used for?","Single damaged bases from deamination, oxidation, or alkylation (e.g., cytosine to uracil). Occurs throughout the cell cycle.","Reparo de base danificada."],["1aivkcttj","Order of enzymes in base excision repair?","Glycosylase removes base, AP endonuclease cuts backbone, lyase removes sugar, DNA polymerase beta fills gap, ligase seals.","Glicosilase, endonuclease, lyase, polimerase, ligase."],["nv7huk7p3","What is mismatch repair (MMR) used for?","Mismatched bases on the newly synthesized strand. Occurs mainly in G2.","Corrige pareamento errado."],["1a6a7xc14","Which syndrome is caused by defective mismatch repair?","Lynch syndrome (hereditary nonpolyposis colorectal cancer), with microsatellite instability.","Lynch."],["15g4y091p","Which genes are commonly mutated in Lynch syndrome?","MLH1, MSH2, MSH6, PMS2.","MLH1, MSH2."],["ai8q3qg40","Which cancers occur in Lynch syndrome?","Colorectal (proximal), endometrial, ovarian, gastric, urinary tract cancers.","Cólon, endométrio, ovário."],["1mtwrzc1w","What is nonhomologous end joining (NHEJ)?","Repair of double-strand breaks by directly ligating ends; no template, so may lose information.","Une pontas quebradas."],["12kjfgf11","Which diseases involve defective NHEJ?","Ataxia-telangiectasia (ATM) and some forms of SCID (e.g., Artemis).","Ataxia-telangiectasia."],["1g0247lzd","What is homologous recombination repair?","Repair of double-strand breaks using a homologous sister chromatid as template; error-free.","Reparo usando fita homóloga."],["1ca2l81i9","Which genes involved in homologous recombination are mutated in hereditary breast/ovarian cancer?","BRCA1 and BRCA2.","BRCA1 e BRCA2."],["1a1g2pu15","Which syndrome is caused by defective homologous recombination/ interstrand crosslink repair and causes bone marrow failure?","Fanconi anemia.","Anemia de Fanconi."],["136i6xf7w","Which drug class exploits defective homologous recombination in BRCA tumors?","PARP inhibitors (e.g., olaparib), causing synthetic lethality.","Inibidores de PARP."],["x76yho1b7","What does RNA polymerase I make?","rRNA (most of it). Located in the nucleolus.","rRNA."],["rly6451da","What does RNA polymerase II make?","mRNA (and some snRNA, microRNA).","mRNA."],["4xhocr2oh","What does RNA polymerase III make?","tRNA, 5S rRNA, and other small RNAs.","tRNA."],["u12yv71n5","Mnemonic for eukaryotic RNA polymerase products?","I, II, III = rRNA, mRNA, tRNA (rmt, in alphabetical order).","Polimerases 1, 2, 3 = r, m, t."],["cgi3v7jvt","Which toxin inhibits RNA polymerase II and which organism produces it?","Alpha-amanitin from Amanita phalloides (death cap mushroom); causes severe hepatotoxicity.","Alfa-amanitina; Amanita."],["1bpkb6xob","Which drug inhibits prokaryotic DNA-dependent RNA polymerase?","Rifampin.","Rifampicina."],["22ad5fxfi","Which drug inhibits RNA polymerase in both prokaryotes and eukaryotes?","Actinomycin D (dactinomycin).","Actinomicina D."],["1vzd79k1a","How many RNA polymerases do prokaryotes have?","One, which makes all RNA types (holoenzyme with sigma factor).","Uma."],["wf58hingj","Which is the most abundant RNA type? Longest? Smallest?","Most abundant: rRNA. Longest: mRNA. Smallest: tRNA.","rRNA; mRNA; tRNA."],["1h7mrl3mj","What is a promoter?","Site upstream of a gene where RNA polymerase II and transcription factors bind (e.g., TATA box, CAAT box).","Início da transcrição."],["b5zwcd7hp","What does a mutation in a promoter usually cause?","Dramatic decrease in transcription of that gene.","Menos transcrição."],["fagdkt13n","What is an enhancer?","DNA sequence that increases transcription when bound by activators; can be upstream, downstream, or in an intron, far from the gene.","Aumenta a transcrição."],["p8y2si17z","What is a silencer?","DNA site where repressors bind to decrease transcription; can be far from the gene.","Reduz a transcrição."],["1s8rucjic","What are the three main processing steps of eukaryotic pre-mRNA?","5' 7-methylguanosine cap, 3' poly-A tail, and splicing out of introns.","Cap, cauda poli-A, splicing."],["1sw5at51m","Where does mRNA processing occur?","In the nucleus, before export to the cytosol.","Núcleo."],["a6aj9g1ss","What is the poly-A tail signal sequence?","AAUAAA.","AAUAAA."],["1b65v8u1o","What is heterogeneous nuclear RNA (hnRNA)?","The initial pre-mRNA transcript before processing.","Transcrito inicial."],["jjtbe01fa","Where are mRNAs degraded or stored in the cytoplasm?","P-bodies (processing bodies), containing exonucleases, decapping enzymes, and microRNAs.","Corpúsculos P."],["gu6n1o1uu","What is the spliceosome made of?","snRNPs (small nuclear ribonucleoproteins) and other proteins.","snRNPs e proteínas."],["3o86zm1qa","Which antibodies are associated with snRNP components in SLE and MCTD?","Anti-Smith (SLE, highly specific) and anti-U1 RNP (mixed connective tissue disease).","Anti-Smith; anti-U1 RNP."],["1032kva1l","Steps of splicing, in brief?","snRNPs bind the pre-mRNA, forming a lariat intermediate; the intron is released as a lariat and exons are joined.","Corte e união em laço."],["1jgajab1x","Introns vs exons?","Exons are expressed (coding) sequences that remain in mRNA; introns are intervening noncoding sequences removed by splicing.","Íntrons são removidos."],["1s1ey4gdo","What is alternative splicing?","Different exon combinations from the same gene produce different protein variants (e.g., antibody heavy chains).","Várias proteínas de um gene."],["b65bg058b","What is the general structure of tRNA?","About 75-90 nucleotides, cloverleaf shape, anticodon at one end, CCA at the 3' end where the amino acid binds.","Trevo."],["12skjmx16","What does the CCA sequence on tRNA do?","3' end where the amino acid is attached (Can Carry Amino acids).","Liga o aminoácido."],["1t4xwpk1h","What does the T-arm of tRNA do?","Contains the TΨC sequence needed for binding to the ribosome.","Liga ao ribossomo."],["gpisw84su","What does the D-arm of tRNA do?","Contains dihydrouridine and allows recognition by the correct aminoacyl-tRNA synthetase.","Reconhecida pela sintetase."],["1cx4tyndb","What does aminoacyl-tRNA synthetase do?","Attaches the correct amino acid to its tRNA using ATP; proofreads and is responsible for translation accuracy.","Carrega o tRNA certo."],["1jrr9krmx","What does 'wobble' mean?","Accurate base pairing is needed only at the first two codon positions; the third position can pair loosely, so one tRNA can read several codons.","Pareamento flexível na 3ª base."],["cct7h21wf","Eukaryotic vs prokaryotic ribosome sizes?","Eukaryotic: 40S + 60S = 80S (Even). Prokaryotic: 30S + 50S = 70S (Odd).","80S vs 70S."],["z5i0x71ao","Which energy molecule is used for tRNA charging and which for translocation?","ATP charges tRNA (aminoacyl-tRNA synthetase); GTP is used for tRNA binding and translocation.","ATP; GTP."],["491q09ys6","What are the three ribosomal sites in order of tRNA movement?","A (aminoacyl, incoming), P (peptidyl, growing chain), E (exit, empty tRNA). Mnemonic: APE.","A, P, E."],["m6m6x3y5f","Which enzyme forms the peptide bond and what is it made of?","Peptidyltransferase, a ribozyme (rRNA of the large subunit).","Peptidil transferase; rRNA."],["1ms6fbs7u","What happens in translation initiation in eukaryotes?","Initiation factors (eIFs) help assemble the 40S subunit with initiator tRNA, scan to AUG, then the 60S subunit joins; GTP is used.","Formação do complexo inicial."],["xsbmk910w","What happens in translation termination?","A stop codon in the A site is recognized by release factors, and the polypeptide is released.","Fator de liberação."],["1ifw3ssqi","Which antibiotics bind the 30S ribosomal subunit?","Aminoglycosides and tetracyclines (Buy AT 30).","Aminoglicosídeos e tetraciclinas."],["1sstwcatn","Which antibiotics bind the 50S ribosomal subunit?","Chloramphenicol, clindamycin, macrolides (erythromycin), linezolid, streptogramins (CCEL at 50).","Macrolídeos, cloranfenicol, clindamicina, linezolida."],["3frb107k2","What does diphtheria toxin do?","ADP-ribosylates and inactivates elongation factor 2 (EF-2), stopping protein synthesis.","Inativa EF-2."],["2g472l1ub","Which toxin also inactivates EF-2 by ADP-ribosylation?","Pseudomonas aeruginosa exotoxin A.","Exotoxina A de Pseudomonas."],["3q58s6cq2","What does Shiga toxin do?","Cleaves rRNA of the 60S subunit, inhibiting protein synthesis.","Inativa a subunidade 60S."],["1jfsqs69y","What is trimming as a posttranslational modification?","Removal of N- or C-terminal propeptides from zymogens to make mature proteins (e.g., trypsinogen to trypsin).","Corte de partes."],["nusbvedzz","Name common covalent posttranslational modifications.","Phosphorylation, glycosylation, hydroxylation, methylation, acetylation, ubiquitination.","Fosforilação, glicosilação, acetilação."],["12yqqv91h","What does ubiquitination usually signal?","Tagging a protein for degradation by the proteasome.","Degradação no proteassoma."],["mc60o710a","What are chaperone proteins?","Proteins that help other proteins fold properly (e.g., heat shock proteins induced by stress).","Ajudam o dobramento."],["filf71iqq","What is a lac operon and how is it regulated?","Prokaryotic operon for lactose metabolism; induced by lactose (allolactose inactivates the repressor) and enhanced by low glucose (high cAMP-CAP).","Operon da lactose."],["fpngxv1qv","When is the lac operon maximally transcribed?","Low glucose and lactose present.","Lactose presente, glicose ausente."],["z1ginriym","What is the role of cAMP-CAP in the lac operon?","Low glucose raises cAMP, which binds CAP and increases RNA polymerase binding (positive control).","Ativa transcrição."],["p6wv70j4q","What is a microRNA?","Small noncoding RNA that binds complementary mRNA and blocks translation or causes degradation.","Silencia mRNA."],["12hgj2ies","What is RNA interference with siRNA?","Small interfering RNA (double-stranded) binds a target mRNA and causes its degradation; used experimentally to knock down genes.","Corta mRNA alvo."],["sah92dlrl","What is a polycistronic mRNA?","An mRNA encoding several proteins, typical of prokaryotic operons.","Vários genes num mRNA."],["fteyrz1cw","Is eukaryotic mRNA usually monocistronic or polycistronic?","Monocistronic (one protein per mRNA).","Monocistrônico."],["ep4pq1zk7","Where does transcription occur in eukaryotes vs translation?","Transcription: nucleus. Translation: cytoplasm (free ribosomes or rough ER).","Núcleo vs citoplasma."],["1j1fknf14","Where are transcription and translation coupled?","In prokaryotes (no nucleus, both happen at the same time in the cytoplasm).","Procariotos."],["skun0hv99","What is the function of the 5' cap?","Protects mRNA from degradation, aids nuclear export and ribosome binding.","Protege e inicia tradução."],["1fbmnols1","What are the components of a nucleosome 'beads on a string'?","Nucleosomes (beads) connected by linker DNA bound by H1 (string).","DNA e histonas."],["1d9gb46wh","What happens to chromatin during mitosis?","It condenses into chromosomes (30-nm fiber and higher-order loops).","Condensa."],["j3d0e4ppx","What is a codon vs anticodon?","Codon: 3-nucleotide sequence on mRNA. Anticodon: complementary 3 nucleotides on tRNA.","Códon no mRNA; anticódon no tRNA."],["1v5t2bh9e","Why can a single base deletion in an exon be devastating?","It causes a frameshift, altering every downstream codon and often creating a premature stop.","Muda a leitura."],["eiafjb19d","What is the difference between DNA replication fidelity mechanisms: proofreading vs mismatch repair?","Proofreading by DNA polymerase 3'-5' exonuclease occurs during synthesis; mismatch repair fixes errors left after replication.","Revisão na hora vs após."],["nrwm5d1l6","How does the mismatch repair system tell the new strand from the template in prokaryotes?","The new strand is not yet methylated (hemimethylated DNA).","Fita velha metilada."],["zdbzqz1vo","What is reverse transcriptase?","RNA-dependent DNA polymerase, used by retroviruses (HIV) and telomerase.","RNA para DNA."],["7d8rac1me","Which antiretroviral classes target HIV reverse transcriptase?","NRTIs (e.g., tenofovir, zidovudine) and NNRTIs (e.g., efavirenz).","ITRN e ITRNN."],["ljjouofzz","Which RNA does the nucleolus produce?","rRNA (by RNA polymerase I) and ribosome subunit assembly.","rRNA."],["olwcgy1y2","What does the signal recognition particle (SRP) do?","Binds the signal peptide of nascent secretory proteins and directs the ribosome to the rough ER.","Leva ao retículo."],["doyfdtnfl","What is the role of mannose-6-phosphate?","Golgi tag that targets proteins to lysosomes.","Envia ao lisossomo."],["g1l34i1hv","Which disease results from failure to add mannose-6-phosphate?","I-cell disease (inclusion cell disease): N-acetylglucosaminyl-1-phosphotransferase deficiency.","Doença de célula I."],["2yothg1o1","Clinical findings of I-cell disease?","Coarse facies, gingival hyperplasia, clouded corneas, restricted joints, claw hands, high plasma lysosomal enzymes; often fatal in childhood.","Atraso, face grosseira, morte precoce."],["otb1quw43","What is the general sequence of protein secretion?","Rough ER, then Golgi (via COPII vesicles), then secretory vesicles or lysosomes or membrane.","RER, Golgi, vesícula, membrana."],["1cba1uq1c","What does COPI vs COPII transport?","COPII: ER to Golgi (anterograde). COPI: Golgi to ER and between Golgi cisternae (retrograde).","Golgi→RE vs RE→Golgi."],["olqixtz8b","What does clathrin do?","Coats vesicles moving from trans-Golgi to lysosomes and from plasma membrane to endosomes (receptor-mediated endocytosis, e.g., LDL).","Endocitose."],["sgepfr1y4","What happens in N-linked glycosylation vs O-linked?","N-linked: on asparagine, starts in rough ER. O-linked: on serine/threonine, occurs in Golgi.","Asparagina vs serina/treonina."],["1vel2n01p","What are proteasomes?","Barrel-shaped complexes that degrade ubiquitin-tagged proteins.","Degradam proteínas."],["3brciu1s3","Which drug inhibits the proteasome and is used in multiple myeloma?","Bortezomib (also carfilzomib).","Bortezomibe."],["6y77yfuxy","What are peroxisomes responsible for?","Beta-oxidation of very-long-chain fatty acids, alpha-oxidation of branched-chain fatty acids, catabolism of amino acids and ethanol, synthesis of plasmalogens.","Oxidar ácidos graxos longos."],["lutiuhmvd","Which disease is caused by defective peroxisome biogenesis?","Zellweger syndrome: hypotonia, seizures, hepatomegaly, early death.","Zellweger."],["xm69an1mf","What accumulates in Refsum disease and why?","Phytanic acid, due to defective peroxisomal alpha-oxidation.","Ácido fitânico; falta alfa-oxidação."],["1izbhe1dr","Features of Refsum disease?","Scaly skin, ataxia, cataracts/night blindness, shortening of the 4th toe, epiphyseal dysplasia. Treatment: avoid dietary phytanic acid.","Neuropatia, ictiose, retinite."],["uasleh1cs","What accumulates in adrenoleukodystrophy?","Very-long-chain fatty acids (VLCFA) in adrenal glands, white matter, and testes, due to defective peroxisomal transport (ABCD1, X-linked).","Ácidos graxos muito longos."],["jdtf361oe","Clinical features of X-linked adrenoleukodystrophy?","Progressive demyelination (behavior change, vision loss), adrenal insufficiency, in boys.","Desmielinização e insuficiência adrenal."]]},{"name":"Cellular","cards":[["1qxrkqtvq","What are the phases of the cell cycle?","G1, S (DNA synthesis), G2, and M (mitosis). G1, S, G2 together form interphase.","G1, S, G2, M."],["oegdedf6e","Which phase of the cell cycle is the most variable in length?","G1 (and G0).","G1."],["186rc1p1f","What is G0?","A quiescent resting phase where cells exit the cycle; they can re-enter G1 when stimulated.","Fase de repouso."],["3wg2lq1jx","What drives progression through the cell cycle?","Cyclins binding cyclin-dependent kinases (CDKs), which phosphorylate target proteins.","Ciclinas e CDKs."],["1r1phrk1h","Are CDKs constitutive or regulated?","CDKs are constitutive and inactive alone; activity depends on cyclin levels, which rise and fall.","CDKs constantes; ciclinas variam."],["1kpm0gek5","What is the role of the Rb protein at the G1/S checkpoint?","Hypophosphorylated Rb binds and inhibits E2F, blocking entry into S phase.","Freia G1 para S."],["1ukvva61y","What happens when Rb is phosphorylated by cyclin D-CDK4/6?","Rb releases E2F, allowing transcription of genes needed for S phase.","Libera E2F e o ciclo."],["1yr0l6n1u","How does p53 halt the cell cycle?","p53 induces p21, which inhibits CDKs, keeping Rb hypophosphorylated and stopping G1 to S progression.","Induz p21."],["1mt26db1s","What else does p53 do if DNA damage is irreparable?","Triggers apoptosis (e.g., via BAX).","Induz apoptose."],["1rsifti16","Which syndrome is caused by germline TP53 mutation?","Li-Fraumeni syndrome: sarcomas, breast cancer, leukemia, adrenal carcinoma, brain tumors (SBLA).","Li-Fraumeni."],["1v393fy3z","Which viral proteins inactivate Rb and p53 in HPV infection?","HPV E7 inhibits Rb; HPV E6 promotes p53 degradation.","E7 inibe Rb; E6 inibe p53."],["x2bez891q","Are tumor suppressor gene mutations usually dominant or recessive at the cellular level?","Recessive: both alleles must be lost (two-hit hypothesis).","Recessivas."],["jc9ou31hl","Are oncogene mutations usually dominant or recessive at the cellular level?","Dominant: one mutated allele is enough (gain of function).","Dominantes."],["1g71wel1y","What are permanent cells? Examples?","Cells that remain in G0 and cannot divide: neurons, skeletal muscle, cardiac muscle, RBCs.","Não se dividem; neurônios, músculo."],["1efba0s1p","What are stable (quiescent) cells? Examples?","Cells in G0 that can re-enter G1 when stimulated: hepatocytes, lymphocytes, proximal tubule cells, periosteal cells.","Dividem se preciso; fígado, rim."],["1gw1rp4f0","What are labile cells? Examples?","Continuously dividing cells: bone marrow, gut epithelium, skin, hair follicles, germ cells.","Sempre se dividem; medula, pele, intestino."],["8h6du713x","Why do chemotherapy side effects often affect hair, gut, and bone marrow?","These are labile, rapidly dividing cell populations.","Atinge células que se dividem."],["11czifu1s","What is the function of rough endoplasmic reticulum (RER)?","Synthesis of secretory, membrane, and lysosomal proteins; N-linked glycosylation begins here.","Sintetiza proteínas secretadas."],["1gne5x7xc","What are Nissl bodies?","RER in neurons; synthesize peptide neurotransmitters. Found in cell body and dendrites, not the axon.","RER dos neurônios."],["hizshi175","Which cells are rich in RER?","Cells that secrete proteins: plasma cells, goblet cells, pancreatic acinar cells.","Plasmócitos, células secretoras."],["1fy2h1a1r","What is the function of smooth endoplasmic reticulum (SER)?","Steroid synthesis, drug and poison detoxification, glycogen metabolism (glucose-6-phosphatase), calcium storage.","Lipídios e detoxificação."],["hj0ihj175","Which cells are rich in SER?","Liver hepatocytes and steroid-producing cells (adrenal cortex, gonads).","Fígado, adrenal, gônadas."],["1nm7nka9l","What is the function of the Golgi apparatus?","Distributes and modifies proteins and lipids from the ER: glycosylation, sulfation, adds mannose-6-phosphate to lysosomal proteins.","Modifica e distribui proteínas."],["gi6rdc1ys","What does the Golgi do to proteoglycans?","Assembles glycosaminoglycans onto core proteins and sulfates them.","Adiciona sulfato."],["yf11y98cf","What are endosomes?","Sorting centers for material from outside or inside the cell; can recycle receptors or send cargo to lysosomes.","Separam e reciclam."],["1bp3cgn1a","What is the cytoskeleton made of?","Microfilaments (actin), intermediate filaments, and microtubules.","Microfilamentos, intermediários, microtúbulos."],["1s9h5ovfn","What are the functions of actin microfilaments?","Muscle contraction, cytokinesis, microvilli, adherens junctions.","Movimento e contração."],["9rnayzlnd","Which intermediate filament stains connective tissue (mesenchymal) cells?","Vimentin.","Vimentina."],["z3rrpc1f4","Which intermediate filament stains muscle cells?","Desmin.","Desmina."],["1vsujfwro","Which intermediate filament stains epithelial cells?","Cytokeratin.","Citoqueratina."],["1a8e5ky10","Which intermediate filament stains astrocytes and other glial cells?","GFAP (glial fibrillary acidic protein).","GFAP."],["1jwnxe21u","Which intermediate filament stains neurons?","Neurofilaments.","Neurofilamentos."],["dphs5q163","Which intermediate filament is in the nuclear envelope?","Lamins (mutations cause progeria).","Lamina."],["b8y6bvyj5","What is the structure of a microtubule?","Cylinder of 13 protofilaments of alpha- and beta-tubulin heterodimers; each dimer binds 2 GTP.","Tubulina em 13 protofilamentos."],["t3xy4skly","What are microtubules used for?","Flagella, cilia, mitotic spindle, axonal transport, centrioles.","Transporte, mitose, cílios."],["18p18qf3s","What does dynein do?","Retrograde transport toward the minus end (toward the cell center/ nucleus).","Para o centro (retrógrado)."],["1wykhsreu","What does kinesin do?","Anterograde transport toward the plus end (toward the periphery).","Para a periferia (anterógrado)."],["wp7m211ph","Mnemonic for microtubule motor direction?","Dynein = retrograde to microtubule minus end. Kinesin = anterograde to plus end.","Dynein = dentro."],["ycmfw1f3x","Which drugs act on microtubules?","Mebendazole, griseofulvin, colchicine, vincristine/vinblastine, paclitaxel/taxanes. Mnemonic: Microtubules Get Constructed Very Poorly.","Colchicina, vincas, taxanos."],["qhci39ffb","How does colchicine work?","Binds tubulin and prevents microtubule polymerization, impairing neutrophil chemotaxis and degranulation (used in gout).","Inibe polimerização."],["7n6wkw1ya","How do vinca alkaloids differ from taxanes?","Vinca alkaloids block microtubule polymerization; taxanes stabilize microtubules and block depolymerization. Both stop mitosis.","Vinca impede montar; taxano impede desmontar."],["vbvzvl198","What is the structure of cilia?","9 + 2 arrangement of microtubule doublets (axoneme); basal body has 9 triplets.","9+2."],["hu9pz1tb5","What connects the outer microtubule doublets in cilia and enables bending?","Axonemal dynein (ATPase).","Dineína."],["7ngzbo323","What is the defect in primary ciliary dyskinesia?","Dynein arm defect causing immotile cilia (autosomal recessive).","Dineína defeituosa."],["1h5h9kev5","Clinical features of primary ciliary dyskinesia?","Male and female infertility, recurrent sinusitis, bronchiectasis, chronic ear infections, situs inversus in about half (Kartagener syndrome).","Infecções, infertilidade."],["12pr9s91f","What is Kartagener syndrome?","Primary ciliary dyskinesia with situs inversus.","Situs inversus com DCP."],["1q4pwgr7z","Why do patients with primary ciliary dyskinesia have reduced nasal nitric oxide?","Low nasal NO is a screening feature of the disease (used diagnostically).","Menor óxido nítrico."],["1wl6anh1k","Where is the Na+/K+-ATPase located and what does it pump?","Plasma membrane; pumps 3 Na+ out and 2 K+ in per ATP.","Membrana; 3 Na+ fora, 2 K+ dentro."],["xia38y1l3","Which drug class directly inhibits the Na+/K+-ATPase?","Cardiac glycosides (digoxin), which bind the K+ site.","Glicosídeos cardíacos."],["179l96t31","How does digoxin increase cardiac contractility?","Inhibits Na+/K+-ATPase, so less Na+/Ca2+ exchange occurs, intracellular Ca2+ rises, and contractility increases.","Mais cálcio intracelular."],["1nly7jf1w","Which drug inhibits the Na+/K+-ATPase by binding the K+ site, used mainly as a research tool?","Ouabain.","Ouabaína."],["1mgo4zfrm","What is the most abundant protein in the human body?","Collagen.","Colágeno."],["my5h5g1wp","What is the basic structure of collagen?","Triple helix of three alpha chains with repeating Gly-X-Y (X and Y often proline, hydroxyproline, hydroxylysine).","Tripla hélice Gly-X-Y."],["2z77uc126","Why is glycine every third residue in collagen?","Glycine is the smallest amino acid and fits in the tight core of the triple helix.","Cabe no centro da hélice."],["ok83uz1sf","Where is type I collagen found?","Bone, skin, tendon, dentin, fascia, cornea, late wound repair. Most common (90%).","Osso, pele, tendão."],["11nufv04l","Which disease involves decreased type I collagen production?","Osteogenesis imperfecta.","Osteogênese imperfeita."],["15dw7aav4","Where is type II collagen found?","Cartilage (including hyaline), vitreous body, nucleus pulposus. Mnemonic: cartwolage.","Cartilagem e vítreo."],["1sui7u3xa","Where is type III collagen found?","Reticulin: skin, blood vessels, uterus, fetal tissue, early granulation tissue.","Vasos, útero, cicatriz inicial."],["1ridjd21c","Which disease involves defective type III collagen?","Vascular Ehlers-Danlos syndrome.","Ehlers-Danlos vascular."],["hnhjulf61","Where is type IV collagen found?","Basement membrane, basal lamina, lens. Mnemonic: Type IV under the floor (basement membrane).","Membrana basal."],["yla3rzlqf","Which diseases involve type IV collagen?","Alport syndrome (defective) and Goodpasture syndrome (autoantibodies).","Alport e Goodpasture."],["l01weo14d","Mnemonic for collagen types I-IV?","Be (I) So (II) Totally (III) Cool, Read Books (IV): Bone, Skin; Cartilage; Reticulin; Basement membrane.","Ossos, cartilagem, vasos, membrana."],["6q1pibbz1","First step of collagen synthesis (intracellular)?","Translation of preprocollagen alpha chains on RER (usually Gly-X-Y).","Tradução no RER."],["gt75w21r2","What happens during hydroxylation of collagen?","Specific proline and lysine residues are hydroxylated in the RER; requires vitamin C.","Precisa de vitamina C."],["6re0hyur1","What disease results from impaired collagen hydroxylation?","Scurvy (vitamin C deficiency).","Escorbuto."],["s6ri3q1w5","What happens during collagen glycosylation?","Glucose and galactose are added to hydroxylysine residues; three alpha chains form procollagen via H- and disulfide bonds.","Adiciona açúcar."],["1si43cm17","Which disease involves a problem forming the procollagen triple helix?","Osteogenesis imperfecta.","Osteogênese imperfeita."],["p76yecqlz","What happens after procollagen is secreted?","Procollagen peptidases cleave the terminal regions, forming insoluble tropocollagen.","Clivagem das pontas."],["1jj2qq78t","Which disease involves defective procollagen peptidase cleavage?","Some forms of Ehlers-Danlos syndrome (dermatosparaxis type).","Ehlers-Danlos."],["1j9whcj1d","What enzyme cross-links tropocollagen into collagen fibrils?","Lysyl oxidase (copper-dependent), cross-linking lysine and hydroxylysine residues.","Lisil oxidase."],["ggx99t1nn","Which diseases involve problems with collagen cross-linking?","Menkes disease and some Ehlers-Danlos types.","Menkes e Ehlers-Danlos."],["o5i6ih17e","What is the most common form of osteogenesis imperfecta and its inheritance?","Type I, autosomal dominant, with decreased production of otherwise normal type I collagen (COL1A1 or COL1A2).","Tipo I; autossômica dominante."],["10jibv333","Clinical features of osteogenesis imperfecta?","Multiple fractures with minimal trauma, blue sclerae, hearing loss (abnormal ossicles), dental imperfections. Mnemonic: Bones, Eyes, Ears, Teeth (BITE).","Fraturas, escleras azuis, surdez."],["rk03ypi4b","Why are the sclerae blue in osteogenesis imperfecta?","The thin, translucent collagen lets the underlying choroidal veins show through.","Veias aparecem pelo colágeno fino."],["1rbklyl1x","What may osteogenesis imperfecta be confused with clinically?","Child abuse (multiple fractures).","Maus-tratos."],["1itj33113","Clinical features of Ehlers-Danlos syndrome?","Hyperextensible skin, hypermobile joints, easy bruising; may have joint dislocation, berry and aortic aneurysms, organ rupture.","Hipermobilidade e pele elástica."],["i8qzkuaiu","Which Ehlers-Danlos type is most common?","Hypermobility type (joint instability).","Hipermobilidade."],["1lfdr81ed","What is the inheritance and defect in classic Ehlers-Danlos syndrome?","Autosomal dominant; type V collagen (COL5A1/COL5A2).","AD; colágeno V."],["c23bt95x0","What is the inheritance and defect in vascular Ehlers-Danlos syndrome?","Autosomal dominant; type III collagen (COL3A1). Risk of vascular and organ rupture.","AD; colágeno III."],["1ppqr6pa7","What is the inheritance of Menkes disease?","X-linked recessive.","Ligada ao X."],["1y979jqai","What is the defect in Menkes disease?","Mutated ATP7A copper transporter causing impaired copper absorption and transport, so lysyl oxidase activity falls.","ATP7A, falta cobre."],["1da6azw1t","Clinical features of Menkes disease?","Brittle, kinky hair, growth retardation, hypotonia, seizures, low serum copper and ceruloplasmin, increased risk of cerebral aneurysms.","Cabelo crespo, atraso, hipotonia."],["x921jp1jj","What is elastin and where is it found?","Stretchy protein in skin, lungs, large arteries, elastic ligaments, vocal cords, ligamenta flava.","Fibra elástica; pele, pulmão, vasos."],["aag10t18p","What amino acids is elastin rich in?","Nonhydroxylated proline, glycine, and lysine residues.","Prolina, glicina, lisina."],["1iko1wq1g","How is elastin cross-linked?","Tropoelastin is cross-linked extracellularly by lysyl oxidase (desmosine cross-links), giving elasticity.","Desmosina."],["1w1ss1f1c","What scaffold is elastin built on?","Fibrillin, a glycoprotein that forms microfibrils.","Fibrilina."],["1jn4813zo","Which disease involves a defect in fibrillin-1?","Marfan syndrome (FBN1, chromosome 15, autosomal dominant).","Marfan."],["1sr5tpg2y","What breaks down elastin and what inhibits that enzyme?","Elastase; normally inhibited by alpha-1-antitrypsin.","Elastase; alfa-1-antitripsina."],["x5osnsofb","What happens when alpha-1-antitrypsin is deficient?","Unopposed elastase causes panacinar emphysema; misfolded protein accumulates in the liver causing cirrhosis.","Enfisema."],["1prffrqnc","What happens to elastic tissue with aging?","Elastin and collagen decrease, causing wrinkles (reduced dermal collagen and elastin).","Perde elasticidade."],["1k9yqd5oe","Clinical features of Marfan syndrome?","Tall with long extremities, arachnodactyly, joint laxity, pectus deformity, upward lens subluxation, cystic medial necrosis of aorta, mitral valve prolapse.","Alto, frouxo, cristalino, aorta."],["1237m8312","Most common cause of death in Marfan syndrome?","Aortic dissection or rupture (aortic root dilation).","Dissecção de aorta."],["db5rfph7g","What does a positive 'thumb sign' and 'wrist sign' suggest?","Arachnodactyly and joint laxity of Marfan syndrome.","Marfan."],["p5yu5v1pd","What is the main structural difference between apoptosis and necrosis?","Apoptosis is ATP-dependent programmed death without inflammation; necrosis is unregulated death with inflammation and loss of membrane integrity.","Apoptose sem inflamação."],["11oors1ll","Morphologic features of apoptosis?","Cell shrinkage, chromatin condensation (pyknosis), nuclear fragmentation (karyorrhexis), membrane blebs, apoptotic bodies, no inflammation.","Encolhe, condensa, fragmenta."],["11ef4xn75","What does the intrinsic (mitochondrial) pathway of apoptosis involve?","Loss of anti-apoptotic signals or DNA damage leads BAX/BAK to release cytochrome c from mitochondria, activating caspases.","Mitocôndria e citocromo c."],["qeknokn7b","What does BCL-2 do?","Anti-apoptotic: prevents cytochrome c release. Overexpressed in follicular lymphoma (t(14;18)).","Inibe apoptose."],["1j3tcmfxk","What does the extrinsic pathway of apoptosis involve?","Ligand-receptor interactions (FasL binding Fas, TNF binding its receptor) or cytotoxic T cell release of perforin and granzyme B.","Receptor de morte."],["op0m7pcxl","What do caspases do?","Proteases that execute apoptosis by cleaving cellular proteins and activating endonucleases.","Executam a apoptose."],["1a3v8wzrm","What is the role of Fas-FasL in the immune system?","Removes self-reactive lymphocytes (negative selection) and ends immune responses.","Eliminar linfócitos."],["louo3f3da","Which syndrome results from Fas mutation?","Autoimmune lymphoproliferative syndrome (ALPS).","Linfoproliferativa autoimune."],["1tzry5xky","What are tight junctions (zonula occludens)?","Junctions that prevent paracellular movement of solutes; made of claudins and occludins.","Vedam entre células."],["k6kruh9s6","What are adherens junctions (zonula adherens)?","Belt-like junctions below tight junctions connecting actin cytoskeletons via cadherins (Ca2+ dependent).","Ligam actina; caderinas."],["1qk9iu41g","What is the significance of losing E-cadherin in cancer?","Promotes metastasis (e.g., diffuse gastric cancer, lobular breast cancer).","Favorece metástase."],["tmj5ph1xs","What are desmosomes (macula adherens)?","Spot junctions linking keratin intermediate filaments of adjacent cells via cadherins.","Ancoram células."],["g3tfuqalk","Which disease involves autoantibodies against desmosomes?","Pemphigus vulgaris (anti-desmoglein 1 and 3).","Pênfigo vulgar."],["1fvkg2513","What are gap junctions?","Channels of connexons (connexins) allowing electrical and chemical communication between adjacent cells.","Comunicação entre células."],["wgodlk19x","What are hemidesmosomes?","Connect keratin in basal cells to the basement membrane (via integrins).","Ancoram à membrana basal."],["nnhoujg6p","Which disease involves autoantibodies against hemidesmosomes?","Bullous pemphigoid.","Penfigoide bolhoso."],["18o3gvb19","What do integrins do?","Membrane proteins that maintain basement membrane integrity by binding collagen, laminin, and fibronectin.","Ligam a matriz."],["1jhxjfk6l","What makes up the plasma membrane?","Asymmetric lipid bilayer with cholesterol, phospholipids, sphingolipids, glycolipids, and proteins.","Bicamada lipídica."],["uon9me16l","What effect does cholesterol have on membrane fluidity?","Buffers fluidity: decreases fluidity at high temperature and prevents rigidity at low temperature; increases rigidity overall.","Tampão de fluidez."],["1ktyez65f","What is the role of phosphatidylserine flipping to the outer leaflet?","Signals apoptotic cells for phagocytosis; also acts as a procoagulant surface on platelets.","Sinal de apoptose."],["2jtvy21qg","What does a positive Na+ gradient drive across membranes?","Secondary active transport, e.g., SGLT glucose uptake and Na+/Ca2+ exchange.","Transporte secundário."],["peyf3mdpn","Which molecules are glycosaminoglycans?","Long unbranched polysaccharides (e.g., heparan sulfate, chondroitin, dermatan, keratan sulfate, hyaluronic acid).","Ácido hialurônico, heparan, condroitina."],["23k8hk184","What are proteoglycans?","Core proteins with attached glycosaminoglycan chains; give tissues compressive resistance (e.g., cartilage aggrecan).","Proteína com GAGs."],["1vhbuj114","What does fibronectin do?","Extracellular glycoprotein that binds integrins and collagen, mediating cell adhesion and migration (important in wound healing).","Liga célula à matriz."],["lp8zly1fk","What does laminin do?","Major glycoprotein of the basement membrane, anchoring cells via integrins.","Componente da membrana basal."],["1w8cp251s","What is the main function of lysosomes?","Degradation of macromolecules by acid hydrolases (low pH ~4.5-5).","Degradação."],["37dgvcw6q","How is the lysosomal low pH maintained?","A vacuolar H+-ATPase pumps protons into the lysosome.","Bomba de prótons."],["1yh2poyf6","What are mitochondria responsible for?","Oxidative phosphorylation, TCA cycle, beta-oxidation, part of heme synthesis, part of urea cycle, apoptosis signaling.","ATP e apoptose."],["jg0ub11yz","How are mitochondrial diseases inherited and why?","Maternal inheritance, because mitochondria in the zygote come from the egg.","Herança materna."],["1tvb7sh1f","What is heteroplasmy?","Mixture of normal and mutant mitochondrial DNA in a cell, explaining variable severity of mitochondrial disease.","Mistura de mitocôndrias."],["1gm046u10","Which tissues are most affected by mitochondrial diseases and why?","Tissues with high energy demand: brain, skeletal muscle, heart.","Músculo e nervo."],["jyv54q198","What is the typical muscle biopsy finding in mitochondrial myopathies?","Ragged red fibers (accumulated abnormal mitochondria).","Fibras vermelhas rasgadas."],["eoy8sce4y","What is MELAS?","Mitochondrial encephalomyopathy, lactic acidosis, and stroke-like episodes.","Encefalopatia, acidose, AVC."],["1l88v61i6","What is Leber hereditary optic neuropathy?","Mitochondrial disease causing acute bilateral painless vision loss in young adults, often males.","Perda visual em jovens."],["13qmdiaso","Which bodies are found within the nucleus and make ribosomes?","Nucleoli.","Nucléolo."],["1ql6ghh1t","What does the nuclear pore complex do?","Regulates transport of molecules between nucleus and cytoplasm (e.g., mRNA export, protein import).","Transporte núcleo-citoplasma."],["u7rrn515d","What signal targets proteins to the nucleus?","Nuclear localization signal (short sequence rich in basic amino acids).","Sinal de localização nuclear."],["73csusscg","What is the function of the centrosome?","Main microtubule-organizing center; contains two centrioles and organizes the mitotic spindle.","Organiza o fuso."],["9pwjd0179","What happens in prophase?","Chromatin condenses into chromosomes, the mitotic spindle starts to form, nucleolus disappears.","Condensa cromossomos."],["1u6yrsk1d","What happens in metaphase?","Chromosomes line up at the metaphase plate; spindle checkpoint ensures attachment at kinetochores.","Alinha no centro."],["12tb2npgq","Why are karyotypes typically analyzed in metaphase?","Chromosomes are maximally condensed and visible; colchicine can be used to arrest cells in metaphase.","Cromossomos condensados."],["fuzg931ms","What happens in anaphase?","Sister chromatids separate and move to opposite poles.","Separa cromátides."],["17hy8hd1h","What happens in telophase and cytokinesis?","Nuclear envelopes re-form, chromosomes decondense, and the cytoplasm divides (actin-myosin contractile ring).","Divide a célula."],["dsrgc5jmr","What is nondisjunction?","Failure of homologous chromosomes or sister chromatids to separate, producing aneuploid cells.","Falha na separação."],["1s8np9s1i","Meiosis I vs meiosis II: what separates?","Meiosis I separates homologous chromosomes (reductional). Meiosis II separates sister chromatids (equational).","Homólogos vs cromátides."],["mlvqrvb2p","When does crossing over occur?","Prophase I of meiosis, between homologous chromosomes (chiasmata).","Prófase I."],["1hgdtp21a","At what stage are primary oocytes arrested until ovulation?","Prophase I (diplotene).","Prófase I."],["59jx4j1lb","At what stage are secondary oocytes arrested until fertilization?","Metaphase II.","Metáfase II."],["ajcvsv3f5","Which receptor type is used by insulin and growth factors?","Receptor tyrosine kinases (intrinsic tyrosine kinase activity).","Tirosina quinase."],["39yfvxm7n","Which hormones use the JAK/STAT pathway?","Non-receptor tyrosine kinase-associated receptors: prolactin, GH, cytokines (IL-2, IL-6, interferon), EPO, thrombopoietin, G-CSF. Mnemonic: PIGG(lets) with JAK.","Citocinas, GH, prolactina."],["r7529p9f5","Which second messenger system raises intracellular Ca2+ via IP3?","Gq (phospholipase C to IP3 and DAG).","Gq."],["ai7um11ru","Which second messenger is raised by Gs?","cAMP (adenylyl cyclase activation).","AMPc."],["1eo89e01x","What does Gi do?","Inhibits adenylyl cyclase, decreasing cAMP.","Reduz AMPc."],["10sxz261r","Which second messenger is used by ANP, BNP, and nitric oxide?","cGMP (ANP/BNP via receptor guanylyl cyclase; NO via soluble guanylyl cyclase).","GMPc."],["vs3gupj7w","Which hormones act through intracellular (nuclear) receptors?","Steroid hormones, thyroid hormone (T3/T4), vitamin D (and retinoic acid).","Esteroides e tireoide."]]},{"name":"Lab Techniques","cards":[["bccaevdxv","What is PCR used for?","Amplifying a specific DNA sequence; used for diagnosing infections, genetic disorders, and detecting mutations.","Amplificar DNA."],["1gyxx8s1w","What are the three main steps of each PCR cycle?","Denaturation (heat separates strands), annealing (primers bind), elongation (heat-stable DNA polymerase extends primers).","Desnatura, anela, estende."],["10frcgi3v","Why is a heat-stable DNA polymerase used in PCR?","It survives the high temperatures used for denaturation (e.g., Taq polymerase).","Aguenta o calor."],["8ve5sn19x","How many copies does PCR roughly make after n cycles?","About 2^n copies (exponential amplification).","2 elevado a n."],["r1ptqfoog","What does gel electrophoresis do?","Separates DNA (or proteins) by size; smaller fragments travel farther toward the positive electrode.","Separa por tamanho."],["b3tvsj3uz","Why does DNA move toward the positive electrode in gel electrophoresis?","The phosphate backbone makes DNA negatively charged.","DNA é negativo."],["xzof5evtf","What is reverse transcription PCR (RT-PCR) used for?","Detecting and quantifying RNA (e.g., viral load) by converting it to cDNA first.","Detectar e amplificar RNA."],["tatz2111x","What is quantitative (real-time) PCR used for?","Measuring the amount of a specific DNA or RNA in real time during amplification.","Quantificar DNA/RNA."],["aw265kw51","What does CRISPR/Cas9 do?","Guide RNA directs the Cas9 nuclease to a matching DNA sequence to make a double-strand break, allowing gene editing.","Corta DNA guiado por RNA."],["iz2vi42vo","How is the CRISPR break repaired to knock out a gene?","Nonhomologous end joining, which creates insertions/deletions that disrupt the gene.","Reparo com erro desliga o gene."],["1wdlq8p16","How can CRISPR insert a corrected sequence?","By providing a donor template, so the break is repaired by homologous recombination.","Reparo com molde."],["14lfhsi1d","What does a Southern blot detect?","DNA. Mnemonic: SNoW DRoP (Southern = DNA, Northern = RNA, Western = Protein).","DNA."],["3lg96wzq4","What does a Northern blot detect?","RNA (mRNA levels, gene expression).","RNA."],["1lj5i9e15","What does a Western blot detect?","Protein, using labeled antibodies.","Proteína."],["1yjywp31x","What does a Southwestern blot detect?","DNA-binding proteins (e.g., transcription factors), using labeled oligonucleotide probes.","Proteína que liga DNA."],["19ev7g02d","Basic steps of a Southern blot?","Cut DNA with restriction enzymes, run on gel, transfer to membrane, denature, hybridize with labeled probe, visualize bands.","Corta, separa, transfere, sonda."],["ubbkxrl1n","What is a restriction fragment length polymorphism (RFLP)?","Variation in DNA fragment lengths after restriction enzyme digestion, used to detect mutations or for genetic mapping.","Variação no tamanho dos fragmentos."],["1xmfr8fpq","Which diagnostic test was historically used to confirm HIV after a positive ELISA?","Western blot (now replaced by HIV-1/2 differentiation immunoassays).","Western blot."],["1f8je3c1y","What does ELISA detect?","Antigen or antibody in a patient sample, using an enzyme-linked antibody that produces a color change.","Antígeno ou anticorpo."],["wvka4w1ak","What is the difference between direct and indirect ELISA?","Direct: labeled antibody detects antigen. Indirect: patient antibody binds fixed antigen, then a labeled secondary antibody detects it.","Anticorpo primário vs secundário."],["eudqb61dj","Which ELISA format is very sensitive for antigen detection?","Sandwich ELISA (antigen captured between two antibodies).","Sanduíche."],["1jebaegwy","What is a microarray?","Thousands of nucleic acid sequences on a chip, hybridized with labeled sample DNA/RNA to detect expression levels or SNPs/CNVs.","Muitas sondas num chip."],["bt6gq5q3g","What are microarrays used to detect?","Gene expression profiles, single nucleotide polymorphisms, and copy number variations.","Expressão e variantes."],["6fb29n1b3","What is fluorescence in situ hybridization (FISH)?","A fluorescent DNA or RNA probe binds a specific chromosomal location to detect microdeletions, translocations, or duplications.","Sonda fluorescente no cromossomo."],["16yzu2h1n","What does absence of a FISH signal at a locus indicate?","A microdeletion (e.g., 22q11 in DiGeorge syndrome).","Deleção."],["l4cuez16l","What does FISH show in a translocation?","Signals from two different chromosomes appear fused or relocated together.","Sinais fundidos."],["104ep89i1","What is karyotyping?","Arranging metaphase chromosomes (arrested with colchicine) by size, shape, and banding to detect aneuploidy and large rearrangements.","Análise dos cromossomos."],["k18ncp187","What sample types can be used for karyotyping?","Blood, bone marrow, amniotic fluid, chorionic villi, or tumor tissue.","Sangue, medula, líquido amniótico."],["7izang8h4","What is Sanger sequencing based on?","Chain termination with fluorescent dideoxynucleotides (lack 3'-OH) during DNA synthesis.","Terminação por didesoxi."],["15f3nlo1x","What is next-generation sequencing?","Massively parallel sequencing of many DNA fragments at once; used for gene panels, exomes, and genomes.","Sequenciamento em massa."],["13atzawk8","What is cloning in molecular biology?","Producing a recombinant DNA molecule that is self-perpetuating, e.g., inserting a gene into a plasmid and growing bacteria.","Copiar DNA."],["k3rw4f7ic","Steps of gene cloning with cDNA?","Isolate mRNA, make cDNA with reverse transcriptase, insert into a plasmid vector, transform bacteria, select colonies with antibiotics.","mRNA, cDNA, vetor, bactéria."],["1gxe7r21i","Why is cDNA used to express eukaryotic genes in bacteria?","cDNA has no introns, and bacteria cannot splice.","Bactéria não remove íntrons."],["5yedch1kv","What is a transgenic animal?","An animal with an exogenous gene inserted into its genome (random insertion: constitutive expression).","Gene inserido."],["mmdm5i1fg","What is a knockout mouse?","A mouse in which a specific gene is inactivated or removed.","Gene desligado."],["dh884iqb6","What is a knock-in mouse?","A mouse in which a gene is inserted or replaced at a specific locus by targeted insertion.","Gene inserido no lugar."],["1n02idk1o","What is the Cre-lox system used for?","Conditional gene knockout or expression in specific tissues or at specific times.","Desligar gene em tecido específico."],["vpe7be17g","What is RNA interference used for experimentally?","Knocking down gene expression by introducing siRNA complementary to a target mRNA.","Silenciar genes."],["11m4xwy1u","What is flow cytometry used for?","Counting and characterizing cells using fluorescent antibodies against surface or intracellular proteins.","Analisar células por marcadores."],["1ksmvt6pi","What is a clinical use of flow cytometry in hematology?","Immunophenotyping leukemias/lymphomas and measuring CD4 counts in HIV.","Leucemias e linfomas."],["oyu331g1h","Which flow cytometry finding defines paroxysmal nocturnal hemoglobinuria?","Absence of CD55 and CD59 (GPI-anchored proteins) on RBCs.","Falta CD55 e CD59."],["1ia7hskdf","What does immunohistochemistry do?","Uses labeled antibodies on tissue sections to detect specific proteins in cells.","Proteína no tecido."],["1448734z0","What is a codominant genetic marker example?","Blood groups (A and B) or HLA alleles, where both alleles are expressed.","Grupo sanguíneo ABO."],["wqpjcb1l8","What does a positive Coombs (direct antiglobulin) test show?","Antibodies or complement bound to the patient's RBCs (immune hemolysis).","Anticorpo na hemácia."],["4k8341umr","What does the indirect Coombs test detect?","Antibodies in the patient's serum against RBC antigens (e.g., prenatal screening, crossmatching).","Anticorpo no soro."],["1wetjm61x","What is a Sanger sequencing limitation compared with NGS?","Sequences one fragment at a time; less efficient for large regions and poor at detecting low-level mosaic variants.","Menos sensível a mosaicos."],["1a6f22p1i","What is chromosomal microarray better at than karyotype?","Detecting submicroscopic deletions and duplications (copy number variants).","Detecta pequenas deleções."],["1fq1g181j","What is chromosomal microarray unable to detect?","Balanced translocations and inversions (no change in copy number).","Translocação balanceada."],["1br96k1t6","What is the purpose of a restriction enzyme?","Cuts DNA at specific palindromic sequences; bacterial defense against phages, used in molecular cloning.","Corta DNA em sítios."],["uexxbwfw0","What is a plasmid vector?","Circular DNA that replicates in bacteria, usually carrying an antibiotic resistance gene and cloning sites.","DNA circular carregador."],["1qc64wbkh","What is a probe in hybridization techniques?","A labeled single-stranded DNA or RNA complementary to the target sequence.","Sequência marcada."],["1s7rfv31o","What is the principle of DNA microarray comparative genomic hybridization?","Patient and reference DNA are labeled with different colors; ratios reveal gains or losses.","Compara DNA do paciente e controle."],["b5cad71mj","What is linkage analysis?","Tracking inheritance of genetic markers near a disease gene within families to locate the gene.","Gene herdado com marcador."],["1dfi3qfuq","What is a genome-wide association study (GWAS)?","Comparing SNPs across the genome in people with and without a disease to find associated variants.","Variantes comuns e doenças."],["1r1cgq3dz","What is the main use of whole exome sequencing?","Finding causative variants in protein-coding regions in suspected Mendelian diseases.","Achar variante causal."],["q0tz3u1sz","What does methylation-specific PCR detect?","Methylation status of a DNA region (e.g., imprinting disorders like Prader-Willi/Angelman).","Metilação do DNA."],["1oiazch1x","How can you diagnose fragile X syndrome molecularly?","Southern blot and/or PCR to measure CGG repeat number and methylation of FMR1.","Southern blot e PCR."],["q7ksyrhtf","Why is Southern blot used for large repeat expansions?","PCR may fail to amplify very long repeats; Southern blot sizes them.","PCR não amplifica bem."],["1drce1kt8","What is the principle of a radioimmunoassay?","Competitive binding of radiolabeled and unlabeled antigen to antibodies, used to measure hormone levels.","Competição com antígeno marcado."],["1l1e2dgrm","What does mass spectrometry measure in newborn screening?","Acylcarnitines and amino acids (e.g., MCAD deficiency, PKU, MSUD).","Metabólitos e aminoácidos."],["jl3zqgpyk","What technique separates proteins by charge (isoelectric point)?","Isoelectric focusing.","Focalização isoelétrica."],["1v32km9o6","Which technique separates hemoglobin variants such as HbS?","Hemoglobin electrophoresis (or HPLC).","Eletroforese de hemoglobina."],["1wojmm4s1","Why does HbS migrate slower toward the anode than HbA on electrophoresis?","Glutamate (negative) is replaced by valine (neutral), so HbS is less negative.","Perde carga negativa."],["184yha0vi","Order of hemoglobin migration (fastest to slowest toward anode)?","HbA > HbF > HbS > HbC. Mnemonic: A Fat Santa Claus.","A > F > S > C."],["ieay4l10e","Why does HbC move the slowest?","Glutamate is replaced by lysine (positive), making it the least negative.","Lisina positiva."],["19ujzme1k","What is a reporter gene and why is it used?","A gene with an easily measured product (e.g., luciferase, GFP) linked to a promoter to study gene expression.","Mostra expressão do gene."],["lb7l2911c","What is a dot blot?","Nucleic acids or proteins spotted directly onto a membrane without electrophoresis, then probed.","Amostra sem separação."],["tqk5sct8l","What is the Northern blot most useful for clinically or experimentally?","Studying mRNA levels and expression patterns (e.g., in tissue).","Expressão de RNA."],["1xhrfah83","What is the main advantage of PCR for infectious disease testing?","High sensitivity and rapid detection, even of organisms that are hard to culture.","Rápido e sensível."],["1v70t6q1t","What does cell-free fetal DNA testing screen for?","Fetal aneuploidies (trisomy 21, 18, 13) from maternal blood, usually after 10 weeks.","Aneuploidias fetais."]]},{"name":"Genetics (Part 1)","cards":[["1ugy62uhj","What is codominance? Give examples.","Both alleles contribute to the phenotype of the heterozygote. Examples: ABO blood groups (A and B), HLA groups, alpha-1-antitrypsin alleles.","Ambos alelos se expressam."],["1sqi87t1e","What is variable expressivity? Give an example.","Patients with the same genotype have varying severity of phenotype. Example: neurofibromatosis type 1 (some have few spots, others many tumors).","Gravidade varia; ex. NF1."],["m9kkh92vr","What is incomplete penetrance? Give an example.","Not all individuals with a mutant genotype show the phenotype. Example: BRCA1 mutation carriers do not all develop cancer.","Nem todos manifestam; ex. BRCA."],["o976m91it","What is pleiotropy? Give an example.","One gene contributes to multiple phenotypic effects. Example: untreated PKU causes light skin, intellectual disability, and musty odor.","Um gene, vários efeitos."],["kkblij124","What is anticipation? Give an example.","Increased severity or earlier onset of disease in successive generations. Example: trinucleotide repeat disorders like Huntington disease.","Piora a cada geração."],["1x751bd17","What is loss of heterozygosity? Give an example.","If a patient inherits or develops a mutation in a tumor suppressor gene, the remaining allele must be lost or mutated before cancer develops. Example: retinoblastoma.","Perde o alelo normal."],["1r1gonrhg","What is a dominant negative mutation? Give an example.","A mutant protein that interferes with the normal protein product of the other allele. Example: mutated p53 that cannot bind DNA but still binds normal p53.","Mutante inibe o normal."],["nn60wr1t1","What is linkage disequilibrium?","Tendency for certain alleles at two linked loci to occur together more or less often than expected by chance; measured in a population, not a family.","Alelos herdados juntos."],["183ylj6g7","What is mosaicism?","Presence of genetically distinct cell lines in the same individual.","Células com genótipos diferentes."],["eeyp1r1r1","What is somatic mosaicism vs gonadal mosaicism?","Somatic: mutation arises after fertilization and spreads through tissues. Gonadal: mutation only in egg or sperm cells, so parents may be unaffected but have several affected children.","Corpo vs gametas."],["9ck2ee568","What causes McCune-Albright syndrome?","Somatic mosaicism for an activating mutation in the G-protein alpha subunit (GNAS).","Mutação pós-zigótica GNAS."],["bzqa3h15f","Triad of McCune-Albright syndrome?","Unilateral cafe-au-lait spots with ragged edges (coast of Maine), polyostotic fibrous dysplasia, and endocrine overactivity (e.g., precocious puberty).","Café com leite, displasia óssea, puberdade precoce."],["143nlw412","Why is McCune-Albright syndrome only seen as mosaicism?","The mutation is lethal if present before fertilization (in every cell); it survives only in mosaic form.","Seria letal se em todas."],["hbayic1tj","What is locus heterogeneity? Give an example.","Mutations at different loci can produce a similar phenotype. Example: albinism.","Genes diferentes, mesmo quadro."],["1qyf8s01m","What is allelic heterogeneity? Give an example.","Different mutations at the same locus produce the same phenotype. Example: beta-thalassemia.","Mutações diferentes, mesmo gene."],["htvil01hk","Why can two siblings with the same mitochondrial mutation have very different disease severity?","Different proportions of mutant mitochondria (heteroplasmy) are distributed randomly to tissues during cell division.","Heteroplasmia."],["1dihqochf","What is uniparental disomy?","Offspring receives two copies of a chromosome from one parent and none from the other.","Dois cromossomos do mesmo pai."],["uw0kizsh0","Heterodisomy vs isodisomy?","Heterodisomy: two different homologs from one parent (meiosis I error). Isodisomy: two identical copies of one homolog from one parent (meiosis II error or postzygotic duplication).","Cromossomos diferentes vs iguais."],["zoyrjak3b","What should you suspect when a recessive disorder occurs in a child with only one carrier parent?","Uniparental isodisomy.","Dissomia uniparental."],["uxkmw3awl","Is uniparental disomy usually euploid?","Yes; it is euploid (correct number of chromosomes), so most cases are normal phenotypically unless imprinted or recessive genes are involved.","Sim."],["14fx3qq1e","What does the Hardy-Weinberg principle assume?","No mutation at the locus, no natural selection, completely random mating, no net migration, and a large population.","População grande e estável."],["84ny1snb0","Hardy-Weinberg equations?","p + q = 1 and p^2 + 2pq + q^2 = 1, where p and q are allele frequencies.","p + q = 1; p² + 2pq + q² = 1."],["1cdp82t4k","In Hardy-Weinberg, what does 2pq represent?","The frequency of heterozygotes (carriers).","Portadores."],["7yj9c513o","If a recessive disease has an incidence of 1/10,000, what is the approximate carrier frequency?","q^2 = 1/10,000, so q = 1/100; carrier frequency 2pq is about 2 x 1/100 = 1/50.","1/50."],["1rwllasoc","In Hardy-Weinberg, what is the frequency of an X-linked recessive disease in males?","q (the allele frequency).","q."],["1enc5sn19","In Hardy-Weinberg, what is the frequency of an X-linked recessive disease in females?","q^2.","q²."],["joh7rv1ri","What is genomic imprinting?","At some loci only one allele is active; the other is inactive (imprinted/silenced by methylation). Deletion of the active allele causes disease.","Expressão depende do pai de origem."],["188igmbxy","Which chromosome region is involved in Prader-Willi and Angelman syndromes?","15q11-q13.","15q11-13."],["p31mqn1tc","Which parental allele is lost or silenced in Prader-Willi syndrome?","The paternal allele is deleted or mutated; the maternal gene is normally silenced (imprinted).","Paterno."],["1rb6fi310","What uniparental disomy causes Prader-Willi syndrome?","Maternal uniparental disomy of chromosome 15 (two maternally imprinted copies), about 25% of cases.","Materna."],["bchuys1fe","Clinical features of Prader-Willi syndrome?","Hyperphagia, obesity, intellectual disability, hypogonadism, hypotonia (neonatal), short stature, small hands and feet.","Obesidade, hipotonia, hipogonadismo."],["bp80pi3re","Which parental allele is lost or silenced in Angelman syndrome?","The maternal UBE3A allele is deleted or mutated; the paternal UBE3A is normally silenced.","Materno."],["1sbpl6ayt","What uniparental disomy causes Angelman syndrome?","Paternal uniparental disomy of chromosome 15, in about 5% of cases.","Paterna."],["115eux9ut","Clinical features of Angelman syndrome?","Inappropriate laughter (happy puppet), seizures, ataxia, severe intellectual disability, absent speech.","Riso, convulsões, ataxia."],["15hkjq01r","Mnemonic to remember imprinting in Prader-Willi vs Angelman?","Prader-Willi: Paternal deletion. AngelMan: Maternal deletion.","Prader = pai ausente; AngelMan = mãe."],["1263rkd13","Key features of autosomal dominant inheritance in a pedigree?","Affected individuals in every generation, males and females equally, transmission from either parent, 50% risk for each child of an affected heterozygote.","Todas gerações, ambos sexos."],["123pvyr1b","Why do autosomal dominant diseases often present later in life?","Many involve structural proteins or receptors and have variable onset; family history is crucial.","Sintoma tardio permite reprodução."],["15iwd301o","Key features of autosomal recessive inheritance in a pedigree?","Often seen in one generation only (skips generations), equal sexes, more common with consanguinity, 25% risk if both parents are carriers.","Pula gerações; pais portadores."],["1nfhctvej","Why do autosomal recessive diseases tend to be more severe and present early?","They usually involve loss of enzyme function, often presenting in childhood.","Perda de enzima."],["1n42dth1n","Risk that an unaffected sibling of a child with an AR disease is a carrier?","2/3 (since the sibling is known not to be affected).","2/3."],["7nayb41vy","Key features of X-linked recessive inheritance?","Mostly males affected, no male-to-male transmission, sons of heterozygous mothers have 50% risk, daughters of affected fathers are all carriers.","Homens; sem transmissão pai-filho."],["7owjz9m99","Why can female carriers of X-linked recessive diseases be affected?","Skewed X-inactivation (lyonization), Turner syndrome (XO), or homozygosity.","Inativação desfavorável do X."],["1mtu3q9gw","Key features of X-linked dominant inheritance?","Transmitted by both parents; all daughters but no sons of an affected father are affected; mothers transmit to 50% of sons and daughters.","Pai afetado passa a todas as filhas."],["1nmsdlb3f","Name examples of X-linked dominant diseases.","Hypophosphatemic rickets (vitamin D-resistant rickets), fragile X syndrome, Alport syndrome (most forms), Rett syndrome.","Raquitismo hipofosfatêmico, Rett."],["1s23i0xpg","What is the defect in X-linked hypophosphatemic rickets?","Increased phosphate wasting at the proximal tubule (PHEX mutation, high FGF23), causing rickets-like presentation.","Perda renal de fosfato."],["1iywonc1r","Key features of mitochondrial inheritance?","Transmitted only through the mother; all offspring of an affected mother may show signs, with variable expression due to heteroplasmy.","Só pela mãe."],["tq9vzr1nm","What is X-inactivation (lyonization)?","Random inactivation of one X chromosome in each female cell early in development, forming a Barr body.","Um X desativado."],["10rtiqg19","Which gene initiates X-inactivation?","XIST (produces a noncoding RNA that coats the inactive X).","XIST."],["ir3jhj1cy","What does consanguinity increase the risk for?","Autosomal recessive diseases (and some multifactorial disorders), due to shared alleles.","Doenças recessivas."],["1jk4fwj27","What is a de novo mutation?","New mutation in an affected child that is not present in either parent; common in AD disorders like achondroplasia.","Mutação nova."],["vy7aci1ro","What is the association between de novo mutations and paternal age?","Advanced paternal age increases the risk of new point mutations (e.g., achondroplasia, Marfan, Apert).","Mutações pontuais."],["wrnjgc1ow","What is the association between maternal age and aneuploidy?","Advanced maternal age increases nondisjunction (e.g., trisomy 21).","Não disjunção."],["jb0c3f1r8","What is a multifactorial disorder?","Disease caused by combined effects of multiple genes and environmental factors (e.g., cleft lip, neural tube defects, pyloric stenosis).","Genes mais ambiente."],["vb0m4y4ed","What is the risk pattern of multifactorial disorders in relatives?","Risk is highest in first-degree relatives and increases with more affected relatives and more severe disease.","Maior em parentes próximos."],["1jja54r5l","What is penetrance?","The proportion of individuals with a genotype who express the phenotype.","Fração que manifesta."],["15ks8i31b","What is expressivity?","The degree or severity with which a phenotype is expressed in an individual.","Grau de manifestação."],["1ucu9ink5","What is a proband?","The first affected family member who brings the family to medical attention (index case).","Caso índice."],["1s9xmft1j","What does a square, circle, and filled shape mean in a pedigree?","Square = male, circle = female, filled = affected.","Homem, mulher, afetado."],["1yew1wse3","What does a double line between partners mean in a pedigree?","Consanguineous union.","Consanguinidade."],["hdz982ex7","What is a germline mutation vs a somatic mutation?","Germline: present in egg or sperm, inherited, in every cell. Somatic: acquired after conception, only in some cells, not inherited.","Herdável vs não herdável."],["whrmts1we","What is a frameshift vs in-frame deletion?","Frameshift: deletion not divisible by 3, changes reading frame. In-frame: deletion of multiple of 3, removes amino acids but keeps the frame.","Muda vs mantém leitura."],["1wv8f4eql","What is a balanced translocation?","Exchange of chromosome segments without loss or gain of genetic material; carrier usually normal but at risk for unbalanced offspring.","Sem perda de material."],["1xj2opedb","What is a reciprocal translocation?","Exchange of segments between two nonhomologous chromosomes.","Troca entre cromossomos."],["wn0nk4gh2","What is a Robertsonian translocation?","Fusion of the long arms of two acrocentric chromosomes (13, 14, 15, 21, 22) at the centromere, with loss of short arms.","Fusão de acrocêntricos."],["12tb1fpqv","Why can a Robertsonian translocation carrier be phenotypically normal?","The lost short arms contain only rRNA genes, which are present on other chromosomes.","Sem perda de material relevante."],["5k9pv61xo","Which chromosomes are acrocentric in humans?","13, 14, 15, 21, 22.","13, 14, 15, 21, 22."],["1pzoriu11","What is the significance of a 14;21 Robertsonian translocation?","Carriers are normal but have high risk of offspring with translocation Down syndrome.","Risco de Down na prole."],["1fz8hw8oa","What is an inversion?","A segment of a chromosome is reversed; paracentric does not include the centromere, pericentric includes it.","Segmento invertido."],["zt13kug27","Why can inversions cause problems in offspring?","Abnormal crossing over in meiosis can create unbalanced gametes with deletions/duplications.","Gametas desequilibrados."],["18s6zy118","What is a ring chromosome?","Chromosome whose ends are lost and fused to form a ring; e.g., some Turner syndrome cases.","Pontas unidas em anel."],["dseosw1lt","What is an isochromosome?","Chromosome formed by duplication of one arm and loss of the other (e.g., isochromosome Xq in Turner syndrome).","Dois braços iguais."],["l4eiqtvbv","What is a microdeletion?","Small deletion below karyotype resolution, detected with FISH or microarray.","Deleção pequena."],["1ol6q4a1r","What is aneuploidy vs polyploidy?","Aneuploidy: abnormal number of individual chromosomes (e.g., 47). Polyploidy: whole extra sets (e.g., triploidy 69 chromosomes).","Um cromossomo vs conjunto."],["or0davsmm","What causes triploidy (69,XXX or 69,XXY)?","Fertilization of an egg by two sperm or a diploid gamete; seen in partial hydatidiform mole.","Dois espermatozoides."],["zhhyc71kn","What is the most common cause of trisomy 21?","Meiotic nondisjunction, most often maternal meiosis I (about 95% of cases).","Não disjunção materna."],["v1f5a3ev9","What proportion of trisomy 21 is due to Robertsonian translocation?","About 4%.","4%."],["ilytvl53c","What proportion of trisomy 21 is mosaic?","About 1%, due to mitotic error; usually milder phenotype.","1-2%."],["kz82ua19v","What is the recurrence risk of Down syndrome due to nondisjunction?","Low; increases with maternal age (about 1% plus age-related risk).","Cerca de 1%."],["1b5tbgeey","What is genetic anticipation's mechanism in Huntington disease?","CAG repeats expand during spermatogenesis, so paternal transmission leads to earlier onset.","Expansão CAG."],["na7lks1uy","In which parent do fragile X CGG repeats tend to expand?","During maternal transmission (oogenesis).","Mãe."],["1c3b37usw","In which parent do myotonic dystrophy CTG repeats tend to expand into the congenital form?","Maternal transmission (congenital myotonic dystrophy).","Mãe."],["1lxodh3xf","Which trinucleotide repeat diseases are there and their repeats?","Huntington (CAG), myotonic dystrophy (CTG), fragile X (CGG), Friedreich ataxia (GAA).","Huntington, X frágil, distrofia, Friedreich."],["n2gv9k1g9","Mnemonic for trinucleotide repeats?","Try (trinucleotide) hunting for my fragile cagged free eggs (X): Huntington CAG, Myotonic CTG, Fragile X CGG, Friedreich GAA.","Mnemônico das repetições."],["r7w51v60o","Which trinucleotide repeat disease is autosomal recessive?","Friedreich ataxia (GAA repeat in frataxin gene).","Ataxia de Friedreich."],["zjh0yx1wq","What is the inheritance of fragile X syndrome?","X-linked dominant (with variable penetrance and expression); trinucleotide repeat in FMR1.","Ligada ao X dominante."],["1vc2hu81n","What is a premutation in fragile X?","55-200 CGG repeats; carriers are at risk of fragile X tremor/ataxia syndrome (FXTAS) and premature ovarian failure.","55-200 repetições."],["17w52xa1a","What number of CGG repeats is a full fragile X mutation?","More than 200 repeats, with methylation and silencing of FMR1.","Mais de 200."],["1xrhrf7cw","What is a frameshift in the context of DMD?","Deletion causing loss of reading frame in the dystrophin gene, producing a truncated or absent protein.","Muda leitura; Duchenne."],["m7nqdl1oi","What is the most common inheritance for metabolic enzyme deficiencies?","Autosomal recessive (most inborn errors of metabolism).","Autossômica recessiva."],["lo1xgr164","What are the exceptions: X-linked recessive metabolic disorders?","Fabry disease, Hunter syndrome, Lesch-Nyhan syndrome, OTC deficiency, G6PD deficiency, Menkes disease, pyruvate dehydrogenase deficiency (E1 alpha), Bruton agammaglobulinemia (immune).","Fabry, Hunter, OTC, Lesch-Nyhan."],["fzmuf112h","Mnemonic for X-linked recessive disorders?","Ornithine Transcarbamylase deficiency, Bruton, Wiskott-Aldrich, Fabry, G6PD, Ocular albinism, Lesch-Nyhan, Duchenne/Becker, Hunter, Hemophilia A and B. 'Oblivious Female Will Often Give Her Boys Her x-Linked Disorders'.","Mnemônico do X recessivo."],["6ekckg1no","How is the probability of a child being affected calculated when a mother is a carrier for X-linked recessive disease?","Each son has 50% risk of being affected; each daughter has 50% risk of being a carrier.","50% dos filhos."],["xnuq201pd","If an affected male (XR disease) has children with a non-carrier female, what are the outcomes?","All sons unaffected; all daughters obligate carriers.","Filhas portadoras; filhos sadios."],["13xib9q1x","What is the Bayesian approach used for in genetic counseling?","Updating carrier or disease risk using conditional information such as unaffected children or negative test results.","Calcula risco real."],["ooxl193j4","What is a founder effect?","High frequency of a genetic variant in a population descended from a small group of ancestors (e.g., Tay-Sachs in Ashkenazi Jews).","Mutação comum em população isolada."],["gq5w34117","What is genetic drift?","Random changes in allele frequency, most pronounced in small populations.","Mudança aleatória."],["vqn0p914r","What is heterozygote advantage? Example?","Carriers of a recessive allele have a survival advantage. Example: sickle cell trait protects against Plasmodium falciparum malaria.","Portador tem vantagem; malária."],["mxt99k7oz","Which other recessive diseases may have heterozygote advantage?","Possibly cystic fibrosis carriers against cholera/typhoid; G6PD deficiency and thalassemia traits against malaria.","Fibrose cística, talassemia."],["ulaldl5ec","What is the 'two-hit' hypothesis?","Both alleles of a tumor suppressor gene must be inactivated for tumor development; hereditary cases inherit one hit.","Duas mutações para o câncer."],["21sjtyqhl","Why are hereditary retinoblastomas often bilateral and early?","Every cell already has one mutated RB1 allele (first hit inherited), so only one somatic hit is needed.","Primeira mutação herdada."],["10lf8631o","What is genetic imprinting disorder Beckwith-Wiedemann syndrome?","Overgrowth disorder from abnormal imprinting at 11p15 (IGF2 overexpression): macroglossia, organomegaly, omphalocele, hemihyperplasia, hypoglycemia, Wilms tumor risk.","Imprinting em 11p15."],["1vsuuyhez","What is meant by 'sex-limited' inheritance?","Autosomal traits expressed only in one sex (e.g., male-limited precocious puberty).","Expressa em um sexo."],["1one03tug","What does 'obligate carrier' mean?","A person who must carry a mutation based on the pedigree (e.g., daughter of a male with an X-linked recessive disorder).","Certamente portador."],["gd62wain5","What is an X-linked recessive disease's typical pedigree clue?","Affected males connected through unaffected females (maternal uncles, grandsons).","Homens afetados."],["129yvte1h","What pattern suggests mitochondrial inheritance over X-linked inheritance?","Affected mother transmits to both sons and daughters; affected father never transmits.","Transmissão só materna."],["14xue3f1k","How does a dominant negative mutation differ from haploinsufficiency?","Dominant negative: mutant protein actively interferes with the normal one. Haploinsufficiency: one functional copy is not enough to make adequate product.","Inibe o normal vs falta dose."],["fj4pld8ad","Give an example of haploinsufficiency.","Familial hypercholesterolemia (one LDL receptor allele mutated reduces receptor number), or some forms of Marfan syndrome.","Hipercolesterolemia familiar."],["1icjehz1u","What is a gain-of-function mutation? Example?","A mutation giving the protein a new or enhanced function, usually dominant. Example: Huntington disease, achondroplasia (FGFR3 activation).","Ganha função; ex. acondroplasia."],["5c3xs51j3","What is a loss-of-function mutation? Example?","A mutation reducing or abolishing protein function, usually recessive. Example: most enzyme deficiencies.","Perde função; ex. supressor."],["1lm1fbyqm","What is the difference between a carrier test and a diagnostic test?","Carrier test detects heterozygotes for recessive conditions in unaffected people; diagnostic test confirms disease in a symptomatic person.","Portador vs doente."],["2grsfe1ez","What is the purpose of prenatal chorionic villus sampling vs amniocentesis?","CVS: 10-13 weeks, placental tissue. Amniocentesis: 15-20 weeks, fetal cells in amniotic fluid. Both give fetal karyotype/DNA.","Precoce vs mais seguro."],["v3nvno1q9","Which test results are typical of the first-trimester screen for trisomy 21?","Low PAPP-A, high beta-hCG, and increased nuchal translucency.","hCG alto, PAPP-A baixa, translucência alta."],["1izt3ih1u","What is the quad screen pattern for trisomy 21?","Low AFP, high beta-hCG, low estriol, high inhibin A. (HI: hCG and Inhibin high).","AFP baixa, hCG alto, estriol baixo, inibina alta."],["1izszmr1u","What is the quad screen pattern for trisomy 18?","Low AFP, low beta-hCG, low estriol, normal or low inhibin A.","Tudo baixo."],["1evmpmoqz","What does elevated maternal serum AFP suggest?","Neural tube defects, ventral wall defects (omphalocele, gastroschisis), multiple gestation, or incorrect dating.","Defeito de tubo neural."],["xky4js1vv","What does decreased maternal serum AFP suggest?","Chromosomal abnormalities (trisomy 21, trisomy 18).","Aneuploidia."],["1cptpaq1k","What is the difference between expressivity and penetrance in a sentence?","Penetrance is whether a genotype shows any phenotype (all or none); expressivity is how severe it is when it shows.","Grau vs presença."],["1g2mmu5og","What does 'de novo dominant' mean for recurrence risk?","Recurrence risk for siblings is low (but slightly above population due to possible gonadal mosaicism); affected individual's children have 50% risk.","Risco baixo."],["1kxquhwsz","What is the recurrence risk for siblings in gonadal mosaicism?","Higher than population (e.g., several percent), although parents are unaffected.","Risco aumentado."],["uzxsv1nmt","What does a Punnett square for two heterozygous carriers of an AR disease predict?","1/4 affected, 1/2 carriers, 1/4 noncarriers.","25% doente."],["3cvln51gv","What is a compound heterozygote?","Individual with two different pathogenic mutations in the same gene (one on each allele), causing AR disease.","Dois alelos mutados diferentes."],["8c3edp1vw","What is digenic inheritance?","Disease requires mutations in two different genes simultaneously (rare; e.g., some retinitis pigmentosa).","Dois genes necessários."],["63gn1q15n","What does 'dominant' or 'recessive' describe, the gene or the trait?","The trait (phenotype); genes are described as alleles that produce dominant or recessive traits.","O traço."],["7phsni1vi","What does 'semidominant' or 'incomplete dominance' mean? Example?","Heterozygote has an intermediate phenotype. Example: familial hypercholesterolemia (homozygotes much more severe), achondroplasia (homozygous lethal).","Heterozigoto intermediário."],["18dcr4yyz","Why is homozygous achondroplasia lethal?","Two activating FGFR3 alleles cause severe skeletal dysplasia with small thorax and respiratory failure.","Duas cópias mutadas."],["1l73epe1f","What is a chromosomal deletion in the shorthand '46,XY,del(5p)'?","Male with deletion of part of the short arm of chromosome 5 (cri-du-chat syndrome).","Deleção do braço curto."],["70w70917q","In cytogenetic notation, what do p and q refer to?","p = short arm (petite); q = long arm.","Braço curto e longo."],["1qu8kq0kq","What is the purpose of the newborn screening program?","Early detection of treatable genetic/metabolic disorders (e.g., PKU, hypothyroidism, CF, sickle cell) to prevent harm.","Detectar e tratar cedo."],["ixla491pz","What genetic concept explains why a woman with Turner syndrome can have an X-linked recessive disease?","She has only one X chromosome, so a single mutant allele causes disease (hemizygosity).","Só um X."],["18b8v1q38","What does hemizygous mean?","Having only one copy of a gene, as with X-linked genes in males.","Um X nos homens."],["louwhk1t1","What is a pseudoautosomal region?","Regions at the tips of X and Y that pair and recombine during meiosis, inherited like autosomes (e.g., SHOX).","Região pareada X-Y."],["5dmekuncn","Which gene deletion in the pseudoautosomal region contributes to short stature in Turner syndrome?","SHOX.","SHOX."],["1w9ns6k1q","What is the Lyon hypothesis in females heterozygous for G6PD deficiency?","Random X-inactivation creates mosaic RBC populations; some carriers have hemolysis depending on the proportion.","Expressão em mosaico."],["1ot8msxbq","What explains a female presenting with Duchenne-like features?","Skewed X-inactivation in a carrier, Turner syndrome, or X-autosome translocation disrupting the dystrophin gene.","X inativado desfavorável."],["iyfekq18m","How can an AD disease appear to skip a generation?","Incomplete penetrance or variable expressivity (mildly affected parent not recognized).","Penetrância incompleta."],["1wlcivn15","What is phenocopy?","An environmentally caused phenotype that mimics a genetic disease (e.g., thalidomide limb defects mimicking a genetic syndrome).","Ambiente imita doença."],["f1us0p1vi","What is epistasis?","When one gene's expression masks or modifies the effect of another gene.","Um gene altera outro."],["10a0en41h","What is the purpose of cascade testing?","Testing relatives of a person with a known pathogenic variant (e.g., BRCA, familial hypercholesterolemia) to identify carriers.","Testar parentes."],["rmy5nq132","What is a variant of uncertain significance (VUS)?","A genetic variant whose effect on disease risk is unknown; it should not change management on its own.","Variante de significado incerto."],["2ngpnzki8","What is genetic counseling's key ethical principle regarding test results for minors?","Generally avoid testing children for adult-onset conditions without treatment (e.g., Huntington) until they can decide themselves.","Esperar a maioridade."],["40f0szgjs","What federal law in the US prohibits genetic discrimination in health insurance and employment?","GINA (Genetic Information Nondiscrimination Act). It does not cover life, disability, or long-term care insurance.","GINA."],["1bwcbsy1c","What is an euploid individual?","Cell or individual with a normal multiple of the haploid chromosome number (e.g., 46 in humans).","Número normal."],["1dchkvo1u","What is a haploid number in humans?","23 (gametes).","23."],["1t9x4nzpp","What is the threshold effect in mitochondrial disease?","Symptoms appear only when the fraction of mutant mitochondrial DNA in a tissue exceeds a critical level.","Proporção mínima causa doença."],["lqlxh8122","What is the recurrence risk for a child of an affected father with a mitochondrial disease?","Essentially zero, because paternal mitochondria are not transmitted.","Quase zero."],["1096kwllr","What is a chromosomal duplication and its usual effect?","Extra copy of a chromosome segment; usually milder than a deletion of the same region.","Cópia extra; menos grave."],["xqr9zn17k","What is a contiguous gene syndrome?","A deletion or duplication that affects several adjacent genes, producing a combined phenotype (e.g., Williams, 22q11).","Deleção de vários genes."],["2xpgk31fh","What is meant by 'genetic heterogeneity' in deafness?","Many different genes (locus heterogeneity) can cause the same phenotype of hereditary hearing loss.","Vários genes causam."],["1dqh0xo18","What is the purpose of preimplantation genetic testing?","Testing embryos created by IVF for a known familial mutation or aneuploidy before transfer.","Escolher embrião saudável."],["16x3ani1y","What is the main difference between a screening test and a diagnostic genetic test in pregnancy?","Screening (e.g., cell-free DNA, quad screen) estimates risk; diagnostic tests (CVS, amniocentesis) give a definitive fetal genotype/karyotype.","Risco vs certeza."]]},{"name":"Genetics (Part 2)","cards":[["1vv2jtfl6","Gene and chromosome in autosomal dominant polycystic kidney disease?","PKD1 (chromosome 16, more common, more severe) or PKD2 (chromosome 4).","PKD1 (16) ou PKD2 (4)."],["k6ooo11dm","Clinical features of ADPKD?","Bilateral enlarged kidneys with cysts, flank pain, hematuria, hypertension, progressive renal failure; liver cysts, berry aneurysms, mitral valve prolapse.","Rins grandes, hipertensão, hematúria."],["104h82y1u","Which ADPKD-associated lesion can cause subarachnoid hemorrhage?","Berry (saccular) aneurysms in the circle of Willis.","Aneurisma sacular."],["1aeylawk3","Gene and chromosome in familial adenomatous polyposis?","APC tumor suppressor gene on chromosome 5q.","APC, cromossomo 5."],["pr1kosxmw","Clinical features of familial adenomatous polyposis?","Hundreds to thousands of colon polyps starting after puberty; colon cancer in essentially 100% without colectomy.","Centenas de pólipos; câncer certo."],["18rzfx21a","What is Gardner syndrome?","FAP with osteomas, soft tissue tumors (desmoids), epidermoid cysts, and impacted/supernumerary teeth.","PAF com osteomas e tumores moles."],["zw7d9w1e2","What is Turcot syndrome?","FAP or Lynch syndrome with CNS tumors (medulloblastoma or glioma).","PAF com tumor cerebral."],["inizvzink","Defect in familial hypercholesterolemia?","Absent or defective LDL receptor (or ApoB-100, PCSK9 gain of function), autosomal dominant.","Receptor de LDL."],["c3r3hw147","Clinical features of heterozygous familial hypercholesterolemia?","Cholesterol about 300 mg/dL, tendon xanthomas (Achilles), corneal arcus, premature atherosclerosis.","LDL alto, xantomas, IAM precoce."],["axqyz41gp","Clinical features of homozygous familial hypercholesterolemia?","Cholesterol often >700 mg/dL, severe atherosclerosis and MI in childhood/ adolescence.","IAM na infância."],["1i31x112g","What is hereditary hemorrhagic telangiectasia (Osler-Weber-Rendu)?","AD disorder of blood vessels (ENG or ACVRL1): telangiectasias, recurrent epistaxis, skin discoloration, AVMs (lung, brain, liver), GI bleeding.","Telangiectasias e sangramentos."],["xydwpf113","What is the defect in hereditary spherocytosis?","Defect in RBC membrane proteins (spectrin, ankyrin, band 3, protein 4.2), usually autosomal dominant.","Espectrina e anquirina."],["1h8fj8p1e","Clinical features of hereditary spherocytosis?","Hemolytic anemia, jaundice, splenomegaly, pigmented gallstones, increased MCHC, positive osmotic fragility/EMA binding test.","Anemia, icterícia, esplenomegalia."],["1p8v5ph11","Treatment of hereditary spherocytosis?","Splenectomy in moderate/severe cases (after vaccination).","Esplenectomia."],["t6gzcx4b6","Gene and chromosome in Huntington disease?","HTT on chromosome 4; CAG repeat expansion, autosomal dominant.","HTT, cromossomo 4."],["6xqkpx1vu","Clinical features of Huntington disease?","Chorea, athetosis, aggression, depression, dementia, onset usually 20-50 years.","Coreia, demência, depressão."],["bn7aeo1pb","Which brain area atrophies in Huntington disease?","Caudate nucleus (and putamen) with ex vacuo ventriculomegaly.","Caudado."],["1u8hifdqy","Which neurotransmitter changes occur in Huntington disease?","Decreased GABA and acetylcholine, increased dopamine in the striatum.","Menos GABA e ACh, mais dopamina."],["14pz0na35","Gene in Li-Fraumeni syndrome?","TP53 (chromosome 17p), autosomal dominant.","TP53."],["17yx1lp11","Gene and chromosome in Marfan syndrome?","FBN1 on chromosome 15 (fibrillin-1), autosomal dominant.","FBN1, cromossomo 15."],["z0g3r01rj","Gene in multiple endocrine neoplasia type 1?","MEN1 (menin) tumor suppressor on chromosome 11.","MEN1 (menina)."],["1xl4rrcxv","Tumors in MEN1?","Pituitary, parathyroid, pancreatic (and duodenal) endocrine tumors. The 3 Ps.","Paratireoide, hipófise, pâncreas."],["1pww6n01v","Gene in MEN2A and MEN2B?","RET proto-oncogene on chromosome 10.","RET."],["ndrlvu1gn","Tumors in MEN2A?","Medullary thyroid carcinoma, pheochromocytoma, parathyroid hyperplasia.","Paratireoide, feocromocitoma, medular."],["ndrlyh1gn","Tumors in MEN2B?","Medullary thyroid carcinoma, pheochromocytoma, mucosal neuromas, marfanoid habitus.","Medular, feocromocitoma, neuromas."],["1gajvk915","Why is prophylactic thyroidectomy recommended in RET mutation carriers?","Near-universal risk of medullary thyroid carcinoma.","Câncer medular de tireoide."],["3sc6m71mp","Gene in myotonic dystrophy type 1?","DMPK on chromosome 19; CTG repeat expansion, autosomal dominant.","DMPK."],["17256u11v","Clinical features of myotonic dystrophy?","Myotonia (cannot release grip), muscle wasting, cataracts, testicular atrophy, frontal balding, arrhythmias, insulin resistance.","Miotonia, catarata, calvície, atrofia testicular."],["1j9c58bz3","Gene and chromosome in neurofibromatosis type 1?","NF1 (neurofibromin, a Ras GTPase activating protein) on chromosome 17.","NF1, cromossomo 17."],["dukyiqsf0","Clinical features of NF1?","Cafe-au-lait spots, cutaneous neurofibromas, Lisch nodules (iris hamartomas), optic gliomas, axillary/inguinal freckling, pheochromocytoma, bone lesions.","Café com leite, neurofibromas, Lisch."],["1j9c594z3","Gene and chromosome in neurofibromatosis type 2?","NF2 (merlin) on chromosome 22.","NF2, cromossomo 22."],["dukyldsf0","Clinical features of NF2?","Bilateral vestibular schwannomas, juvenile cataracts, meningiomas, ependymomas.","Schwannoma vestibular bilateral."],["m7qnne12v","Mnemonic for NF chromosomes?","NF1 has 17 letters (von Recklinghausen); NF2 is on chromosome 22 (type 2 = 22).","NF1 = 17 letras; NF2 = 22."],["1n4lenrux","Genes in tuberous sclerosis?","TSC1 (hamartin, chromosome 9) and TSC2 (tuberin, chromosome 16), autosomal dominant.","TSC1 e TSC2."],["10ushuz1h","Clinical features of tuberous sclerosis?","Hamartomas (cortical tubers), ash-leaf spots, angiofibromas, cardiac rhabdomyomas, renal angiomyolipomas, seizures, shagreen patches, subependymal giant cell astrocytoma.","Hamartomas, convulsões, angiofibromas."],["y8s8furmg","Gene and chromosome in von Hippel-Lindau disease?","VHL tumor suppressor on chromosome 3p, autosomal dominant.","VHL, cromossomo 3."],["1qxwqla1a","Clinical features of von Hippel-Lindau disease?","Hemangioblastomas (retina, cerebellum, spinal cord), bilateral renal cell carcinomas, pheochromocytomas, pancreatic cysts.","Hemangioblastomas, carcinoma renal."],["l2gsfknky","What does the VHL protein normally do?","Targets HIF-1-alpha for degradation; loss leads to increased VEGF and erythropoietin (angiogenesis, polycythemia).","Degrada HIF."],["9f22e8r3a","Gene in achondroplasia?","FGFR3 activating mutation (inhibits chondrocyte proliferation), autosomal dominant, most often de novo.","FGFR3."],["4ivxf3e0i","Clinical features of achondroplasia?","Short limbs, large head, normal trunk, normal intelligence; associated with advanced paternal age.","Nanismo de membros curtos."],["1kcsdhr13","What is the defect in cystic fibrosis?","Mutation in CFTR (chromosome 7) causing a misfolded chloride channel; most common: deletion of Phe508 (deltaF508).","CFTR com defeito."],["1b4axt71a","Pathophysiology of cystic fibrosis in the lungs?","Less Cl- secretion and more Na+ reabsorption cause dehydrated, thick mucus and recurrent infections.","Muco espesso."],["6rivn018t","Why is sweat chloride high in CF?","In sweat ducts CFTR normally reabsorbs Cl-; defective CFTR leaves high Cl- in sweat.","Não reabsorve cloreto."],["ec0132i3m","Diagnostic test for cystic fibrosis?","Sweat chloride >60 mEq/L; newborn screen with high immunoreactive trypsinogen; genetic testing.","Cloreto no suor."],["1svv49laz","Early pulmonary pathogens in CF?","Staphylococcus aureus and Haemophilus influenzae in early childhood.","S. aureus, H. influenzae."],["4tqtp2s8g","Late pulmonary pathogens in CF?","Pseudomonas aeruginosa and Burkholderia cepacia complex in adolescence/adulthood.","Pseudomonas."],["1r3n4z6cz","GI manifestations of cystic fibrosis?","Meconium ileus in newborns, pancreatic insufficiency with steatorrhea, fat-soluble vitamin deficiency, biliary cirrhosis, distal intestinal obstruction.","Íleo meconial, insuficiência pancreática."],["wxfm04d6k","Reproductive finding in males with cystic fibrosis?","Infertility due to bilateral absence of the vas deferens.","Ausência de ductos deferentes."],["wane9f136","Which CFTR modulators are used in CF?","Ivacaftor (potentiator) and correctors like lumacaftor, tezacaftor, elexacaftor.","Ivacaftor e combinações."],["1mw6dia1w","What nasal finding is associated with cystic fibrosis?","Nasal polyps (especially in children).","Pólipos nasais."],["1t0qol9h1","Mutation in sickle cell disease?","Point mutation in beta-globin: glutamate replaced by valine at position 6 (missense).","Glu6Val."],["xrr0svpra","Why do HbS molecules polymerize?","Deoxygenated HbS aggregates due to the hydrophobic valine, causing RBC sickling.","Desoxigenada polimeriza."],["1vkrann11","Gene and chromosome in Wilson disease?","ATP7B on chromosome 13, autosomal recessive.","ATP7B, cromossomo 13."],["ptxuxw1tv","Mechanism of Wilson disease?","Impaired hepatic copper excretion into bile and incorporation into ceruloplasmin, causing copper accumulation in liver, brain, cornea.","Cobre não excretado."],["xa5qfr1ye","Clinical features of Wilson disease?","Liver disease, Kayser-Fleischer rings, basal ganglia degeneration (parkinsonism, tremor), psychiatric symptoms, hemolytic anemia, low ceruloplasmin.","Fígado, neuro, anel de Kayser-Fleischer."],["4yxkezxi2","Treatment of Wilson disease?","Chelation with penicillamine or trientine, and zinc to block copper absorption; liver transplant in severe cases.","Quelantes e zinco."],["mskeje6y0","Gene in hereditary hemochromatosis?","HFE on chromosome 6, most commonly C282Y (or H63D), autosomal recessive.","HFE."],["1xx5ffq1s","Mechanism of hereditary hemochromatosis?","Low hepcidin increases intestinal iron absorption, leading to iron overload.","Absorção excessiva de ferro."],["vgqbbs1bk","Clinical triad of hereditary hemochromatosis?","Cirrhosis, diabetes mellitus, skin hyperpigmentation (bronze diabetes); also cardiomyopathy, arthropathy, hypogonadism.","Cirrose, diabetes, pele bronzeada."],["1ar0lt686","Lab findings in hereditary hemochromatosis?","High ferritin, high serum iron, high transferrin saturation, low TIBC.","Ferritina e saturação altas."],["km8r321k8","Why may women with hereditary hemochromatosis present later?","Menstrual blood loss protects against iron accumulation.","Menstruação perde ferro."],["1rfafq11u","Treatment of hereditary hemochromatosis?","Repeated phlebotomy; deferoxamine or deferasirox if phlebotomy is not possible.","Flebotomia."],["vzdumf1sw","Gene and defect in Friedreich ataxia?","FXN (frataxin) on chromosome 9; GAA repeat expansion causing impaired mitochondrial iron handling, autosomal recessive.","FXN; repetição GAA."],["1wofxqu13","Clinical features of Friedreich ataxia?","Gait ataxia in childhood, loss of proprioception and vibration, hypertrophic cardiomyopathy (main cause of death), pes cavus, diabetes, kyphoscoliosis.","Ataxia, cardiomiopatia, diabetes."],["1p3rcbp17","What is autosomal recessive polycystic kidney disease associated with?","Bilateral collecting duct cysts in infants, congenital hepatic fibrosis, Potter sequence from oligohydramnios.","Fibrose hepática congênita."],["zehmh4pei","Which disorders are classic autosomal recessive storage diseases?","Most glycogen and lysosomal storage diseases, except Hunter syndrome and Fabry disease (X-linked).","Lisossomais."],["pmh6qaaz6","What is the inheritance of oculocutaneous albinism?","Autosomal recessive (tyrosinase deficiency most commonly).","Autossômica recessiva."],["12f4o06dl","What is the inheritance of ocular albinism type 1?","X-linked recessive.","Ligada ao X."],["1lnaz7j11","What is the defect in Duchenne muscular dystrophy?","Deletion causing frameshift in the dystrophin gene (DMD on Xp21), with absent dystrophin; X-linked recessive.","Distrofina deletada."],["1vcqmk11r","Why is the dystrophin gene prone to mutations?","It is the largest protein-coding gene in humans, so it has a high spontaneous mutation rate.","Gene muito grande."],["hfky8o1uw","What does dystrophin normally do?","Connects the intracellular cytoskeleton (actin) to the transmembrane proteins and extracellular matrix, stabilizing muscle membranes.","Liga actina à membrana."],["1vhtgp1ux","Clinical features of Duchenne muscular dystrophy?","Onset before age 5, weakness starting in pelvic girdle, Gowers sign, waddling gait, calf pseudohypertrophy (fibrofatty replacement).","Fraqueza proximal e pseudo-hipertrofia."],["1cwfznfoj","What is the Gowers sign?","Child uses hands to push off the thighs to stand, due to proximal leg weakness.","Levanta usando as mãos."],["ps345b11p","Most common cause of death in Duchenne muscular dystrophy?","Dilated cardiomyopathy (and respiratory failure).","Insuficiência cardíaca ou respiratória."],["82wwgq4gv","Lab findings in Duchenne muscular dystrophy?","Very high creatine kinase and aldolase; diagnosis by genetic testing.","CK muito alta."],["i6ae2fy5n","What distinguishes Becker muscular dystrophy?","In-frame deletions with partially functional dystrophin; onset in adolescence or early adulthood, milder, longer survival.","Mais leve, in-frame."],["2xbwh0izg","Clinical features of fragile X syndrome?","Intellectual disability, long face, large jaw, large everted ears, macroorchidism (post-puberty), mitral valve prolapse, autism, hypermobile joints.","Macrocefalia, testículos grandes, atraso."],["vc59yv4ri","What is the most common inherited cause of intellectual disability?","Fragile X syndrome (Down syndrome is the most common genetic cause overall).","X frágil."],["1dlvnd81o","Karyotype in Down syndrome?","47,XX or XY,+21 (trisomy 21).","47,XX/XY +21."],["awygwswqq","Clinical features of Down syndrome?","Intellectual disability, flat facies, prominent epicanthal folds, single palmar crease, gap between 1st and 2nd toes, duodenal atresia, Hirschsprung disease, congenital heart disease, Brushfield spots.","Face típica, atraso, hipotonia."],["vmja6rork","Most common congenital heart defect in Down syndrome?","Atrioventricular septal defect (endocardial cushion defect).","Defeito do septo AV."],["15ezkv61e","Which malignancies are increased in Down syndrome?","Acute lymphoblastic leukemia and acute megakaryoblastic leukemia (AML M7); transient myeloproliferative disorder in newborns.","Leucemias."],["16dbuhipr","Why do people with Down syndrome develop early Alzheimer disease?","Chromosome 21 carries the APP gene; extra copy increases amyloid production.","APP no cromossomo 21."],["17bmk0j1k","Clinical features of Edwards syndrome (trisomy 18)?","Prominent occiput, rocker-bottom feet, intellectual disability, small jaw (micrognathia), low-set ears, clenched hands with overlapping fingers, congenital heart disease. Death usually within 1 year.","Mão fechada, pés em mata-borrão."],["1w7l0wrzu","Clinical features of Patau syndrome (trisomy 13)?","Severe intellectual disability, rocker-bottom feet, microphthalmia, microcephaly, cleft lip/palate, holoprosencephaly, polydactyly, cutis aplasia, congenital heart disease. Death usually within 1 year.","Fenda, polidactilia, holoprosencefalia."],["14dv1od1a","Mnemonic for trisomy numbers: Down, Edwards, Patau?","Drinking age 21, Election age 18, Puberty at 13.","21 = votar, 18 = eleição, 13 = puberdade."],["ieoqdqp50","Which trisomy is associated with omphalocele and polycystic kidneys?","Trisomy 13 (Patau).","Trissomia 13."],["zjwyawxeh","What is cri-du-chat syndrome?","Microdeletion of the short arm of chromosome 5 (5p-): microcephaly, intellectual disability, high-pitched mewing cry, epicanthal folds, cardiac defects (VSD).","Deleção 5p; choro de gato."],["j96qpj3j8","What is Williams syndrome?","Microdeletion of chromosome 7 (including elastin gene): elfin facies, intellectual disability, hypercalcemia, well-developed verbal skills, extreme friendliness, supravalvular aortic stenosis.","Deleção 7q; sociável, estenose aórtica."],["18bq11i1n","What is 22q11.2 deletion syndrome?","Microdeletion causing failure of 3rd and 4th pharyngeal pouch development: DiGeorge or velocardiofacial syndrome.","DiGeorge."],["1t9bcxv1h","Mnemonic for 22q11 deletion features?","CATCH-22: Cleft palate, Abnormal facies, Thymic aplasia (T cell deficiency), Cardiac defects (conotruncal), Hypocalcemia (parathyroid aplasia).","CATCH-22."],["1nmrn07o2","Karyotype in Klinefelter syndrome?","47,XXY.","47,XXY."],["1ndb1nroy","Clinical features of Klinefelter syndrome?","Testicular atrophy, eunuchoid body shape, tall, long extremities, gynecomastia, female hair distribution, infertility, possible developmental delay.","Alto, ginecomastia, testículos pequenos."],["hjsro8fnv","Hormone levels in Klinefelter syndrome?","Low testosterone, high FSH and LH, high estrogen (hypergonadotropic hypogonadism).","FSH/LH altos, testosterona baixa."],["z6fs2jlef","What forms Barr bodies in Klinefelter syndrome?","The inactivated extra X chromosome.","X extra inativado."],["yuvvdg1tl","Karyotype in Turner syndrome?","45,XO (most common); also mosaicism or isochromosome Xq.","45,X."],["13iti841f","Clinical features of Turner syndrome?","Short stature, ovarian dysgenesis (streak ovaries), shield chest, widely spaced nipples, webbed neck, lymphedema of hands/feet, bicuspid aortic valve, coarctation, horseshoe kidney.","Baixa, pescoço alado, ovários em fita."],["19ytu1kp7","Most common cause of primary amenorrhea?","Turner syndrome.","Turner."],["cj4u3f51r","Hormone levels in Turner syndrome?","Low estrogen, high LH and FSH (hypergonadotropic hypogonadism).","FSH/LH altos, estrogênio baixo."],["8jl2771vl","What cardiovascular defects are classic in Turner syndrome?","Bicuspid aortic valve and preductal coarctation of the aorta.","Coarctação e valva bicúspide."],["1eatihy18","What is double Y males (47,XYY)?","Phenotypically normal, very tall, severe acne, may have learning/ behavioral issues; normal fertility.","Altos, normais."],["12myrpqwz","What is ovotesticular disorder of sex development?","46,XX or 47,XXY with both ovarian and testicular tissue; ambiguous genitalia.","Ovário e testículo juntos."],["15o2lgt1x","Most common cause of 46,XX disorder of sex development (virilized female)?","Congenital adrenal hyperplasia (21-hydroxylase deficiency).","Hiperplasia adrenal congênita."],["mprmxbhkk","What is androgen insensitivity syndrome?","46,XY with defective androgen receptor: female-appearing external genitalia, testes in abdomen/labia, no uterus or fallopian tubes, scant pubic hair.","Genitália feminina, XY."],["5191yw1j7","What is 5-alpha-reductase deficiency?","46,XY, inability to convert testosterone to DHT; ambiguous genitalia until puberty, then masculinization.","Genitália ambígua até a puberdade."],["1x6r655wq","What is Kallmann syndrome?","Defective GnRH neuron migration and olfactory bulb development: hypogonadotropic hypogonadism with anosmia.","Anosmia e hipogonadismo."],["cn91yl15z","Inheritance of hemophilia A and B?","X-linked recessive. A: factor VIII deficiency. B: factor IX deficiency.","Ligada ao X recessiva."],["xy5lgk1hh","Inheritance of von Willebrand disease?","Usually autosomal dominant (most common inherited bleeding disorder).","Autossômica dominante."],["x7brhrhby","Inheritance of G6PD deficiency?","X-linked recessive.","Ligada ao X recessiva."],["17l3ap15i","Inheritance of Bruton agammaglobulinemia?","X-linked recessive (BTK gene defect).","Ligada ao X recessiva."],["3wtsfv5q2","Inheritance and features of Wiskott-Aldrich syndrome?","X-linked recessive (WAS gene): thrombocytopenia, eczema, recurrent infections (WATER: WAS, Thrombocytopenia, Eczema, Recurrent infections).","XR; eczema, trombocitopenia, infecções."],["z5or2b5b4","Inheritance of chronic granulomatous disease (most common form)?","X-linked recessive (NADPH oxidase gp91phox, CYBB).","Ligada ao X recessiva."],["mzeo2lb7b","Inheritance of Fabry disease?","X-linked recessive (alpha-galactosidase A).","Ligada ao X recessiva."],["1alg2hm3u","Inheritance of Hunter syndrome?","X-linked recessive (iduronate-2-sulfatase).","Ligada ao X recessiva."],["jko9uw1dd","Inheritance of ornithine transcarbamylase deficiency?","X-linked recessive (most common urea cycle disorder).","Ligada ao X recessiva."],["nsa5upt36","Inheritance of Alport syndrome (most common form)?","X-linked dominant (type IV collagen alpha-5, COL4A5).","Ligada ao X dominante."],["178qu7pr5","Features of Alport syndrome?","Hematuria and progressive nephritis, sensorineural hearing loss, ocular disorders (anterior lenticonus). Can't see, can't pee, can't hear a bee.","Nefrite, surdez, olhos."],["t5foco15e","What is Rett syndrome?","X-linked dominant (MECP2), seen almost exclusively in girls: normal development, then regression of motor, verbal, cognitive skills, ataxia, seizures, stereotyped hand-wringing.","Regressão em meninas."],["mx4nblwid","Why is Rett syndrome rare in males?","MECP2 loss is usually lethal in hemizygous males.","Letal em meninos."],["xici3kh4j","Genetic defect in Prader-Willi syndrome?","Loss of paternal 15q11-q13 (deletion, maternal UPD, or imprinting defect).","Perda paterna 15q."],["osugyx8xm","Genetic defect in Angelman syndrome?","Loss of maternal UBE3A on 15q11-q13 (deletion, paternal UPD, UBE3A mutation, or imprinting defect).","Perda materna 15q."],["kfn6xo1hk","What is the defect in osteogenesis imperfecta (most common)?","Autosomal dominant mutation in COL1A1 or COL1A2 (type I collagen).","COL1A1/COL1A2."],["t4cd2k1ad","Inheritance and defect in Gaucher disease?","Autosomal recessive; glucocerebrosidase deficiency (most common lysosomal storage disease, especially in Ashkenazi Jews).","AR; glicocerebrosidase."],["1yfjebsle","Inheritance and defect in Tay-Sachs disease?","Autosomal recessive; hexosaminidase A deficiency causing GM2 ganglioside accumulation.","AR; hexosaminidase A."],["xnkdah8px","Which populations have high frequency of Tay-Sachs and Gaucher?","Ashkenazi Jews (also French Canadians and Cajuns for Tay-Sachs).","Judeus asquenazes."],["15qzmq71u","Which inherited disorder is the most common lethal genetic disease in people of European descent?","Cystic fibrosis.","Fibrose cística."],["vr0tbj1dt","What is the inheritance of sickle cell disease and thalassemias?","Autosomal recessive.","Autossômica recessiva."],["w6nzv9hn5","Gene deletion in alpha thalassemia vs mutation in beta thalassemia?","Alpha: usually gene deletions (chromosome 16, four alleles). Beta: usually point mutations (splice site, promoter) on chromosome 11.","Deleção vs mutação pontual."],["14omejy1h","What is the inheritance of familial Mediterranean fever?","Autosomal recessive (MEFV, pyrin).","Autossômica recessiva."],["1d3y684eq","What is the inheritance of phenylketonuria?","Autosomal recessive.","Autossômica recessiva."],["1syh17dpr","What is the inheritance of hereditary angioedema?","Autosomal dominant (C1 esterase inhibitor deficiency).","Autossômica dominante."],["1qj6am1p3","What is the inheritance of acute intermittent porphyria?","Autosomal dominant (porphobilinogen deaminase).","Autossômica dominante."],["1cd3op7tm","What is the inheritance of BRCA1/2-associated cancer syndromes?","Autosomal dominant (tumor suppressor genes).","Autossômica dominante."],["gszh5f97p","What is the inheritance of Lynch syndrome?","Autosomal dominant (mismatch repair genes).","Autossômica dominante."],["1vrftun1a","What is the inheritance of hereditary retinoblastoma?","Autosomal dominant (germline RB1 mutation, chromosome 13).","Autossômica dominante."],["ih5us5i0m","Other malignancy risk in hereditary retinoblastoma survivors?","Osteosarcoma (especially after radiation).","Osteossarcoma."],["2facpk533","What is Peutz-Jeghers syndrome?","Autosomal dominant (STK11): hamartomatous polyps throughout GI tract and hyperpigmented mouth, lips, hands, genitalia; increased cancer risk (colorectal, breast, pancreatic).","Pólipos hamartomatosos e manchas."],["qkzagbje9","What is Cowden syndrome?","Autosomal dominant PTEN mutation: multiple hamartomas, macrocephaly, increased risk of breast, thyroid, endometrial cancer.","PTEN; hamartomas e câncer."],["p6xiqrb3c","What is the inheritance of Bernard-Soulier syndrome and Glanzmann thrombasthenia?","Both autosomal recessive (GpIb deficiency and GpIIb/IIIa deficiency, respectively).","Autossômica recessiva."],["njkcgtotd","What is hereditary nonpolyposis colorectal cancer's other name?","Lynch syndrome.","Lynch."],["v4b4g8x3a","What is Noonan syndrome?","AD (often PTPN11, RAS-MAPK pathway): webbed neck, short stature, pulmonary valve stenosis, hypertrophic cardiomyopathy, cryptorchidism; normal karyotype.","Baixa, pescoço alado, estenose pulmonar."],["wpd3zj4gz","How is Noonan syndrome distinguished from Turner syndrome?","Noonan occurs in both sexes with normal karyotype, normal fertility in females, and pulmonary valve stenosis (vs bicuspid aortic valve/coarctation in Turner).","Noonan tem cariótipo normal."],["meu9v810h","What is the inheritance of spinal muscular atrophy?","Autosomal recessive (SMN1 deletion).","Autossômica recessiva."],["1g9690rkz","Key features of spinal muscular atrophy type 1 (Werdnig-Hoffmann)?","Infantile floppy baby, tongue fasciculations, degeneration of anterior horn cells; treated with nusinersen or gene therapy.","Bebê hipotônico."],["1uvuas4jh","What is the inheritance of hereditary motor and sensory neuropathy (Charcot-Marie-Tooth type 1A)?","Autosomal dominant (PMP22 duplication).","Autossômica dominante."],["i8iebib6q","What is the inheritance of hereditary fructose intolerance?","Autosomal recessive (aldolase B).","Autossômica recessiva."],["2jkm6f5ch","What is the inheritance of most glycogen storage diseases?","Autosomal recessive.","Autossômica recessiva."],["1ch0moj16","What is the inheritance of DiGeorge syndrome?","Usually de novo; autosomal dominant transmission possible.","Deleção, geralmente de novo."],["i26v171pp","What is the inheritance of neurofibromatosis?","Autosomal dominant, with about half of NF1 cases de novo.","Autossômica dominante."],["11jck411g","What is the inheritance of multiple endocrine neoplasia syndromes?","Autosomal dominant.","Autossômica dominante."],["e9pi91ojw","What is the inheritance of mitochondrial myopathies like MELAS?","Mitochondrial (maternal) inheritance, with variable expression due to heteroplasmy.","Mitocondrial."],["1szb18svh","What is the inheritance of Leigh syndrome?","Can be mitochondrial or autosomal recessive (nuclear genes).","Mitocondrial ou nuclear."],["1vfqq2ohl","What is the inheritance of homocystinuria and alkaptonuria?","Autosomal recessive.","Autossômica recessiva."],["15i2hoh1b","What is the inheritance of familial hypocalciuric hypercalcemia?","Autosomal dominant (inactivating CaSR mutation).","Autossômica dominante."],["1qzrirq6u","What is the inheritance of hereditary pancreatitis?","Autosomal dominant (PRSS1, cationic trypsinogen).","Autossômica dominante."],["g4xf6x1j6","What is the inheritance of congenital adrenal hyperplasia?","Autosomal recessive.","Autossômica recessiva."],["1w0flcgos","What is the inheritance of hereditary elliptocytosis?","Usually autosomal dominant.","Autossômica dominante."],["gplwpx19u","What is the inheritance of Ehlers-Danlos syndrome (hypermobile, classic, vascular types)?","Autosomal dominant (most types).","Mais AD; algumas AR."],["2cdfv81rr","What is the inheritance of Marfan vs homocystinuria?","Marfan: autosomal dominant. Homocystinuria: autosomal recessive.","AD vs AR."],["bqq9cstes","How is lens subluxation different in Marfan vs homocystinuria?","Marfan: upward/temporal. Homocystinuria: downward/inward (down and in).","Para cima vs para baixo."]]},{"name":"Metabolism (Part 1)","cards":[["wefwsdpil","Which metabolic pathways occur in the mitochondria?","Fatty acid oxidation (beta-oxidation), acetyl-CoA production, TCA cycle, oxidative phosphorylation, ketogenesis.","Krebs, beta-oxidação, cetogênese."],["1sl9r5gzs","Which metabolic pathways occur in the cytoplasm?","Glycolysis, HMP shunt, fatty acid synthesis, cholesterol synthesis, protein synthesis (free ribosomes), steroid synthesis (SER).","Glicólise, síntese de ácidos graxos, HMP."],["14own8q4k","Which pathways occur in both cytoplasm and mitochondria?","Heme synthesis, urea cycle, gluconeogenesis. Mnemonic: HUGs take two (both).","Heme, ureia, gliconeogênese."],["oqpp3f1jj","Rate-limiting enzyme of glycolysis?","Phosphofructokinase-1 (PFK-1).","PFK-1."],["1qvwnr01l","Activators and inhibitors of PFK-1?","Activated by AMP and fructose-2,6-bisphosphate. Inhibited by ATP and citrate.","AMP ativa; ATP e citrato inibem."],["nuscqn1nc","Rate-limiting enzyme of gluconeogenesis?","Fructose-1,6-bisphosphatase.","Frutose-1,6-bisfosfatase."],["1bm8yhvp9","Regulators of fructose-1,6-bisphosphatase?","Activated by citrate (and ATP). Inhibited by AMP and fructose-2,6-bisphosphate.","AMP inibe; ATP ativa."],["1i5hqdyq1","Rate-limiting enzyme of the TCA cycle?","Isocitrate dehydrogenase.","Isocitrato desidrogenase."],["1km6iyi1k","Regulators of isocitrate dehydrogenase?","Activated by ADP. Inhibited by ATP and NADH.","ADP ativa; ATP e NADH inibem."],["1vococ71f","Rate-limiting enzyme of glycogenesis?","Glycogen synthase (activated by insulin, G6P, glucose; inhibited by epinephrine, glucagon).","Glicogênio sintase."],["14uhiqw16","Rate-limiting enzyme of glycogenolysis?","Glycogen phosphorylase (activated by epinephrine, glucagon, AMP; inhibited by insulin, G6P, ATP).","Glicogênio fosforilase."],["13rygi91s","Rate-limiting enzyme of the HMP shunt?","Glucose-6-phosphate dehydrogenase (G6PD), activated by NADP+, inhibited by NADPH.","G6PD."],["1x8edgjqt","Rate-limiting enzyme of the urea cycle?","Carbamoyl phosphate synthetase I (activated by N-acetylglutamate).","CPS I."],["53garw1z0","Rate-limiting enzyme of fatty acid synthesis?","Acetyl-CoA carboxylase (activated by insulin and citrate; inhibited by glucagon and palmitoyl-CoA).","Acetil-CoA carboxilase."],["jcizlr1rd","Rate-limiting enzyme of fatty acid oxidation?","Carnitine acyltransferase I (carnitine palmitoyltransferase I), inhibited by malonyl-CoA.","CAT I."],["18ipkkc19","Rate-limiting enzyme of ketogenesis?","HMG-CoA synthase.","HMG-CoA sintase."],["103vqyr1c","Rate-limiting enzyme of cholesterol synthesis?","HMG-CoA reductase (activated by insulin and thyroxine; inhibited by glucagon, cholesterol, statins).","HMG-CoA redutase."],["kgil3sy7h","Rate-limiting enzyme of heme synthesis?","Aminolevulinic acid (ALA) synthase (inhibited by heme).","ALA sintase."],["1fz0zrc1u","How much ATP does aerobic metabolism of one glucose produce?","About 32 ATP via malate-aspartate shuttle (heart, liver) or 30 ATP via glycerol-3-phosphate shuttle (muscle).","30-32 ATP."],["15lp9441d","How much ATP does anaerobic glycolysis produce per glucose?","2 net ATP.","2 ATP."],["da1lbje2h","Which arsenic effect impairs ATP production in glycolysis?","Arsenate causes glycolysis to produce zero net ATP (replaces phosphate in glyceraldehyde-3-phosphate dehydrogenase step).","Arsenato substitui fosfato."],["vfbnnwwq3","What do ATP, NADH/NADPH/FADH2, CoA, biotin, THF, SAM, and TPP carry?","ATP: phosphoryl groups. NADH, NADPH, FADH2: electrons. CoA, lipoamide: acyl groups. Biotin: CO2. THF: 1-carbon units. SAM: methyl groups. TPP: aldehydes.","Grupos químicos ativados."],["1pyip4zcw","What is NAD+ generally used for vs NADPH?","NAD+: catabolic processes, carries reducing equivalents away as NADH. NADPH: anabolic processes (steroid and fatty acid synthesis), respiratory burst, cytochrome P-450, glutathione reductase.","Catabolismo vs síntese."],["q3av2719k","Which pathway produces NADPH?","HMP shunt (pentose phosphate pathway).","Via das pentoses."],["13u42gg1e","Hexokinase vs glucokinase: location?","Hexokinase: most tissues (except liver and pancreatic beta cells). Glucokinase: liver and pancreatic beta cells.","Maioria dos tecidos vs fígado e pâncreas."],["1anigztda","Hexokinase vs glucokinase: kinetics?","Hexokinase: low Km (high affinity), low Vmax. Glucokinase: high Km (low affinity), high Vmax.","Hexoquinase afinidade alta; glicoquinase baixa."],["1dbh3ix1u","Hexokinase vs glucokinase: regulation?","Hexokinase is feedback-inhibited by glucose-6-phosphate. Glucokinase is induced by insulin and sequestered in the nucleus by glucokinase regulatory protein (not inhibited by G6P).","Hexoquinase inibida pelo produto."],["1pbg3hf1y","Why is glucokinase important in the beta cell?","Acts as a glucose sensor; mutations cause maturity-onset diabetes of the young (MODY 2).","Sensor de glicose."],["1sc52uz1v","Which glycolysis steps produce ATP?","Phosphoglycerate kinase (1,3-BPG to 3-PG) and pyruvate kinase (PEP to pyruvate).","Fosfoglicerato quinase e piruvato quinase."],["1ktdo4t1a","Which glycolysis steps consume ATP?","Hexokinase/glucokinase (glucose to G6P) and PFK-1 (F6P to F1,6BP).","Hexoquinase e PFK-1."],["b8qcnd1g4","What regulates pyruvate kinase?","Activated by fructose-1,6-bisphosphate (feedforward). Inhibited by ATP and alanine; inhibited by glucagon (phosphorylation in liver).","Frutose-1,6-bisfosfato ativa; ATP inibe."],["1iw8xhx9o","What does fructose-2,6-bisphosphate do?","Activates PFK-1 (glycolysis) and inhibits fructose-1,6-bisphosphatase (gluconeogenesis).","Ativa PFK-1."],["stdgmysdi","How do insulin and glucagon affect fructose-2,6-bisphosphate?","Fed state (insulin): more F2,6BP, more glycolysis. Fasting (glucagon): less F2,6BP, more gluconeogenesis.","Insulina sobe; glucagon desce."],["10r74oirm","How does glucagon affect the bifunctional enzyme PFK-2/FBPase-2?","Glucagon raises cAMP, activating protein kinase A, which phosphorylates and activates FBPase-2, lowering F2,6BP.","Fosforila e reduz F2,6BP."],["11nxpid10","What does the pyruvate dehydrogenase complex do?","Converts pyruvate to acetyl-CoA, linking glycolysis to the TCA cycle (irreversible).","Piruvato vira acetil-CoA."],["1n0nf7v1p","Which cofactors are required by pyruvate dehydrogenase?","Thiamine pyrophosphate (B1), lipoic acid, CoA (B5), FAD (B2), NAD+ (B3). Mnemonic: Tender Loving Care For Nancy.","B1, B2, B3, B5, ácido lipoico."],["c1e0zur4t","Which other enzyme uses the same cofactors as pyruvate dehydrogenase?","Alpha-ketoglutarate dehydrogenase (and branched-chain alpha-ketoacid dehydrogenase).","Alfa-cetoglutarato desidrogenase."],["dop4psk7u","What regulates pyruvate dehydrogenase?","Activated by increased NAD+/NADH, ADP, Ca2+ (exercise). Inhibited by its products acetyl-CoA, NADH, and ATP.","Produtos inibem; ADP ativa."],["1t92n1onp","How does arsenic inhibit the pyruvate dehydrogenase complex?","It inhibits lipoic acid.","Liga ácido lipoico."],["1el4l671p","Clinical findings of arsenic poisoning?","Vomiting, rice-water stools, garlic breath, QT prolongation.","Vômito, diarreia, hálito de alho."],["l3u9s5q62","What is pyruvate dehydrogenase complex deficiency?","Causes buildup of pyruvate that is shunted to lactate (lactic acidosis) and alanine; X-linked (E1 alpha) most commonly.","Defeito da PDH."],["17klbuc1r","Clinical features of pyruvate dehydrogenase deficiency?","Neurologic defects, lactic acidosis, increased serum alanine, starting in infancy.","Acidose lática e atraso."],["26pv08ht9","Treatment of pyruvate dehydrogenase deficiency?","Increase intake of ketogenic nutrients (high fat, lysine and leucine), which are converted to acetyl-CoA without PDH.","Dieta cetogênica."],["tdshsumih","What are the four main fates of pyruvate?","Alanine (ALT), oxaloacetate (pyruvate carboxylase), acetyl-CoA (PDH), lactate (LDH).","Alanina, OAA, acetil-CoA, lactato."],["vo0qyh1e7","What does pyruvate carboxylase require and what activates it?","Biotin and ATP; activated by acetyl-CoA. Located in mitochondria.","Biotina; acetil-CoA ativa."],["1uk0uovxk","Why is lactate dehydrogenase important in RBCs?","RBCs lack mitochondria and depend on anaerobic glycolysis, regenerating NAD+ by converting pyruvate to lactate.","Regenera NAD+."],["1wazwms1f","What does alanine aminotransferase do with pyruvate?","Converts pyruvate to alanine (B6 required), carrying amino groups to the liver (Cahill cycle).","Faz alanina."],["7w86n81iw","Products of one turn of the TCA cycle (per acetyl-CoA)?","3 NADH, 1 FADH2, 2 CO2, 1 GTP (about 10 ATP).","3 NADH, 1 FADH2, 1 GTP."],["15rysxl1m","Order of TCA cycle intermediates?","Citrate, isocitrate, alpha-ketoglutarate, succinyl-CoA, succinate, fumarate, malate, oxaloacetate. Mnemonic: Citrate Is Krebs' Starting Substrate For Making Oxaloacetate.","Citrato, isocitrato, alfa-KG..."],["tdz75513s","Which TCA step produces GTP?","Succinyl-CoA synthetase (succinyl-CoA to succinate).","Succinil-CoA sintetase."],["1ay7iu3ow","Which TCA enzyme is also part of the electron transport chain?","Succinate dehydrogenase (complex II), producing FADH2.","Succinato desidrogenase."],["3f8nwtmiq","What inhibits alpha-ketoglutarate dehydrogenase?","Succinyl-CoA, NADH, ATP (and GTP).","Produtos e cálcio."],["17fln1m1q","What do succinyl-CoA and other TCA intermediates feed into?","Succinyl-CoA: heme synthesis. Alpha-ketoglutarate: glutamate. Oxaloacetate: aspartate and gluconeogenesis. Citrate: fatty acid synthesis.","Heme."],["1cfz7042n","What is the electron transport chain's main purpose?","Uses NADH and FADH2 electrons to pump H+ out of the mitochondrial matrix, creating a gradient for ATP synthase.","Gerar gradiente de prótons."],["1p57ran1k","ATP yield of NADH vs FADH2 in oxidative phosphorylation?","NADH: about 2.5 ATP. FADH2: about 1.5 ATP (enters at complex II).","2,5 vs 1,5 ATP."],["j6oni0134","Which drugs/poisons inhibit complex I?","Rotenone and metformin.","Rotenona, metformina."],["12b4jtp1o","Which agents inhibit complex III?","Antimycin A.","Antimicina A."],["4e55vf1uf","Which agents inhibit complex IV (cytochrome c oxidase)?","Cyanide, carbon monoxide, azide, hydrogen sulfide.","Cianeto, CO, azida."],["71dwi93br","What is the effect of electron transport inhibitors?","Directly block electron flow, decreasing the proton gradient and ATP synthesis, increasing anaerobic metabolism (lactic acidosis).","Para tudo."],["2yzbhirvp","Which agent inhibits ATP synthase directly?","Oligomycin.","Oligomicina."],["16s94hi1h","What is the effect of ATP synthase inhibitors on the proton gradient?","Increase the proton gradient; electron transport eventually stops because of the high gradient.","Gradiente aumenta."],["sjymckv4j","What do uncoupling agents do?","Increase permeability of the inner mitochondrial membrane, dissipating the proton gradient; ATP synthesis falls, O2 consumption rises, heat is produced.","Dissipam o gradiente."],["2nln1mvhw","Name examples of uncoupling agents.","2,4-dinitrophenol (DNP), high-dose aspirin (fevers after overdose), thermogenin (UCP1) in brown fat.","2,4-DNP, aspirina, termogenina."],["1n27xw514","Why does aspirin overdose cause hyperthermia?","Salicylates uncouple oxidative phosphorylation, releasing energy as heat.","Desacopla e gera calor."],["93nk8815g","What is thermogenin?","Uncoupling protein 1 in brown adipose tissue of newborns; generates heat (nonshivering thermogenesis).","Desacoplador da gordura marrom."],["9fvmd3swt","What happens to oxygen consumption with uncouplers vs inhibitors?","Uncouplers: O2 consumption increases. ETC inhibitors: O2 consumption decreases.","Uncoupler aumenta; inibidor diminui."],["tc89y1152","What is the main purpose of gluconeogenesis?","Making glucose from noncarbohydrate precursors during fasting (lactate, glycerol, glucogenic amino acids, propionyl-CoA).","Manter glicemia no jejum."],["156w3104v","Where does gluconeogenesis occur?","Primarily liver; also kidney and intestinal epithelium. Not in muscle (lacks glucose-6-phosphatase).","Fígado e rim."],["1c0qban15","What are the irreversible enzymes of gluconeogenesis?","Pyruvate carboxylase, PEP carboxykinase, fructose-1,6-bisphosphatase, glucose-6-phosphatase.","Piruvato carboxilase, PEPCK, F1,6Pase, G6Pase."],["12gwsox1f","Where is pyruvate carboxylase and what does it make?","Mitochondria; pyruvate to oxaloacetate (needs biotin, ATP; activated by acetyl-CoA).","Mitocôndria; oxaloacetato."],["o23xl4w3n","What does PEP carboxykinase do and what does it require?","Converts oxaloacetate to phosphoenolpyruvate in cytosol, requires GTP.","OAA vira PEP; GTP."],["1txknatss","Where is glucose-6-phosphatase located?","Endoplasmic reticulum (liver, kidney).","Retículo endoplasmático."],["iw393p2lh","What disorder results from glucose-6-phosphatase deficiency?","Von Gierke disease (glycogen storage disease type I), with severe fasting hypoglycemia.","Von Gierke."],["1s8k9lmoj","Can fatty acids be used for gluconeogenesis?","Even-chain fatty acids cannot (they yield acetyl-CoA, which cannot be converted to glucose). Odd-chain fatty acids yield propionyl-CoA, which can.","Não, só ímpares."],["ltsz1nrfk","Why can't acetyl-CoA be converted to glucose?","Pyruvate dehydrogenase is irreversible, and the two carbons are lost as CO2 in the TCA cycle.","Piruvato desidrogenase é irreversível."],["5tmdec1sk","What is the Cori cycle?","Lactate from muscle/RBCs travels to the liver, is converted to glucose (gluconeogenesis), and returns to tissues.","Lactato volta a glicose."],["1cbscid1w","Why does alcohol cause fasting hypoglycemia?","Ethanol metabolism increases NADH/NAD+, which drives pyruvate to lactate and OAA to malate, inhibiting gluconeogenesis.","Excesso de NADH."],["mc2q8f1xd","What does the HMP shunt produce?","NADPH (oxidative phase) and ribose-5-phosphate for nucleotide synthesis (nonoxidative phase); no ATP is used or produced.","NADPH e ribose."],["x5m9qxxlv","Where is the HMP shunt active?","Cytoplasm; especially in lactating mammary glands, liver, adrenal cortex (fatty acid/steroid synthesis), and RBCs.","Fígado, adrenal, hemácia."],["gownuv1il","Which enzyme in the nonoxidative HMP shunt requires thiamine?","Transketolase (B1).","Transcetolase."],["15f49jm44","Is the oxidative or nonoxidative phase of the HMP shunt reversible?","Oxidative: irreversible. Nonoxidative: reversible.","Não oxidativo."],["114wojfo3","What is the respiratory (oxidative) burst?","Rapid release of reactive oxygen species by phagocytes (NADPH oxidase), used to kill organisms.","Explosão de radicais."],["53yzxr6d9","Which enzymes produce bactericidal agents in the respiratory burst?","NADPH oxidase (O2 to superoxide), superoxide dismutase (to H2O2), myeloperoxidase (to HOCl, bleach).","NADPH oxidase, SOD, MPO."],["1hrxfia92","What is the defect in chronic granulomatous disease?","NADPH oxidase deficiency, causing recurrent infections with catalase-positive organisms.","Falta NADPH oxidase."],["13zufmk15","Why are catalase-positive organisms a problem in CGD?","They degrade their own H2O2, so the phagocyte cannot use it to make bleach (HOCl).","Destroem peróxido."],["3qkrhi1q5","Catalase-positive organisms in CGD?","Staphylococcus aureus, Aspergillus, Burkholderia cepacia, Serratia, Nocardia (cats Need PLACESS: Pseudomonas, Listeria, Aspergillus, Candida, E. coli, S. aureus, Serratia).","S. aureus, Aspergillus, Serratia."],["1ung0oa7q","What test diagnoses chronic granulomatous disease?","Abnormal dihydrorhodamine flow cytometry test (or nitroblue tetrazolium dye test that fails to turn blue).","Di-hidrorodamina."],["1afr05x1h","How does G6PD deficiency cause hemolysis?","Reduced NADPH means glutathione cannot be kept reduced, so RBCs cannot neutralize oxidative stress (H2O2).","Falta glutationa reduzida."],["1awsqkfvz","What triggers hemolysis in G6PD deficiency?","Oxidant stress: fava beans, sulfonamides, nitrofurantoin, primaquine/dapsone, antituberculosis drugs, infections.","Fava, sulfas, infecção."],["1i1y72xdq","Blood smear findings in G6PD deficiency?","Heinz bodies (denatured Hb precipitates) and bite cells (from splenic removal of Heinz bodies).","Corpos de Heinz e células mordidas."],["bt8fdm1q3","What protective advantage does G6PD deficiency give?","Increased resistance to malaria.","Proteção contra malária."],["19oj2m11i","What type of enzyme inhibitor increases Km without changing Vmax?","Competitive inhibitor (reversible). Can be overcome by increasing substrate.","Competitivo."],["4l2x7jgdf","What type of enzyme inhibitor decreases Vmax without changing Km?","Noncompetitive inhibitor (binds a different site); cannot be overcome by more substrate.","Não competitivo."],["1gmn8ys13","What does Km reflect?","Substrate concentration at which the reaction velocity is half of Vmax; inversely related to enzyme affinity.","Afinidade inversa."],["1xgu3mo6v","What does Vmax reflect?","Maximum reaction velocity; directly proportional to the enzyme concentration.","Velocidade máxima."],["1f4v2ms1t","On a Lineweaver-Burk plot, what are the x- and y-intercepts?","x-intercept = -1/Km; y-intercept = 1/Vmax; slope = Km/Vmax.","-1/Km e 1/Vmax."],["cl64u7umi","What do competitive inhibitors look like on a Lineweaver-Burk plot?","Lines cross at the same y-intercept (same Vmax), different x-intercepts.","Cruzam no eixo y."],["ifonkgtey","What do noncompetitive inhibitors look like on a Lineweaver-Burk plot?","Lines cross at the same x-intercept (same Km), different y-intercepts.","Cruzam no eixo x."],["1n2afxv14","What is the shape of a Michaelis-Menten curve vs cooperative enzyme curve?","Michaelis-Menten: hyperbolic. Cooperative (e.g., hemoglobin): sigmoidal.","Hipérbole vs sigmoide."],["1snv5eksf","What is the potency of a competitive inhibitor vs noncompetitive regarding efficacy?","Competitive inhibitors decrease potency; noncompetitive inhibitors decrease efficacy.","Competitivo reduz potência; não, eficácia."],["qpfm1dfsi","What does an irreversible inhibitor do?","Covalently binds and permanently inactivates the enzyme (e.g., aspirin on COX).","Inativa enzima de vez."],["1485ssj1f","What does a high NADH/NAD+ ratio favor?","Lactate from pyruvate, malate from oxaloacetate, and glycerol-3-phosphate from DHAP; inhibits gluconeogenesis and TCA.","Lactato e corpos cetônicos."],["n2sg6fa9b","What are the main sources of fuel in the fed state (0-4 h)?","Glucose from the diet; glycolysis and storage (glycogenesis, lipogenesis) dominate, driven by insulin.","Glicose da dieta."],["16257wd1o","What sustains blood glucose in the early fasting state (between meals)?","Hepatic glycogenolysis (major), hepatic gluconeogenesis, adipose release of FFAs.","Glicogenólise."],["11i3fo81c","What sustains blood glucose after 1-3 days of starvation?","Hepatic gluconeogenesis (from amino acids, glycerol, lactate, propionate), adipose lipolysis, ketone bodies.","Gliconeogênese."],["wpymlz1u1","When are glycogen stores depleted during starvation?","Within about 1 day (24 hours).","12-18 horas."],["1l674uk8z","What is the main fuel after 3 days of starvation?","Adipose stores (ketone bodies become the main energy source for brain and heart).","Corpos cetônicos."],["xzyb5ecmm","Why is protein spared in prolonged starvation?","Brain shifts to ketone bodies, reducing need for gluconeogenesis from amino acids.","Cérebro usa cetonas."],["19q1ivzvk","What is the main determinant of survival time in starvation?","Amount of adipose tissue stores; once depleted, vital protein degradation leads to organ failure and death.","Reserva de gordura."],["16ppqss44","Which tissue cannot use ketone bodies at all?","RBCs (no mitochondria). The liver makes but cannot use ketones (lacks thiophorase / SCOT).","Hemácias."],["1ktqngkot","Which enzyme is required to use ketone bodies, absent in liver?","Succinyl-CoA:acetoacetate CoA transferase (thiophorase/SCOT).","Tioforase."],["fq9luhdph","What is substrate-level phosphorylation?","Direct transfer of a phosphate to ADP from a high-energy substrate (e.g., pyruvate kinase, phosphoglycerate kinase, succinyl-CoA synthetase).","ATP direto no substrato."],["z5kzfa1pm","What is oxidative phosphorylation?","ATP synthesis driven by the proton gradient from the electron transport chain (ATP synthase).","ATP pela cadeia."],["obq1kb4iq","What are the shuttles for cytosolic NADH entry into mitochondria?","Malate-aspartate shuttle (liver, heart, kidney; ~2.5 ATP) and glycerol-3-phosphate shuttle (muscle, brain; ~1.5 ATP).","Malato-aspartato e glicerol-fosfato."],["1frzdul1i","Why is 2,3-BPG produced in RBC glycolysis important?","It lowers hemoglobin affinity for O2, promoting oxygen unloading; made by the Rapoport-Luebering shunt.","Libera O2."],["tlqiui1ob","What is the effect of pyruvate kinase deficiency on RBCs?","Decreased ATP leads to rigid RBCs and hemolytic anemia; 2,3-BPG increases, right-shifting the O2 curve.","Hemólise."],["1t67x9110","Inheritance and features of pyruvate kinase deficiency?","Autosomal recessive; chronic extravascular hemolytic anemia, splenomegaly, echinocytes (burr cells).","AR; anemia hemolítica."],["1uq8xrfj4","Which enzyme defect causes most cases of hemolytic anemia due to glycolysis defects?","Pyruvate kinase deficiency (G6PD deficiency is HMP shunt related).","Piruvato quinase."],["18fgw9919","What does the glycerol-3-phosphate dehydrogenase do in the liver?","Converts glycerol-3-phosphate to DHAP, allowing glycerol from lipolysis to enter gluconeogenesis (glycerol kinase in liver).","Recicla glicerol."],["1y2w7yitn","Why can't adipose tissue reuse glycerol from lipolysis?","Adipose lacks glycerol kinase; glycerol is sent to the liver.","Falta glicerol quinase."],["1oxg2ng12","What is the overall effect of insulin on metabolic enzymes?","Promotes dephosphorylation, activating glycogen synthase, PDH, acetyl-CoA carboxylase, PFK-2; inhibits glycogen phosphorylase and gluconeogenesis.","Armazenar."],["17gvvwcds","What is the overall effect of glucagon on metabolic enzymes?","Increases cAMP and PKA phosphorylation, activating glycogen phosphorylase, gluconeogenesis, and lipolysis; inhibits glycolysis in liver.","Mobilizar."],["ukwcvs15e","Which tissues use insulin-dependent GLUT4 glucose uptake?","Adipose tissue, skeletal muscle (and cardiac muscle).","Músculo e gordura."],["t74ghy1oa","Which tissues take up glucose independent of insulin?","Brain, RBCs, intestine, cornea, kidney, liver, placenta, islet cells (BRICK LIPs).","Cérebro, hemácia, fígado."],["1t6acmvy0","Which GLUT transporter is in hepatocytes and beta cells?","GLUT2 (bidirectional, low affinity).","GLUT2."],["tis4kx14r","Which GLUT transporter is used for fructose absorption?","GLUT5 (apical enterocytes, spermatocytes).","GLUT5."],["7we6v3abd","Which GLUT transporters are in RBCs and the brain?","GLUT1 (RBCs, brain, cornea, placenta) and GLUT3 (neurons, placenta).","GLUT1."],["58k7pkavy","Which transporter absorbs glucose and galactose in the intestine?","SGLT1 (Na+ dependent, apical).","SGLT1."],["18cdqencn","Which glucose transporter is inhibited by flozins in the kidney?","SGLT2 in the proximal convoluted tubule.","SGLT2."],["bfu70g5pg","What happens to the ATP/AMP ratio with exercise?","ATP falls, AMP rises; AMP activates PFK-1, glycogen phosphorylase, and AMP-activated kinase.","Diminui."],["1ky08m41p","What does AMP-activated protein kinase (AMPK) do?","Energy sensor activated by low energy: promotes catabolism (glucose uptake, fatty acid oxidation) and inhibits anabolism (fatty acid and cholesterol synthesis). Activated by metformin.","Sensor de energia."],["7kne6nhyz","What enzyme does metformin mainly affect to reduce hepatic glucose output?","Inhibits mitochondrial glycerophosphate dehydrogenase and complex I, decreasing gluconeogenesis; activates AMPK.","Inibe gliconeogênese."],["13cpqslz3","Why can metformin cause lactic acidosis?","Inhibits gluconeogenesis from lactate and mitochondrial respiration; risk increases in renal failure.","Inibe uso de lactato."],["6tfax9z9n","What is the purpose of creatine phosphate in muscle?","Rapid regeneration of ATP from ADP (creatine kinase) during short bursts of activity.","Reserva rápida de energia."],["jrbxmsu9c","What is the most energy-efficient fuel per gram?","Fat (9 kcal/g) vs carbohydrate and protein (4 kcal/g); alcohol 7 kcal/g.","Gordura."],["1hwfdqatt","How many kcal per gram do carbohydrate, protein, fat, and ethanol provide?","Carbohydrate 4, protein 4, fat 9, ethanol 7.","4, 4, 9, 7."],["1ykc00m4h","What type of reaction do kinases catalyze?","Transfer of a phosphate from a high-energy molecule (usually ATP) to a substrate.","Fosforilação com ATP."],["gz2o8w1jn","What do phosphorylases do?","Add inorganic phosphate to a substrate without using ATP (e.g., glycogen phosphorylase).","Fosfato sem ATP."],["1wpi3st1g","What do phosphatases do?","Remove phosphate groups from a substrate (e.g., fructose-1,6-bisphosphatase).","Remove fosfato."],["d3pdpt1hi","What do dehydrogenases do?","Catalyze oxidation-reduction reactions (e.g., pyruvate dehydrogenase).","Oxirredução."],["xer7jl1du","What do hydroxylases do?","Add hydroxyl groups (OH) onto substrates (e.g., tyrosine hydroxylase).","Adiciona OH."],["qr80ash3u","What do carboxylases do?","Transfer CO2 groups with the help of biotin (e.g., pyruvate carboxylase).","Adiciona CO2."],["8kf1mgpm2","What do mutases do?","Relocate a functional group within a molecule (e.g., vitamin B12-dependent methylmalonyl-CoA mutase).","Move grupo."],["ndeuv81mn","What do synthases vs synthetases do?","Synthases: join two molecules without using ATP. Synthetases: join two molecules using energy from ATP.","Sem ATP vs com ATP."],["1akxg3e1p","Why does a patient with thiamine deficiency develop lactic acidosis after IV dextrose?","Without thiamine, PDH and alpha-ketoglutarate dehydrogenase fail, so glucose is shunted to lactate; give thiamine before glucose.","PDH sem tiamina."],["98ftel1he","Which metabolic effect explains why Wernicke encephalopathy can be precipitated by glucose?","Glucose increases flux through thiamine-dependent enzymes, depleting thiamine in vulnerable brain regions.","Glicose consome tiamina."],["160oat81a","What are the steps of pyruvate's conversion to PEP in gluconeogenesis?","Pyruvate to oxaloacetate (pyruvate carboxylase, mitochondria), OAA exported as malate, OAA to PEP (PEPCK).","Piruvato, OAA, PEP."],["yft5r313n","Why must oxaloacetate be shuttled as malate out of mitochondria?","The inner mitochondrial membrane is impermeable to oxaloacetate.","Não atravessa membrana."],["61sj2jdw6","Where do glucogenic amino acids enter gluconeogenesis?","As pyruvate or TCA intermediates (e.g., alanine to pyruvate; glutamate to alpha-ketoglutarate).","Via Krebs ou piruvato."],["21k6711wq","Which amino acids are purely ketogenic?","Leucine and lysine.","Leucina e lisina."],["pdvxlg1wi","Which amino acids are both glucogenic and ketogenic?","Phenylalanine, isoleucine, threonine, tryptophan, tyrosine (PITTT).","Fenilalanina, isoleucina, triptofano, tirosina."],["1arqa8v19","What is the function of the malate-aspartate shuttle in gluconeogenesis?","Transfers reducing equivalents and carbon skeletons (as malate) from mitochondria to cytosol.","Leva NADH ao citosol."],["1ii8ejx61","What happens to blood glucose in muscle glycogen breakdown?","Muscle glycogen does not raise blood glucose because muscle lacks glucose-6-phosphatase; it fuels muscle locally.","Músculo não libera glicose."],["1ixstvugf","Which hormones are counterregulatory against hypoglycemia?","Glucagon, epinephrine, cortisol, growth hormone.","Glucagon, adrenalina, cortisol, GH."],["dvj8nmjnd","What happens to glycolysis in RBCs if 2,3-BPG increases?","More oxygen unloading (right shift), as in chronic anemia, high altitude, and pyruvate kinase deficiency.","Glicólise diminui."],["1vf1idyfo","What is the main role of the liver in the fed state?","Glycogenesis, fatty acid synthesis, VLDL export; glucokinase traps glucose.","Armazena glicogênio e gordura."],["o4f2n1aev","What is the role of muscle and adipose in the fed state?","Muscle: glucose uptake (GLUT4), glycogen and protein synthesis. Adipose: glucose uptake, triglyceride storage (LPL activity).","Captam glicose e gordura."],["19zgugee1","What role does the kidney play in prolonged starvation?","It contributes significantly to gluconeogenesis (up to ~40%) and ammoniagenesis from glutamine.","Gliconeogênese."],["17dz0wye8","What is the Warburg effect?","Cancer cells preferentially use aerobic glycolysis (lactate production even with oxygen), supporting rapid growth.","Tumor usa glicólise aeróbia."]]},{"name":"Metabolism (Part 2)","cards":[["1gzczat10","What bonds link glucose in glycogen?","Alpha-1,4 bonds in linear chains and alpha-1,6 bonds at branch points.","Alfa-1,4 e alfa-1,6."],["22w6hj1w0","What is the role of glycogen in skeletal muscle?","Broken down to glucose-1-phosphate then G6P for rapid local energy during exercise.","Energia para contração."],["fisxzai0f","What is the role of glycogen in the liver?","Stored and broken down to maintain blood glucose during fasting.","Manter glicemia."],["1gyv6p33z","Which enzyme creates branches in glycogen?","Branching enzyme (glucosyl alpha-1,4:1,6 transferase).","Enzima ramificadora."],["39hxk0sef","Which enzyme breaks alpha-1,4 linkages to release glucose-1-phosphate?","Glycogen phosphorylase (requires pyridoxal phosphate, B6).","Glicogênio fosforilase."],["1j9b2abpp","What does debranching enzyme do?","Has two activities: 4-alpha-D-glucanotransferase moves 3 glucose units from a branch; alpha-1,6-glucosidase cleaves the branch point, releasing free glucose.","Remove ramificações."],["10wej261o","What is UDP-glucose used for?","Activated glucose donor for glycogen synthesis (made by UDP-glucose pyrophosphorylase).","Doador para síntese."],["iq8358boq","What enzyme degrades glycogen in lysosomes?","Acid alpha-glucosidase (acid maltase).","Alfa-glicosidase ácida."],["1i9k1mts6","How does epinephrine stimulate glycogenolysis in muscle?","Beta-adrenergic receptor raises cAMP, activating PKA, which activates phosphorylase kinase and glycogen phosphorylase.","Via AMPc."],["1glvlk6ly","How does calcium stimulate glycogenolysis in muscle?","Ca2+-calmodulin activates phosphorylase kinase during contraction.","Ativa fosforilase quinase."],["10kriclgq","How does insulin promote glycogen synthesis?","Activates protein phosphatase, dephosphorylating (activating) glycogen synthase and inactivating glycogen phosphorylase.","Ativa fosfatase."],["156r7ein6","Enzyme deficient in von Gierke disease (type I)?","Glucose-6-phosphatase.","Glicose-6-fosfatase."],["1u6efp31r","Clinical features of von Gierke disease?","Severe fasting hypoglycemia, very high liver glycogen (hepatomegaly), lactic acidosis, hyperuricemia (gout), hypertriglyceridemia, doll-like face.","Hipoglicemia grave, hepatomegalia."],["prs5mj1ad","Treatment of von Gierke disease?","Frequent oral glucose/cornstarch; avoid fructose and galactose.","Refeições frequentes, amido de milho."],["1cmgiud8p","Why does von Gierke disease cause lactic acidosis and hyperuricemia?","G6P accumulates and is diverted to glycolysis (lactate) and HMP shunt (more purine production and breakdown).","G6P desviada."],["1wk7i501q","Enzyme deficient in Pompe disease (type II)?","Lysosomal acid alpha-glucosidase (acid maltase).","Alfa-glicosidase ácida."],["6gmt4gshl","Clinical features of Pompe disease?","Cardiomyopathy, hypotonia, exercise intolerance, macroglossia, early death in infantile form. Pompe trashes the pump (heart, liver, muscle).","Cardiomegalia e hipotonia."],["15vp4l91p","Why is Pompe disease also a lysosomal storage disease?","The deficient enzyme is lysosomal, so glycogen accumulates in lysosomes.","Glicogênio em lisossomos."],["11e01vx1f","Enzyme deficient in Cori disease (type III)?","Debranching enzyme (alpha-1,6-glucosidase).","Desramificadora."],["1hk6ltses","Clinical features of Cori disease?","Milder form of type I with normal blood lactate; limit dextrin-like structures accumulate in cytosol; hepatomegaly, hypoglycemia, myopathy.","Von Gierke mais leve."],["y0zexh1c5","Enzyme deficient in McArdle disease (type V)?","Skeletal muscle glycogen phosphorylase (myophosphorylase).","Fosforilase muscular."],["1qd7nxjra","Clinical features of McArdle disease?","Exercise intolerance, painful muscle cramps, myoglobinuria with strenuous exercise, arrhythmia from electrolyte changes; normal blood glucose.","Cãibras e mioglobinúria."],["m9i0d3eoc","What is the 'second wind' phenomenon in McArdle disease?","Improved exercise tolerance after a rest, due to increased muscular blood flow and use of other fuels.","Melhora com ácidos graxos."],["1x3t4ib1x","What happens to blood lactate after exercise in McArdle disease?","Fails to rise (no glycogen breakdown), while ammonia rises.","Lactato não sobe."],["yenytk16o","Enzyme deficient in Andersen disease (type IV)?","Branching enzyme; abnormal glycogen causes liver cirrhosis and early death.","Ramificadora."],["nyi21s1oj","Enzyme deficient in Hers disease (type VI)?","Hepatic glycogen phosphorylase; mild hepatomegaly and hypoglycemia.","Fosforilase hepática."],["1xm14mf18","Mnemonic for glycogen storage diseases I-V?","Very Poor Carbohydrate Metabolism: Von Gierke, Pompe, Cori, McArdle (Andersen IV).","Very Poor Carbohydrate Metabolism."],["1shma6rlz","Defect in essential fructosuria?","Fructokinase deficiency; benign, autosomal recessive.","Frutoquinase."],["1nubu0g1n","Findings in essential fructosuria?","Fructose in blood and urine (positive reducing sugar test), asymptomatic. Fructose is metabolized by hexokinase instead.","Frutose na urina, benigno."],["1033lb413","Defect in hereditary fructose intolerance?","Aldolase B deficiency; fructose-1-phosphate accumulates, trapping phosphate and inhibiting glycogenolysis and gluconeogenesis.","Aldolase B."],["cjkxqrvb8","Clinical features of hereditary fructose intolerance?","Hypoglycemia, jaundice, cirrhosis, vomiting after eating fruit, juice, honey, or sucrose; positive urine reducing sugar.","Hipoglicemia e vômito após frutose."],["1idi4m71j","Treatment of hereditary fructose intolerance?","Avoid fructose and sucrose (and sorbitol).","Evitar frutose e sacarose."],["wo40x416i","How does fructose enter glycolysis in the liver?","Fructokinase makes fructose-1-phosphate; aldolase B splits it into DHAP and glyceraldehyde; bypasses PFK-1.","Via frutoquinase."],["1gtd1at1s","Defect in galactokinase deficiency?","Hereditary deficiency of galactokinase; galactitol accumulates.","Galactoquinase."],["1b3n4xy14","Clinical features of galactokinase deficiency?","Relatively mild; galactose in blood and urine, infantile cataracts; may fail to track objects or develop a social smile.","Catarata infantil."],["1c666jwt0","Defect in classic galactosemia?","Absence of galactose-1-phosphate uridyltransferase (GALT), autosomal recessive.","GALT."],["4ujgjj7qo","Clinical features of classic galactosemia?","Failure to thrive, jaundice, hepatomegaly, infantile cataracts, intellectual disability after milk ingestion; risk of E. coli sepsis in neonates.","Icterícia, catarata, sepse por E. coli."],["13r2gab16","Treatment of classic galactosemia?","Exclude galactose and lactose (galactose + glucose) from the diet.","Evitar galactose e lactose."],["6lvkg1um2","Why do galactosemia patients get cataracts?","Galactose is reduced by aldose reductase to galactitol, which accumulates in the lens.","Galactitol acumula."],["c5hgp71pw","What is the sorbitol (polyol) pathway?","Aldose reductase converts glucose to sorbitol; sorbitol dehydrogenase converts sorbitol to fructose.","Glicose vira sorbitol."],["r0mup5hqs","Which tissues lack sorbitol dehydrogenase and so accumulate sorbitol?","Schwann cells, retina, lens, kidneys (have only aldose reductase).","Cristalino, nervo, retina, rim."],["wvh2vc931","What is the consequence of sorbitol accumulation in hyperglycemia?","Osmotic damage: cataracts, retinopathy, peripheral neuropathy (diabetes complications).","Catarata, neuropatia, retinopatia."],["1ax83dqsy","Which tissues have both enzymes and can metabolize sorbitol?","Liver, ovaries, seminal vesicles.","Fígado, ovário, vesícula seminal."],["emil1u1uu","What is lactase deficiency?","Insufficient lactase enzyme causing dietary lactose intolerance.","Falta lactase."],["fjka5cl75","Types of lactase deficiency?","Primary (age-related decline, common in non-European descent), secondary (loss of brush border from gastroenteritis, celiac), congenital (rare).","Primária, secundária, congênita."],["d1evd265j","Findings in lactose intolerance?","Bloating, cramps, flatulence, osmotic diarrhea; stool pH decreased; breath hydrogen increases with lactose challenge.","Distensão e diarreia."],["1qozj9r8d","Normal intestinal biopsy finding in primary lactose intolerance?","Normal mucosa (unlike celiac disease).","Normal."],["aa2m6820o","What are essential amino acids?","Phenylalanine, valine, threonine, tryptophan, isoleucine, methionine, histidine, leucine, lysine (PVT TIM HaLL).","Precisam da dieta."],["1l2kazns4","Which essential amino acids are purely ketogenic?","Leucine and lysine.","Leucina e lisina."],["v9gbsi55t","Which amino acids are positively charged (basic)?","Arginine, lysine, histidine.","Arginina, lisina, histidina."],["9conqwyn3","Which amino acids are acidic (negatively charged at body pH)?","Aspartic acid and glutamic acid.","Aspartato e glutamato."],["1ey96q81s","Which amino acid is the most basic?","Arginine.","Arginina."],["1bpvj021y","Why are histones rich in arginine and lysine?","These basic residues bind the negatively charged DNA.","Ligam o DNA negativo."],["19fx50kep","What is the role of the urea cycle?","Converts toxic ammonia into urea for excretion in urine, in the liver.","Elimina amônia."],["1ffjk075t","Where do the steps of the urea cycle take place?","First two steps (CPS I, OTC) in mitochondria; remaining steps in cytosol.","Mitocôndria e citosol."],["1k28a9112","What activates carbamoyl phosphate synthetase I?","N-acetylglutamate (made from acetyl-CoA and glutamate, stimulated by arginine).","N-acetilglutamato."],["1h0krkg13","Which amino acids donate nitrogen to urea?","Ammonia (via carbamoyl phosphate) and aspartate.","Aspartato e amônia."],["v5qv3gktd","Order of urea cycle intermediates?","Carbamoyl phosphate, citrulline, argininosuccinate, arginine, ornithine (+ urea). Mnemonic: Ordinarily, Careless Crappers Are Also Frivolous About Urination.","Ornitina, citrulina, argininossuccinato, arginina."],["1aryek23z","How is ammonia transported from muscle to liver?","As alanine (alanine-glucose cycle) and as glutamine.","Ciclo da glicose-alanina."],["8j8n0v14o","How is ammonia transported from peripheral tissues in general?","As glutamine (glutamine synthetase).","Glutamina."],["lxaq431c1","Mechanism of hyperammonemia toxicity?","Excess NH3 depletes alpha-ketoglutarate (forming glutamate), inhibiting the TCA cycle; also increases glutamine in astrocytes (cerebral edema).","Esgota alfa-cetoglutarato."],["3t20zbda7","Symptoms of hyperammonemia?","Tremor (asterixis), slurred speech, somnolence, vomiting, cerebral edema, blurred vision.","Tremor, fala arrastada, coma."],["d571kx1qc","Treatment of hyperammonemia?","Lactulose (acidifies GI tract, traps NH4+), rifaximin (reduces ammoniagenic bacteria), benzoate, phenylacetate/phenylbutyrate (bind amino acids for excretion).","Lactulose, rifaximina, dieta."],["z5tj9s1ll","How does benzoate lower ammonia?","Combines with glycine to form hippurate, which is excreted.","Liga glicina."],["1a8cte17r","How does phenylbutyrate lower ammonia?","Converted to phenylacetate, which combines with glutamine to form phenylacetylglutamine, excreted in urine.","Liga glutamina."],["1yzupn54f","Most common urea cycle disorder?","Ornithine transcarbamylase (OTC) deficiency, X-linked recessive.","Deficiência de OTC."],["a0w3fj1jl","Key findings of OTC deficiency?","Hyperammonemia in first few days of life, increased orotic acid in blood and urine, decreased BUN, no megaloblastic anemia.","Orotato alto, ureia baixa."],["1r0tn1h1c","Why does orotic acid rise in OTC deficiency?","Excess carbamoyl phosphate is diverted to pyrimidine synthesis.","Carbamoil fosfato desviado."],["1lmipzcu2","How do you distinguish CPS I deficiency from OTC deficiency?","Both cause hyperammonemia, but orotic acid is normal in CPS I deficiency and high in OTC deficiency.","CPS I sem orotato."],["1gbvun716","What is N-acetylglutamate synthase deficiency?","Inability to activate CPS I, causing hyperammonemia; treated with carglumic acid (an analog of N-acetylglutamate).","Sem ativador da CPS I."],["9wcjd6q7r","What are the derivatives of phenylalanine and tyrosine?","Tyrosine, then DOPA, dopamine, norepinephrine, epinephrine; also thyroxine and melanin.","Dopamina, NE, adrenalina, melanina."],["rgr4ca1fp","What is the derivative of tryptophan?","Niacin (B3), serotonin, and melatonin.","Serotonina, niacina, melatonina."],["1igy8j4ow","What is the derivative of histidine?","Histamine (by histidine decarboxylase).","Histamina."],["6s7twqiqy","What is the derivative of glycine?","Porphyrin, then heme (with succinyl-CoA).","Heme, glutationa, creatina."],["15en4b3fv","What is the derivative of glutamate?","GABA (glutamate decarboxylase, B6) and glutathione.","GABA e glutationa."],["13j6ykuq6","What are derivatives of arginine?","Creatine, urea, nitric oxide.","NO, creatina, ureia."],["5j6m81b2e","Which cofactor is needed by phenylalanine hydroxylase and tyrosine hydroxylase?","Tetrahydrobiopterin (BH4).","BH4."],["1g99elh11","Which enzyme converts dopamine to norepinephrine and its cofactor?","Dopamine beta-hydroxylase; requires vitamin C (and copper).","Dopamina beta-hidroxilase; vitamina C."],["riqsy7gu8","Which enzyme converts norepinephrine to epinephrine and its cofactor?","Phenylethanolamine N-methyltransferase (PNMT), using SAM; induced by cortisol.","PNMT; SAM."],["1y1g5i41e","Why is the adrenal medulla near the cortex functionally important?","Cortisol from the cortex flows through the medulla and induces PNMT, increasing epinephrine synthesis.","Cortisol ativa PNMT."],["xvz50z1o5","Which enzyme converts DOPA to dopamine and its cofactor?","DOPA decarboxylase (aromatic L-amino acid decarboxylase), requires B6.","DOPA descarboxilase; B6."],["1u6r32gj0","Breakdown products of norepinephrine and epinephrine?","Normetanephrine, metanephrine, and vanillylmandelic acid (VMA) via COMT and MAO.","Ácido vanilmandélico."],["1uaq7s0a7","Breakdown product of dopamine?","Homovanillic acid (HVA).","Ácido homovanílico."],["1s7x94c8e","Breakdown product of serotonin?","5-hydroxyindoleacetic acid (5-HIAA), elevated in carcinoid syndrome.","5-HIAA."],["1gf9q5a6w","Defect in classic phenylketonuria?","Decreased phenylalanine hydroxylase, autosomal recessive.","Fenilalanina hidroxilase."],["1mhps4n14","Defect in malignant (atypical) PKU?","Decreased tetrahydrobiopterin (BH4) synthesis or recycling (e.g., dihydropteridine reductase deficiency).","Falta BH4."],["uvkn5g1lv","Why does tyrosine become essential in PKU?","Phenylalanine cannot be converted to tyrosine.","Não é produzida."],["1ezopkpc1","Clinical features of untreated PKU?","Intellectual disability, growth retardation, seizures, fair skin, eczema, musty body odor.","Retardo, odor de mofo, pele clara."],["1p35ws9y9","Treatment of PKU?","Restrict phenylalanine and supplement tyrosine; sapropterin (BH4 analog) in some patients.","Dieta sem fenilalanina."],["s4ubfnkg9","Why should people with PKU avoid aspartame?","Aspartame contains phenylalanine.","Contém fenilalanina."],["h2hk081g1","What is maternal PKU?","Lack of dietary control in a pregnant woman with PKU; causes microcephaly, intellectual disability, growth retardation, and congenital heart defects in the infant.","Mãe com PKU lesa feto."],["1sv2hho1i","When is PKU screened for?","Newborn screening, 2-3 days after birth (after protein feeding).","Teste do pezinho."],["hf1sfdntl","Defect in maple syrup urine disease?","Blocked degradation of branched-chain amino acids (isoleucine, leucine, valine) due to deficient branched-chain alpha-ketoacid dehydrogenase (B1).","Desidrogenase de alfa-cetoácidos."],["1t01tuibd","Clinical features of maple syrup urine disease?","Increased alpha-ketoacids in blood (especially leucine), severe CNS defects, intellectual disability, death; urine smells like maple syrup or burnt sugar.","Urina com cheiro de xarope."],["1yq0h1y15","Treatment of maple syrup urine disease?","Restrict isoleucine, leucine, valine; give thiamine supplementation.","Restringir aminoácidos ramificados."],["r9d8ygcrf","Mnemonic for maple syrup urine disease amino acids?","I Love Vermont maple syrup: Isoleucine, Leucine, Valine.","I Love Vermont."],["yjp51h1sm","Defect in alkaptonuria?","Congenital deficiency of homogentisate oxidase in tyrosine degradation; homogentisic acid accumulates. Autosomal recessive.","Ácido homogentísico oxidase."],["56r45y1j3","Clinical features of alkaptonuria?","Dark connective tissue (ochronosis), brown pigmented sclerae, urine turns black on prolonged exposure to air, debilitating arthralgias (homogentisic acid toxic to cartilage).","Urina escura, ocronose, artrite."],["1smeqe21q","What is homocystinuria?","Autosomal recessive defects causing high homocysteine: cystathionine synthase deficiency (most common), decreased affinity for its cofactor B6, or methionine synthase/MTHFR deficiency.","Homocisteína alta."],["shh8wb1q4","Clinical features of homocystinuria?","Very high homocysteine in urine, intellectual disability, osteoporosis, marfanoid habitus, kyphosis, lens subluxation (down and in), thrombosis, atherosclerosis.","Marfanoide, trombose, lente para baixo."],["1gke56p1w","Treatment of homocystinuria from cystathionine synthase deficiency?","Decrease methionine, increase cysteine, B6, B12, folate in diet (B6 responsive forms).","Dieta e B6."],["1be97nk11","Why does cysteine become essential in homocystinuria (cystathionine synthase deficiency)?","Cysteine cannot be made from homocysteine.","Não é produzida."],["8wnonx1o5","Defect in cystinuria?","Hereditary defect of the renal PCT and intestinal amino acid transporter for cystine, ornithine, lysine, arginine (COLA).","Transportador de aminoácidos."],["2do45q16m","Clinical features of cystinuria?","Excess cystine in urine forming recurrent hexagonal cystine stones.","Cálculos renais."],["1bxh76tsn","Diagnosis of cystinuria?","Urinary sodium-cyanide nitroprusside test and hexagonal crystals on urinalysis.","Cristais hexagonais."],["de5wg21n9","Treatment of cystinuria?","Urinary alkalinization (potassium citrate, acetazolamide), chelating agents (penicillamine, tiopronin), high fluid intake.","Hidratação e alcalinização."],["hyo7eq1bp","What is Hartnup disease?","Autosomal recessive defect in neutral amino acid transporter (e.g., tryptophan) in renal PCT and intestine, causing pellagra-like symptoms; treated with niacin and high-protein diet.","Perda de triptofano; pelagra."],["16pa39h1h","What is the defect in oculocutaneous albinism?","Deficient tyrosinase (cannot make melanin from tyrosine) or defective tyrosine transporters; increased skin cancer risk.","Falta tirosinase."],["118st3o6z","What is the defect in tyrosinemia type I?","Fumarylacetoacetate hydrolase deficiency causing liver failure, renal tubular dysfunction (Fanconi), cabbage-like odor; treated with nitisinone.","Fumarilacetoacetato hidrolase."],["19w0h5d1k","What is the defect in propionic acidemia?","Propionyl-CoA carboxylase deficiency; ketoacidosis and hyperammonemia in neonates (poor feeding, vomiting, hypotonia).","Propionil-CoA carboxilase."],["1cpniv8qj","What is the defect in methylmalonic acidemia?","Methylmalonyl-CoA mutase deficiency (or B12 defects); anion gap metabolic acidosis, hyperammonemia, hypoglycemia in neonates.","Metilmalonil-CoA mutase."],["d3y8vt1s8","Which amino acids are metabolized via propionyl-CoA?","Valine, odd-chain fatty acids, methionine, isoleucine, threonine (VOMIT).","VOMIT."],["juuo2d3gp","What are lysosomal storage diseases?","Inherited deficiencies of lysosomal enzymes causing accumulation of their substrates (sphingolipids, mucopolysaccharides).","Falta de enzima lisossomal."],["uccxsk1b0","Enzyme deficit and accumulated substrate in Tay-Sachs disease?","Hexosaminidase A; GM2 ganglioside.","Hexosaminidase A; GM2."],["1t9a3q41y","Clinical features of Tay-Sachs disease?","Progressive neurodegeneration, developmental delay, hyperreflexia, hyperacusis, cherry-red spot on macula, lysosomes with onion skin, no hepatosplenomegaly.","Mancha vermelha, sem hepatomegalia."],["1s84w8qak","How do you distinguish Tay-Sachs from Niemann-Pick clinically?","Both have cherry-red spot and neurodegeneration, but Niemann-Pick has hepatosplenomegaly and Tay-Sachs does not.","Niemann-Pick tem hepatomegalia."],["qv6kqh1f9","Enzyme deficit and substrate in Niemann-Pick disease?","Sphingomyelinase; sphingomyelin. Foam cells (lipid-laden macrophages), hepatosplenomegaly, cherry-red spot, neurodegeneration.","Esfingomielinase; esfingomielina."],["dfy69wvsy","Enzyme deficit and substrate in Gaucher disease?","Glucocerebrosidase (beta-glucosidase); glucocerebroside.","Glicocerebrosidase."],["1teofncxo","Clinical features of Gaucher disease?","Hepatosplenomegaly, pancytopenia, osteoporosis, avascular necrosis of femur, bone crises, Gaucher cells (crumpled tissue paper macrophages).","Hepatoesplenomegalia, dor óssea."],["q6lpo41tt","Treatment of Gaucher disease?","Recombinant glucocerebrosidase (enzyme replacement) or substrate reduction (eliglustat).","Reposição enzimática."],["u25ftx11d","Enzyme deficit and substrate in Fabry disease?","Alpha-galactosidase A; ceramide trihexoside (globotriaosylceramide). X-linked recessive.","Alfa-galactosidase A; Gb3."],["26cwux9h4","Clinical features of Fabry disease?","Early: peripheral neuropathy (burning pain in hands/feet), angiokeratomas, hypohidrosis. Late: progressive renal failure, cardiovascular disease.","Dor, angioqueratomas, rim."],["1l8ofme1s","Enzyme deficit and substrate in Krabbe disease?","Galactocerebrosidase; galactocerebroside and psychosine.","Galactocerebrosidase."],["1j2zicq15","Clinical features of Krabbe disease?","Peripheral neuropathy, destruction of oligodendrocytes, developmental delay, optic atrophy, globoid cells.","Neuropatia e atrofia óptica."],["13mu9fk16","Enzyme deficit and substrate in metachromatic leukodystrophy?","Arylsulfatase A; cerebroside sulfate. Central and peripheral demyelination with ataxia and dementia.","Arilsulfatase A; sulfatídeos."],["er9iek1uh","Enzyme deficit in Hurler syndrome?","Alpha-L-iduronidase; heparan and dermatan sulfate accumulate. Autosomal recessive.","Alfa-L-iduronidase."],["1iqm7mi1c","Clinical features of Hurler syndrome?","Developmental delay, gargoylism, airway obstruction, corneal clouding, hepatosplenomegaly.","Face grosseira, opacidade córnea."],["w2t8mgcrr","Enzyme deficit in Hunter syndrome?","Iduronate-2-sulfatase; heparan and dermatan sulfate. X-linked recessive.","Iduronato sulfatase."],["1lcv9nj1j","How does Hunter syndrome differ from Hurler syndrome?","Hunter is milder, X-linked, with aggressive behavior and no corneal clouding. Mnemonic: Hunters see clearly (no corneal clouding) and aim for the X.","Sem opacidade córnea."],["ofqiv1t1a","Which lysosomal storage diseases are X-linked recessive?","Fabry disease and Hunter syndrome; all others are autosomal recessive.","Fabry e Hunter."],["vn6ym1ckz","Which lysosomal storage diseases are more common in Ashkenazi Jews?","Tay-Sachs, Niemann-Pick, Gaucher (some forms).","Tay-Sachs, Gaucher, Niemann-Pick."],["16xe0711x","What is the role of the mucopolysaccharides normally?","Glycosaminoglycans in extracellular matrix (heparan sulfate, dermatan sulfate), degraded in lysosomes.","Matriz extracelular."],["uiheie15i","Which tests diagnose many lysosomal storage diseases?","Enzyme activity assays in leukocytes/fibroblasts, urinary GAGs for mucopolysaccharidoses, genetic testing.","Atividade enzimática."],["1vvxkqmro","Which amino acid is the main carrier of nitrogen in blood?","Glutamine (and alanine from muscle).","Glutamina e alanina."],["78fr72n7c","Which enzyme removes amino groups as free ammonia in the liver?","Glutamate dehydrogenase (oxidative deamination of glutamate).","Glutamato desidrogenase."],["33vmspxkl","What do aminotransferases (transaminases) require?","Pyridoxal phosphate (vitamin B6).","B6."],["1qm5ntk6a","What does ALT catalyze?","Alanine + alpha-ketoglutarate to pyruvate + glutamate.","Alanina para piruvato."],["1nc8lw66r","What does AST catalyze?","Aspartate + alpha-ketoglutarate to oxaloacetate + glutamate.","Aspartato para oxaloacetato."],["ax1715k5j","Which neurotransmitter is synthesized from glutamate using B6?","GABA (glutamate decarboxylase).","GABA."],["184lf33hr","What is SAM and what does it do?","S-adenosylmethionine; universal methyl donor (e.g., NE to epinephrine), made from methionine and ATP.","Doador de metil."],["6a5h8m15a","What does homocysteine methylation to methionine require?","Methionine synthase with vitamin B12 and N5-methyl-THF (folate).","B12 e folato."],["1c1eetbam","Why do B12 and folate deficiency both raise homocysteine?","Both are needed for methionine synthase to remethylate homocysteine.","Ambos remetilam."],["12omuh4lj","Why does only B12 deficiency raise methylmalonic acid?","Methylmalonyl-CoA mutase requires B12 but not folate.","Só B12 na mutase."],["xcey7b7lm","Which pathway makes cysteine from homocysteine?","Transsulfuration: cystathionine synthase (B6) combines homocysteine and serine to cystathionine, then to cysteine.","Transulfuração."],["twing9g5m","What is the precursor of nitric oxide and which enzyme makes it?","Arginine; nitric oxide synthase (NOS), producing citrulline as byproduct.","Arginina; NO sintase."],["16ia9cz1y","How is creatinine formed?","Spontaneous breakdown of creatine phosphate in muscle; excreted by kidneys at a fairly constant rate.","Creatina fosfato."],["cb3gqpin9","What is carnitine synthesized from?","Lysine and methionine.","Lisina e metionina."],["13mhqam1w","Which amino acids are needed to make heme?","Glycine (with succinyl-CoA), by ALA synthase (B6 required).","Glicina e succinil-CoA."],["1flypvl1a","What is the main inhibitory neurotransmitter derived from glycine metabolism in the spinal cord?","Glycine itself is the main inhibitory neurotransmitter in the spinal cord (strychnine blocks its receptor).","Glicina."],["3b5a8i4zj","Which disease causes elevated glycine with severe neonatal seizures?","Nonketotic hyperglycinemia (glycine cleavage system defect).","Hiperglicinemia não cetótica."],["8acxnl8bt","What are the ketone body precursors from amino acids?","Ketogenic amino acids yield acetyl-CoA or acetoacetyl-CoA (leucine, lysine, and partially PITTT).","Leucina e lisina."],["1afdx0nlr","Which amino acid is the precursor of melatonin and in which gland is it made?","Tryptophan (via serotonin); pineal gland.","Triptofano; pineal."],["1u86ni52m","Which enzyme converts histidine to histamine and its cofactor?","Histidine decarboxylase; vitamin B6.","Histidina descarboxilase; B6."],["1rap5vqax","What are the urine findings in galactosemia that can mislead on glucose testing?","Reducing substance present (galactose) but negative glucose oxidase dipstick.","Teste redutor positivo."],["lqvzws1yd","Which glycogen storage disease has hepatomegaly with normal blood lactate and high limit dextrins?","Cori disease (type III).","Hers."],["1t91fgb2d","What is the inheritance of glycogen storage diseases types I-V?","Autosomal recessive.","Autossômica recessiva."],["8lmgk11y4","What causes increased orotic acid with hyperammonemia and low citrulline?","Ornithine transcarbamylase deficiency.","OTC."],["1aovwuz9z","What is the defect in argininosuccinate lyase deficiency and a typical hair finding?","Argininosuccinic aciduria; trichorrhexis nodosa (brittle, nodular hair) with hyperammonemia.","Argininossuccinato liase; tricorrexe."],["1xut4tffs","What is arginase deficiency's typical presentation?","Progressive spastic diplegia and developmental delay with mild hyperammonemia and high arginine; treated with low-protein diet.","Diplegia espástica."],["fpbpgtugu","What does an elevated ammonia with respiratory alkalosis in a neonate suggest?","A urea cycle disorder (ammonia stimulates the respiratory center).","Defeito do ciclo da ureia."]]},{"name":"Metabolism (Part 3)","cards":[["1br3z9j19","Where does fatty acid synthesis occur?","Cytoplasm, mainly in liver, lactating mammary glands, and adipose tissue.","Citosol."],["1yn3bwqq8","How is acetyl-CoA moved from mitochondria to cytosol for fatty acid synthesis?","As citrate via the citrate shuttle; ATP citrate lyase regenerates acetyl-CoA in the cytosol. Mnemonic: Sytrate = synthesis.","Lançadeira do citrato."],["151dbgrxe","What does acetyl-CoA carboxylase do and what does it require?","Converts acetyl-CoA to malonyl-CoA; requires biotin and ATP.","Faz malonil-CoA; biotina."],["1ddne6e1o","Regulation of acetyl-CoA carboxylase?","Activated by insulin and citrate; inhibited by glucagon, epinephrine, and palmitoyl-CoA.","Insulina ativa; glucagon inibe."],["5htewoyiw","What enzyme complex elongates fatty acids to palmitate?","Fatty acid synthase (contains B5 as phosphopantetheine), using NADPH.","Ácido graxo sintase."],["zpgp0g13t","What is the end product of fatty acid synthase?","Palmitate (16-carbon saturated fatty acid).","Palmitato."],["1vrrx40d8","Why is NADPH needed for fatty acid synthesis?","It provides reducing equivalents for the reductive steps; supplied by the HMP shunt and malic enzyme.","Redução."],["1k04re973","Where does beta-oxidation of fatty acids occur?","Mitochondrial matrix (very-long-chain fatty acids begin in peroxisomes).","Mitocôndria."],["1lvj9i91g","How are long-chain fatty acids transported into mitochondria?","Carnitine shuttle: CPT I attaches carnitine (acylcarnitine), translocase moves it across, CPT II regenerates acyl-CoA. Mnemonic: Carnitine = carnage of fatty acids.","Carnitina."],["16x7s1l1x","What inhibits carnitine acyltransferase I?","Malonyl-CoA, preventing simultaneous synthesis and oxidation of fatty acids.","Malonil-CoA."],["16nczs91r","What are the products of each beta-oxidation cycle?","One acetyl-CoA, one NADH, and one FADH2, shortening the chain by 2 carbons.","Acetil-CoA, NADH, FADH2."],["hr32vm1s1","What is the product of oxidation of odd-chain fatty acids?","Propionyl-CoA, which can enter the TCA cycle as succinyl-CoA (gluconeogenic).","Propionil-CoA."],["1wox0vg15","Clinical features of systemic primary carnitine deficiency?","Inability to transport long-chain fatty acids into mitochondria: weakness, hypotonia, hypoketotic hypoglycemia, cardiomyopathy.","Hipoglicemia sem cetose, fraqueza."],["127jao6sq","What is the defect in medium-chain acyl-CoA dehydrogenase (MCAD) deficiency?","Inability to break down medium-chain fatty acids into acetyl-CoA; accumulation of 8-10 carbon fatty acyl carnitines.","Falta MCAD."],["8uq6qtafy","Clinical features of MCAD deficiency?","Hypoketotic hypoglycemia after fasting or illness, vomiting, lethargy, seizures, coma, liver dysfunction, hyperammonemia; possible sudden death in infancy.","Hipoglicemia no jejum."],["1uwu6qx1w","Treatment of MCAD deficiency?","Avoid fasting; frequent feeds; carbohydrate during illness.","Evitar jejum."],["1k8hj57he","Why is hypoglycemia 'hypoketotic' in fatty acid oxidation defects?","Without beta-oxidation, the liver cannot produce acetyl-CoA for ketones, and gluconeogenesis lacks energy and acetyl-CoA activation of pyruvate carboxylase.","Não oxida gordura."],["1s76bmf1i","What are the ketone bodies?","Acetoacetate and beta-hydroxybutyrate (acetone is a byproduct, causing fruity breath).","Acetoacetato e beta-hidroxibutirato."],["9r99irsj3","Where are ketone bodies made and from what?","Liver mitochondria, from acetyl-CoA derived from fatty acids and ketogenic amino acids.","Fígado; acetil-CoA."],["1rao53f2w","When are ketone bodies produced in large amounts?","Prolonged starvation, diabetic ketoacidosis, alcoholism, ketogenic diets.","Jejum, DM1, álcool."],["3b1h14wce","Why does oxaloacetate depletion promote ketogenesis?","In fasting/DKA, OAA is used for gluconeogenesis; in alcoholism, high NADH converts OAA to malate. Acetyl-CoA then goes to ketones instead of TCA.","Desvia acetil-CoA."],["y7vpcqeqg","Why does the urine dipstick for ketones miss beta-hydroxybutyrate?","The nitroprusside test detects acetoacetate (not beta-hydroxybutyrate), which predominates in DKA and alcoholic ketoacidosis.","Detecta só acetoacetato."],["11wnmtb1y","What is the main energy source of the brain in prolonged starvation?","Ketone bodies.","Cetonas."],["znwvta183","What is the function of chylomicrons?","Deliver dietary triglycerides to peripheral tissues and cholesterol to the liver (as remnants). Made by intestinal epithelial cells.","Gordura da dieta."],["1avtc3utw","What is the function of VLDL?","Delivers hepatic triglycerides to peripheral tissues. Secreted by the liver.","Triglicerídeos do fígado."],["11l32tn1u","What is IDL?","Formed from degradation of VLDL; delivers triglycerides and cholesterol to the liver.","Remanescente de VLDL."],["vjrjcsfyq","What is the function of LDL?","Delivers hepatic cholesterol to peripheral tissues; taken up by LDL receptor-mediated endocytosis (ApoB-100).","Leva colesterol aos tecidos."],["vjufqwfyt","What is the function of HDL?","Mediates reverse cholesterol transport from periphery to liver; acts as repository for ApoC-II and ApoE.","Transporte reverso."],["1aeigdn9x","Which drugs and conditions increase HDL synthesis?","Estrogen, alcohol, exercise; HDL is secreted from liver and intestine.","Estrógeno, álcool, niacina."],["10m9o85ww","What does lipoprotein lipase do?","Degrades triglycerides in circulating chylomicrons and VLDL into free fatty acids; found on vascular endothelium.","Libera ácidos graxos."],["31w4hy270","What does hepatic lipase do?","Degrades triglycerides remaining in IDL and chylomicron remnants.","Degrada remanescentes."],["1lfiw551e","What does hormone-sensitive lipase do?","Degrades stored triglycerides in adipocytes; activated by epinephrine, glucagon; inhibited by insulin.","Lipólise na gordura."],["17b1307nw","What does LCAT do?","Lecithin-cholesterol acyltransferase esterifies plasma cholesterol in HDL (activated by ApoA-I).","Esterifica colesterol."],["1tx6yg4nd","What does CETP do?","Cholesteryl ester transfer protein moves cholesteryl esters from HDL to other lipoprotein particles (VLDL, IDL, LDL).","Troca ésteres de colesterol."],["17xcygkyo","What does PCSK9 do?","Degrades LDL receptors; inhibiting it raises LDL receptor numbers and lowers LDL cholesterol.","Degrada receptor de LDL."],["1omcrd6i1","Function of ApoE?","Mediates remnant uptake by the liver; found on chylomicrons, chylomicron remnants, VLDL, IDL, HDL. E for Everything except LDL.","Captação de remanescentes."],["siab7utbv","Function of ApoA-I?","Activates LCAT; found on HDL (and chylomicrons).","Ativa LCAT."],["heehhd18g","Function of ApoC-II?","Cofactor for lipoprotein lipase; on chylomicrons, VLDL, HDL.","Ativa LPL."],["hf2u0c18e","Function of ApoB-48?","Mediates chylomicron secretion into lymphatics; only on chylomicrons (and remnants).","Monta quilomícron."],["6kq2dt18b","Function of ApoB-100?","Binds LDL receptor; on VLDL, IDL, LDL.","Liga receptor de LDL."],["b9kzmjztz","How are ApoB-48 and ApoB-100 made from the same gene?","RNA editing in the intestine creates a stop codon, producing the shorter ApoB-48.","Edição do RNA."],["1m01azcwe","What is abetalipoproteinemia?","Autosomal recessive deficiency of microsomal triglyceride transfer protein (MTP), causing absent ApoB-48 and ApoB-100 lipoproteins.","Falta ApoB."],["3cfnrdpun","Clinical features of abetalipoproteinemia?","Presents in infancy: failure to thrive, steatorrhea, acanthocytosis, ataxia, night blindness (vitamin E and A deficiency); intestinal biopsy shows lipid-laden enterocytes.","Esteatorreia, acantócitos, ataxia."],["1mouflx9z","Treatment of abetalipoproteinemia?","Restrict long-chain fatty acids and give large doses of oral vitamin E.","Vitamina E e restringir gordura."],["1ps2gie9h","Defect in familial dyslipidemia type I (hyperchylomicronemia)?","Autosomal recessive LPL deficiency or ApoC-II defect.","Falta LPL ou ApoC-II."],["1t961qa1h","Lab and clinical findings of type I familial dyslipidemia?","High chylomicrons, very high triglycerides; recurrent acute pancreatitis, hepatosplenomegaly, eruptive/pruritic xanthomas; no increased atherosclerosis risk. Creamy layer in standing plasma.","Plasma leitoso, pancreatite."],["1kvoudvbl","Defect in type II familial hypercholesterolemia?","Autosomal dominant absent or defective LDL receptors, or defective ApoB-100, or PCSK9 gain of function.","Receptor de LDL."],["18mr8wk1v","Lab findings of type IIa vs IIb?","IIa: high LDL and cholesterol. IIb: high LDL, cholesterol, and VLDL.","IIa LDL; IIb LDL e VLDL."],["qcqaa7kjg","Defect in type III familial dysbetalipoproteinemia?","Autosomal recessive ApoE2 variant (binds poorly to receptors).","ApoE2."],["1l5x9s91k","Lab and clinical findings of type III dyslipidemia?","High chylomicron remnants and IDL; premature atherosclerosis, tuberoeruptive xanthomas, palmar xanthomas.","Xantomas palmares."],["141h4eu1b","Defect in type IV familial hypertriglyceridemia?","Autosomal dominant hepatic overproduction of VLDL.","Mais VLDL."],["8wr85b18s","Lab and clinical findings of type IV dyslipidemia?","High VLDL and triglycerides; hypertriglyceridemia (>1000 mg/dL) can cause acute pancreatitis; related to insulin resistance.","TG alto, pancreatite."],["1il1lx613","Which apolipoprotein E allele increases risk of late-onset Alzheimer disease?","ApoE4 (ApoE2 is protective).","ApoE4."],["d3wbfg1de","What is the first committed step of cholesterol synthesis?","HMG-CoA to mevalonate by HMG-CoA reductase.","HMG-CoA redutase."],["1vsqau92i","What does cholesterol serve as a precursor for?","Steroid hormones, bile acids, vitamin D; also a membrane component.","Hormônios, bile, vitamina D."],["1xudyu81n","How do statins lower LDL?","Inhibit HMG-CoA reductase, lowering hepatic cholesterol, which upregulates LDL receptors and increases LDL clearance.","Inibem HMG-CoA redutase."],["1bpl5g9np","What is the rate-limiting enzyme of bile acid synthesis?","Cholesterol 7-alpha-hydroxylase.","7-alfa-hidroxilase."],["imqyqnesu","How does cholestyramine lower LDL?","Binds bile acids in the gut, preventing reabsorption; liver uses more cholesterol to make bile acids, upregulating LDL receptors.","Liga ácidos biliares."],["iarwj81k9","How does ezetimibe lower LDL?","Blocks intestinal cholesterol absorption (NPC1L1 transporter) at the brush border.","Bloqueia absorção intestinal."],["1ijpv641g","How do fibrates lower triglycerides?","Activate PPAR-alpha, increasing lipoprotein lipase activity and decreasing VLDL production.","Ativam PPAR-alfa."],["11sl4wdoh","How does niacin affect lipids?","Inhibits hormone-sensitive lipase (lipolysis) and hepatic VLDL synthesis; lowers LDL and triglycerides, raises HDL.","HDL sobe, LDL e TG caem."],["17xksj9ed","Major side effects of niacin?","Flushing (prostaglandin-mediated, reduced by aspirin), hyperglycemia, hyperuricemia.","Rubor, hiperglicemia, gota."],["8glpwb3yp","Which lipid lowering agents cause myopathy, especially in combination?","Statins and fibrates (especially gemfibrozil), and niacin.","Estatina e fibrato."],["ah1ldj1m8","What fatty acids are essential and why?","Linoleic acid (omega-6) and alpha-linolenic acid (omega-3), because humans cannot introduce double bonds beyond carbon 9.","Linoleico e linolênico."],["xovrgw774","What is arachidonic acid synthesized from?","Linoleic acid; it is the precursor of eicosanoids (prostaglandins, thromboxanes, leukotrienes).","Linoleico."],["9rcbe61nq","Which enzymes make prostaglandins and leukotrienes from arachidonic acid?","Cyclooxygenase (COX-1/2) makes prostaglandins and thromboxanes; 5-lipoxygenase makes leukotrienes.","COX e lipoxigenase."],["mfkf10130","Which eicosanoids cause bronchoconstriction and increased vascular permeability?","Leukotrienes C4, D4, E4.","LTC4, D4, E4."],["1i79k361t","Which leukotriene is a neutrophil chemotactic agent?","LTB4 (neutrophils arrive B4 others).","LTB4."],["1msds6ui5","What does thromboxane A2 do?","Promotes platelet aggregation and vasoconstriction (made by platelets via COX-1).","Agrega plaquetas e vasoconstrição."],["4f1kpe1i9","What does prostacyclin (PGI2) do?","Inhibits platelet aggregation and causes vasodilation (made by endothelium).","Inibe plaquetas e vasodilata."],["iiqhkh1dh","Which drug inhibits 5-lipoxygenase?","Zileuton.","Zileuton."],["i3ac638l1","Which drugs block leukotriene receptors?","Montelukast and zafirlukast (CysLT1 receptor antagonists).","Montelucaste e zafirlucaste."],["1qhpwov5j","What is the first step and enzyme of heme synthesis?","Glycine + succinyl-CoA to delta-aminolevulinic acid (ALA) by ALA synthase in mitochondria (requires B6).","ALA sintase."],["wu2nh72c6","Which enzymes in heme synthesis are inhibited by lead?","ALA dehydratase and ferrochelatase.","ALA desidratase e ferroquelatase."],["xwbqpc134","Which step of heme synthesis is the final step?","Ferrochelatase inserts Fe2+ into protoporphyrin IX in mitochondria.","Ferroquelatase."],["1lmorpq1s","Which enzyme is deficient in acute intermittent porphyria?","Porphobilinogen deaminase (hydroxymethylbilane synthase), autosomal dominant.","Porfobilinogênio desaminase."],["xoe14v39q","Accumulated substances in acute intermittent porphyria?","Porphobilinogen, ALA (urine darkens on exposure to light).","PBG e ALA."],["fc3dh01ud","Clinical features of acute intermittent porphyria?","The 5 Ps: Painful abdomen, Port wine-colored urine, Polyneuropathy, Psychological disturbances, Precipitated by drugs (CYP450 inducers), alcohol, starvation.","Dor abdominal, urina roxa, psiquiátrico."],["55cins1rj","Treatment of acute intermittent porphyria?","Hemin and glucose (both inhibit ALA synthase).","Hemina e glicose."],["zkmjtn1p7","Enzyme deficient in porphyria cutanea tarda?","Uroporphyrinogen decarboxylase (most common porphyria).","Uroporfirinogênio descarboxilase."],["10fky5i1u","Clinical features of porphyria cutanea tarda?","Blistering cutaneous photosensitivity and hyperpigmentation, tea-colored urine; associated with hepatitis C and alcohol.","Bolhas em área exposta."],["gkgik3168","Clinical features of lead poisoning?","Microcytic anemia with basophilic stippling and ringed sideroblasts, abdominal colic, neuropathy (wrist/foot drop), lead lines on gums and long bone metaphyses, encephalopathy, nephropathy.","Anemia, cólica, neuropatia."],["1ib2hvl1k","Which substances accumulate in lead poisoning?","Protoporphyrin (free erythrocyte protoporphyrin/zinc protoporphyrin) and ALA in blood.","ALA e protoporfirina."],["6adpbzncr","Treatment of lead poisoning?","Chelation: dimercaprol and EDTA (severe); succimer for children; remove exposure.","Quelantes."],["1rgc2et1u","What is the most common cause of sideroblastic anemia that is congenital?","X-linked defect in ALA synthase (ALAS2), treated with pyridoxine.","Defeito ALA sintase."],["1x2pu3atl","Acquired causes of sideroblastic anemia?","Alcohol, lead poisoning, vitamin B6 deficiency (e.g., isoniazid), copper deficiency, myelodysplastic syndromes.","Álcool, chumbo, B6."],["b4bt9h10a","How is heme degraded?","Heme oxygenase converts heme to biliverdin (releasing CO and iron); biliverdin reductase converts to bilirubin.","Heme vira bilirrubina."],["471xnf1x8","How is bilirubin transported and conjugated?","Unconjugated bilirubin travels bound to albumin to the liver, where UDP-glucuronosyltransferase conjugates it.","Albumina; conjugada no fígado."],["dyk3q84rz","What happens to conjugated bilirubin in the gut?","Converted by bacteria to urobilinogen; some reabsorbed and excreted in urine as urobilin (yellow), most converted to stercobilin (brown stool).","Vira urobilinogênio."],["1recfkl12","Which disorder involves mildly decreased UDP-glucuronosyltransferase activity?","Gilbert syndrome: benign unconjugated hyperbilirubinemia with stress, fasting, illness.","Gilbert."],["2jpuvcd56","Which disorder involves absent UDP-glucuronosyltransferase?","Crigler-Najjar syndrome type I: severe unconjugated hyperbilirubinemia and kernicterus in infancy.","Crigler-Najjar tipo I."],["p3ndsn1rj","What is Dubin-Johnson syndrome?","Defective liver excretion of conjugated bilirubin (MRP2); conjugated hyperbilirubinemia and black liver; benign.","Fígado escuro."],["1kae5j15q","How does Rotor syndrome differ from Dubin-Johnson syndrome?","Rotor is milder and the liver is not black.","Rotor sem pigmento."],["f7tib91te","What is the role of bile salts?","Emulsify dietary fats forming micelles to aid absorption of fats and fat-soluble vitamins.","Emulsificam gordura."],["74rrz75w4","What happens to bile salts in the terminal ileum?","About 95% are reabsorbed and recycled (enterohepatic circulation).","Reabsorvidos."],["lslg9id6h","What lipid is the major component of lung surfactant?","Dipalmitoylphosphatidylcholine (lecithin).","Fosfatidilcolina."],["40929n1g2","What is the significance of a lecithin-to-sphingomyelin ratio > 2 in amniotic fluid?","Indicates fetal lung maturity.","Pulmão maduro."],["rzlm4f1hm","What type of molecules are sphingolipids?","Lipids built on sphingosine, including sphingomyelin, cerebrosides, gangliosides; important in nerve membranes and myelin.","Ceramida."],["yswd2a534","How are triglycerides digested and absorbed?","Pancreatic lipase breaks them into monoglycerides and free fatty acids, which form micelles, enter enterocytes, are re-esterified, and packaged into chylomicrons.","Lipase, micelas, quilomícrons."],["1ot2jqk1g","Why are medium-chain triglycerides useful in fat malabsorption?","They are absorbed directly into portal blood without micelles or chylomicrons.","Absorção direta."],["14w8nx2nl","What does an increased triglyceride level with milky plasma indicate?","Hyperchylomicronemia (type I or V dyslipidemia).","Quilomícrons altos."],["dx73ax1pg","Which lipoprotein carries the most cholesterol?","LDL.","LDL."],["1inraao36","Which lipoprotein carries the most triglyceride (by proportion)?","Chylomicrons.","Quilomícron."],["8x0ost1df","Which lipoprotein is the smallest and densest?","HDL.","HDL."],["5h7j8d4hb","What lipid abnormality is caused by nephrotic syndrome?","Hyperlipidemia (increased LDL and cholesterol) due to increased hepatic lipoprotein synthesis.","Hiperlipidemia."],["9atcokot1","What lipid abnormality is caused by hypothyroidism?","Increased LDL cholesterol due to fewer LDL receptors.","LDL alto."],["1qn7koz11","What lipid abnormality is caused by obstructive jaundice?","Increased cholesterol (lipoprotein X), causing xanthomas.","Lipoproteína X."],["22avt72n9","What is lipoprotein(a)?","LDL particle with apolipoprotein(a); elevated levels are an independent risk factor for atherosclerosis and thrombosis.","LDL com Apo(a)."],["bmp74u3xy","What causes xanthelasma?","Lipid-laden histiocytes in the eyelid skin, associated with hyperlipidemia (but can occur with normal lipids).","Hipercolesterolemia."],["nuwrgci6l","What are tendinous xanthomas strongly associated with?","Familial hypercholesterolemia (often in Achilles tendon).","Hipercolesterolemia familiar."],["1g0l3jnmm","What are eruptive xanthomas associated with?","Very high triglycerides (chylomicrons/VLDL), e.g., type I or uncontrolled diabetes.","Hipertrigliceridemia."],["295d0s1r2","What are palmar xanthomas associated with?","Type III dysbetalipoproteinemia.","Disbetalipoproteinemia."],["105hr6e1b","What is the source of free fatty acids in fasting?","Adipose triglyceride hydrolysis by hormone-sensitive lipase (activated by catecholamines, glucagon, low insulin).","Lipólise."],["60hbsy137","How is glycerol from lipolysis used?","Transported to the liver and converted by glycerol kinase to glycerol-3-phosphate, used for gluconeogenesis.","Gliconeogênese no fígado."],["xp9awm1bz","Why does insulin deficiency cause diabetic ketoacidosis?","Unrestrained lipolysis supplies fatty acids, glucagon promotes ketogenesis, and ketones accumulate faster than they are used.","Lipólise sem freio."],["1wdeee31m","What is the role of malonyl-CoA in regulating fatty acid metabolism?","Inhibits CPT I, preventing newly synthesized fatty acids from being oxidized.","Inibe CAT I."],["16kv11115","Which fatty acids need peroxisomal alpha-oxidation before beta-oxidation?","Branched-chain fatty acids with a methyl group at the beta carbon, such as phytanic acid.","Ramificados."],["dv07qs1n5","What lab finding supports a diagnosis of X-linked adrenoleukodystrophy?","Elevated plasma very-long-chain fatty acids (C26:0).","Ácidos graxos longos altos."],["1xr737y1l","What is the role of peroxisomes in plasmalogen synthesis?","Peroxisomes initiate synthesis of plasmalogens, important phospholipids in myelin.","Síntese de plasmalogênio."],["1y4ubhn7k","What does the enzyme 7-dehydrocholesterol reductase deficiency cause?","Smith-Lemli-Opitz syndrome: low cholesterol, microcephaly, syndactyly of 2nd and 3rd toes, ambiguous genitalia, intellectual disability.","Smith-Lemli-Opitz."],["114grrx1k","Which vitamins are absorbed with fat?","Vitamins A, D, E, K.","A, D, E, K."],["1necrjz17","How does orlistat cause weight loss?","Inhibits pancreatic and gastric lipases, decreasing fat absorption (side effects: steatorrhea, fat-soluble vitamin deficiency).","Inibe lipase."],["1xom25f5c","Why do triglycerides rise with alcohol use?","Ethanol metabolism increases NADH and glycerol-3-phosphate and fatty acid synthesis, increasing hepatic triglyceride and VLDL production.","Mais VLDL."],["1sxmsg11l","What happens to fatty acids in the liver in excess NADH from alcohol?","Beta-oxidation is inhibited and fatty acid synthesis increased, leading to hepatic steatosis.","Esteatose."],["g1xq8l37y","What is the major lipoprotein increased in the postprandial state?","Chylomicrons.","Quilomícron."],["v7iq5cv19","Which lipoproteins are atherogenic?","LDL, VLDL remnants, IDL, lipoprotein(a) (ApoB-containing particles).","LDL, VLDL, IDL, Lp(a)."],["1tgtljx1y","What are omega-3 fatty acids used for clinically?","Lowering triglycerides (fish oil, icosapent ethyl).","Reduzir triglicerídeos."],["1bm6hx1jf","What is the inheritance of familial hypercholesterolemia?","Autosomal dominant.","Autossômica dominante."],["xzb9096xu","What is the main enzyme for triglyceride synthesis in adipose tissue after a meal?","Lipoprotein lipase on capillary endothelium (stimulated by insulin) releases fatty acids for uptake and re-esterification.","LPL."],["1t77xu9sr","Why does adipose tissue need glucose to store triglycerides?","Adipocytes lack glycerol kinase, so they need glucose-derived DHAP to make glycerol-3-phosphate backbone.","Glicerol-3-fosfato."],["1fapqi52j","What is brown adipose tissue's special mitochondrial protein?","Thermogenin (UCP1), an uncoupler that generates heat.","Termogenina."],["11ybj3fva","Which lab is used to calculate LDL in the Friedewald equation?","LDL = total cholesterol - HDL - (triglycerides/5); inaccurate when triglycerides >400 mg/dL.","Colesterol total, HDL, TG."],["1c91vau10","What effect do PCSK9 inhibitors have on LDL?","Large reduction in LDL by preserving hepatic LDL receptors (e.g., alirocumab, evolocumab).","Reduzem muito."],["1fb3nve1n","What is the target of bempedoic acid?","ATP-citrate lyase inhibition, reducing cholesterol synthesis upstream of HMG-CoA reductase.","ATP citrato liase."],["1qn5s2clx","What is the most common inherited porphyria worldwide?","Porphyria cutanea tarda.","Porfiria cutânea tarda."],["rr07gi1hx","Which porphyria causes painful photosensitivity starting in childhood without blisters?","Erythropoietic protoporphyria (ferrochelatase deficiency).","Protoporfiria eritropoética."],["7543oa1g3","Why are barbiturates dangerous in acute intermittent porphyria?","They induce cytochrome P450, increasing heme demand and ALA synthase activity, precipitating attacks.","Induzem ALA sintase."],["18gpmx6u6","How many ATP does complete oxidation of palmitate yield (approximately)?","About 106 ATP (net), much more than glucose.","Cerca de 106 ATP."],["45s4sj1dw","What effect does glucagon have on lipolysis and ketogenesis?","Stimulates both: activates hormone-sensitive lipase and lowers malonyl-CoA, allowing fatty acids into mitochondria.","Aumenta ambos."],["1jyhdzzqs","What is the key difference between fatty acid synthesis and oxidation in terms of carrier?","Synthesis uses acyl carrier protein and NADPH in the cytosol; oxidation uses CoA, FAD, and NAD+ in mitochondria.","ACP vs CoA."]]},{"name":"Nutrition","cards":[["1ijgexr1q","Which vitamins are fat soluble?","A, D, E, K. Absorption depends on the gut and pancreas; toxicity is more common because they accumulate in fat.","A, D, E, K."],["xiwvoj1ov","Which conditions cause fat-soluble vitamin deficiency?","Malabsorption syndromes with steatorrhea: cystic fibrosis, celiac disease, pancreatic insufficiency, cholestasis, orlistat, mineral oil.","Má absorção de gordura."],["1tiovllg5","Which vitamins are water soluble?","B1, B2, B3, B5, B6, B7, B9, B12, and C. All wash out easily except B12 and folate (stored in liver).","Complexo B e C."],["cplq5d1pf","How long do liver stores of B12 last?","About 3-4 years (folate lasts about 3-4 months).","Anos."],["1mdp3341p","What are the functions of vitamin A (retinol)?","Antioxidant, component of visual pigments (retinal), needed for differentiation of epithelial cells into specialized tissue (e.g., mucus-secreting cells), prevents squamous metaplasia.","Visão, epitélio, imunidade."],["hty6zx1er","Clinical uses of vitamin A?","Treats measles and acute promyelocytic leukemia (all-trans retinoic acid), oral isotretinoin for severe acne, wrinkles and psoriasis.","Acne, sarampo, LPA."],["1wkppbb1t","Signs of vitamin A deficiency?","Night blindness (nyctalopia), dry scaly skin (xerosis cutis), corneal degeneration (keratomalacia), Bitot spots, immunosuppression.","Cegueira noturna, xeroftalmia."],["4moz3d19m","What are Bitot spots?","Foamy gray patches on the conjunctiva due to vitamin A deficiency (keratinization).","Manchas na conjuntiva."],["mmfizd1xu","Signs of acute vitamin A toxicity?","Nausea, vomiting, vertigo, blurred vision.","Náusea, visão turva."],["1jeay5mpv","Signs of chronic vitamin A toxicity?","Alopecia, dry skin (scaliness), hepatic toxicity and enlargement, arthralgias, idiopathic intracranial hypertension (pseudotumor cerebri).","Alopecia, pele seca, hepatotoxicidade."],["i09v67yti","Why is isotretinoin contraindicated in pregnancy?","Vitamin A derivatives are teratogenic (cleft palate, cardiac abnormalities, CNS defects); pregnancy test and contraception required.","Teratogênico."],["1red6fn1k","What is the active form of vitamin B1?","Thiamine pyrophosphate (TPP).","Pirofosfato de tiamina."],["fijh0i8ds","Which enzymes require thiamine?","Pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, transketolase, branched-chain ketoacid dehydrogenase. Mnemonic: ATP (alpha-ketoglutarate, transketolase, pyruvate) + BCKDH.","PDH, alfa-KG, transcetolase, BCKDH."],["1akqx5y21","How is thiamine deficiency diagnosed?","Increased RBC transketolase activity after adding thiamine.","Transcetolase da hemácia."],["1gexooz1i","What is Wernicke encephalopathy?","Acute thiamine deficiency triad: confusion, ophthalmoplegia (often lateral rectus/ nystagmus), ataxia.","Confusão, oftalmoplegia, ataxia."],["1n3cvcv18","What is Korsakoff syndrome?","Chronic thiamine deficiency: confabulation, personality change, permanent memory loss (anterograde and retrograde amnesia).","Amnésia e confabulação."],["n0ivjvc7s","Which brain structures are damaged in Wernicke-Korsakoff syndrome?","Mammillary bodies, medial dorsal thalamic nuclei, periaqueductal gray.","Corpos mamilares."],["kb6g5h1ox","What is dry beriberi?","Thiamine deficiency with symmetric peripheral neuropathy and muscle wasting.","Neuropatia."],["1r96ru411","What is wet beriberi?","Thiamine deficiency with high-output cardiac failure (dilated cardiomyopathy) and edema.","Insuficiência cardíaca."],["px9ub7ehc","Who is at risk for thiamine deficiency?","Alcoholics, malnourished people (polished rice diets), patients with hyperemesis, bariatric surgery, diuretic therapy.","Alcoolistas e desnutridos."],["m7haz7c73","Why should thiamine be given before glucose in alcoholics?","Giving glucose first increases thiamine use and can precipitate or worsen Wernicke encephalopathy.","Glicose consome tiamina."],["s8lv5u1uw","What are the active forms of vitamin B2 (riboflavin)?","FAD and FMN, used in redox reactions (e.g., succinate dehydrogenase).","FAD e FMN."],["10mtrgqux","Signs of riboflavin deficiency?","Cheilosis (inflamed lips, scaling at corners), angular stomatitis, glossitis, normocytic anemia, corneal vascularization. The 2 Cs of B2.","Queilite e glossite."],["1h3f3t0uj","What is vitamin B3 (niacin) used for?","Constituent of NAD+ and NADP+ (redox reactions).","NAD e NADP."],["19lvu8l1o","From which amino acid is niacin derived and which vitamins are required?","Tryptophan; requires B2 and B6.","Triptofano; B2 e B6."],["1d6awhx7a","Signs of niacin deficiency (pellagra)?","Diarrhea, dementia (and hallucinations), dermatitis (C3/C4 dermatome, Casal necklace, sun-exposed areas). The 3 Ds.","Dermatite, diarreia, demência."],["1lq0h1dpz","Causes of pellagra?","Hartnup disease (tryptophan absorption defect), malignant carcinoid syndrome (tryptophan diverted to serotonin), isoniazid (decreases B6), diets based on untreated corn.","Hartnup, carcinoide, isoniazida."],["b12dhm1d0","Signs of niacin excess?","Facial flushing (prostaglandin-mediated, prevent with aspirin), hyperglycemia, hyperuricemia.","Rubor."],["1703r2ub9","What is vitamin B5 (pantothenic acid) used for?","Component of coenzyme A (CoA) and fatty acid synthase.","Coenzima A."],["f9xamo1ge","Signs of pantothenic acid deficiency?","Dermatitis, enteritis, alopecia, adrenal insufficiency (rare).","Dermatite e alopecia."],["19p4hqugt","What is the active form of vitamin B6 (pyridoxine)?","Pyridoxal phosphate.","Piridoxal fosfato."],["185h6n86w","Which reactions require vitamin B6?","Transamination (ALT, AST), decarboxylation, glycogen phosphorylase, synthesis of cystathionine, heme, niacin, histamine, and neurotransmitters (serotonin, epinephrine, norepinephrine, dopamine, GABA).","Transaminação e descarboxilação."],["1syejde1c","Signs of vitamin B6 deficiency?","Convulsions, hyperirritability, peripheral neuropathy (often induced by isoniazid and oral contraceptives), sideroblastic anemia (impaired heme), cheilosis, stomatitis.","Convulsões e neuropatia."],["1v673k01u","Why does isoniazid cause neuropathy and how is it prevented?","Isoniazid causes B6 deficiency; give pyridoxine supplementation.","Isoniazida esgota B6; dar B6."],["1wira1e8h","What is vitamin B7 (biotin) a cofactor for?","Carboxylation enzymes: pyruvate carboxylase, acetyl-CoA carboxylase, propionyl-CoA carboxylase.","Carboxilases."],["1crk8owly","What causes biotin deficiency?","Rare; caused by antibiotics or eating large amounts of raw egg whites (avidin binds biotin).","Clara de ovo crua."],["1qh6975j7","Signs of biotin deficiency?","Dermatitis, alopecia, enteritis.","Dermatite e alopecia."],["5eerxr3yw","What is the active form of folate (B9)?","Tetrahydrofolic acid (THF), a coenzyme for 1-carbon transfer/methylation reactions.","Tetra-hidrofolato."],["1q05dk21s","What is folate important for?","Synthesis of nitrogenous bases in DNA and RNA (purines and thymidine).","Síntese de DNA."],["1hhep41ji","Where is folate absorbed and where is it found?","Jejunum; found in leafy green vegetables.","Jejuno; folhas verdes."],["1se42c31d","Signs of folate deficiency?","Macrocytic megaloblastic anemia, hypersegmented neutrophils, glossitis, no neurologic symptoms; high homocysteine, normal methylmalonic acid.","Anemia megaloblástica."],["15k8jvj18","Most common vitamin deficiency in the US?","Folate deficiency.","Folato."],["18xkawxbf","Causes of folate deficiency?","Alcoholism, pregnancy, poor diet, drugs (phenytoin, sulfonamides, methotrexate, trimethoprim).","Dieta, gestação, drogas."],["11t9kqup1","Why is folate supplemented before and during early pregnancy?","Folate deficiency increases neural tube defects.","Prevenir defeito de tubo."],["e39oft16b","What is vitamin B12 (cobalamin) a cofactor for?","Methionine synthase (transfers CH3 from N5-methyl-THF to homocysteine) and methylmalonyl-CoA mutase.","Metionina sintase e mutase."],["1vspyjl1p","Main dietary sources of B12?","Animal products only (synthesized by microorganisms).","Carne e laticínios."],["4liw363dh","Steps of B12 absorption?","Released from food by gastric acid, binds haptocorrin (R factor), freed by pancreatic proteases, binds intrinsic factor, absorbed in terminal ileum.","Fator intrínseco e íleo."],["1p2hyjr3d","Signs of B12 deficiency?","Macrocytic megaloblastic anemia, hypersegmented neutrophils, paresthesias, subacute combined degeneration (dorsal columns, lateral corticospinal tracts, spinocerebellar tracts).","Anemia e neuropatia."],["142hfu816","Lab findings that distinguish B12 from folate deficiency?","B12 deficiency: high homocysteine and high methylmalonic acid. Folate deficiency: high homocysteine only.","Ácido metilmalônico alto."],["113fu461q","Most common cause of B12 deficiency in the US?","Pernicious anemia (autoimmune destruction of parietal cells/ anti-intrinsic factor antibodies).","Anemia perniciosa."],["1jylt5d1b","Other causes of B12 deficiency?","Strict vegan diet, malabsorption (Crohn disease, ileal resection), gastric bypass, Diphyllobothrium latum, metformin, proton pump inhibitors.","Gastrectomia, Crohn, vegano."],["154azv61d","Why does B12 deficiency cause neurologic damage?","Methylmalonyl-CoA accumulates, causing abnormal myelin synthesis.","Mielina anormal."],["18feejej1","Why should B12 deficiency not be treated with folate alone?","Folate may correct the anemia but the neurologic damage progresses.","Folato não corrige neurologia."],["wpdacxdn7","What is the function of vitamin C (ascorbic acid)?","Antioxidant; facilitates iron absorption (keeps iron Fe2+); needed for hydroxylation of proline and lysine in collagen; cofactor for dopamine beta-hydroxylase.","Antioxidante e colágeno."],["1xbsegs1a","Signs of vitamin C deficiency (scurvy)?","Swollen gums, easy bruising, petechiae, perifollicular hemorrhage, corkscrew hairs, poor wound healing, anemia, weakened immune response, hemarthrosis.","Gengivas, hematomas, cabelo em saca-rolha."],["cl2fk51gq","Who is at risk for scurvy?","People with diets lacking fruits/vegetables (e.g., elderly, alcoholics, restrictive eating disorders).","Dieta sem frutas."],["1emfs8b1c","Signs of vitamin C excess?","Nausea, vomiting, diarrhea, fatigue, calcium oxalate nephrolithiasis; increased iron toxicity in predisposed individuals (hemochromatosis).","Cálculos de oxalato."],["1f0qrhz8b","What are the forms of vitamin D?","D2 (ergocalciferol, from plants/fungi), D3 (cholecalciferol, from sun exposure in skin and fish/milk), 25-OH D3 (storage form), 1,25-(OH)2 D3 (calcitriol, active form).","D2 e D3."],["r2yvyw7lz","Where is vitamin D hydroxylated?","Liver (25-hydroxylation) and kidney (1-alpha-hydroxylation, stimulated by PTH).","Fígado e rim."],["1ab421lhe","Function of active vitamin D?","Increases intestinal absorption of Ca2+ and phosphate, increases bone resorption of Ca2+ and phosphate.","Absorver cálcio e fosfato."],["6g25quci5","Signs of vitamin D deficiency in children?","Rickets: deformity (genu varum, bowlegs), bone pain, rachitic rosary, craniotabes.","Raquitismo."],["d8kfr2k5h","Signs of vitamin D deficiency in adults?","Osteomalacia: bone pain and muscle weakness; hypocalcemic tetany in severe cases.","Osteomalácia."],["c2oimk1mw","Who is at risk for vitamin D deficiency?","Low sun exposure, darker skin, exclusively breastfed infants (give supplements), malabsorption, liver or kidney disease, elderly.","Pouco sol, pele escura."],["3sdkmk1we","Signs of vitamin D excess?","Hypercalcemia, hypercalciuria, loss of appetite, stupor; seen in granulomatous disease (sarcoidosis: macrophages activate vitamin D).","Hipercalcemia."],["160e3lp97","What is the function of vitamin E?","Antioxidant (protects RBCs and membranes from free radical damage).","Antioxidante."],["sqk28zpx0","Signs of vitamin E deficiency?","Hemolytic anemia, acanthocytosis, muscle weakness, posterior column and spinocerebellar tract demyelination (similar to B12 deficiency but without megaloblastic anemia or high MMA).","Hemólise e neuropatia."],["bl28kfu8o","Effect of high-dose vitamin E?","May enhance anticoagulant effect of warfarin; increased risk of necrotizing enterocolitis in infants.","Risco de sangramento."],["160e3ub97","What is the function of vitamin K?","Cofactor for gamma-carboxylation of glutamic acid residues on clotting factors II, VII, IX, X and proteins C and S.","Carboxilar fatores."],["129jv8t1u","How is vitamin K produced and recycled?","Synthesized by intestinal flora; recycled by vitamin K epoxide reductase (target of warfarin).","Flora intestinal."],["17q87ek1a","Why are newborns given vitamin K at birth?","Neonates have sterile intestines and poor placental transfer; risk of hemorrhagic disease of the newborn.","Intestino estéril."],["r8t7cdenu","Signs of vitamin K deficiency?","Neonatal hemorrhage with increased PT and aPTT but normal bleeding time; also after prolonged broad-spectrum antibiotics.","Sangramento."],["1b7wqznvq","Which lab test rises first in vitamin K deficiency?","PT/INR (factor VII has the shortest half-life).","TP."],["1adxl8muo","What is the function of zinc?","Essential for the activity of many enzymes; important in zinc finger transcription factors.","Enzimas e cicatrização."],["mw5zx41o6","Signs of zinc deficiency?","Delayed wound healing, suppressed immunity, male hypogonadism, decreased adult hair, dysgeusia, anosmia, acrodermatitis enteropathica (perioral and perianal rash).","Feridas, anosmia, hipogonadismo."],["boqqhd11i","What may zinc deficiency predispose to in alcoholics?","Alcoholic cirrhosis (zinc deficiency is common in alcoholics).","Cirrose."],["1euac814k","What is acrodermatitis enteropathica?","Autosomal recessive defect in intestinal zinc absorption: dermatitis around orifices and extremities, alopecia, diarrhea.","Falta absorção de zinco."],["1u9frg34y","What are the clinical effects of copper deficiency?","Microcytic anemia, neutropenia, myelopathy (similar to B12 deficiency), hypopigmentation; associated with gastric bypass and excess zinc intake.","Anemia e neuropatia."],["66gk531vq","Why does excess zinc intake cause copper deficiency?","Zinc induces metallothionein in enterocytes, which binds copper and blocks its absorption.","Zinco bloqueia cobre."],["yoddcn1i9","What is selenium important for?","Glutathione peroxidase and thyroid hormone deiodinases.","Antioxidante."],["1gp7iyu1w","Signs of selenium deficiency?","Keshan disease (cardiomyopathy), myopathy, hypothyroidism.","Cardiomiopatia."],["1plixzi16","What is the role of iodine?","Needed for thyroid hormone synthesis.","Hormônio tireoidiano."],["1pk03hiaq","Signs of iodine deficiency?","Goiter, hypothyroidism; in pregnancy, congenital hypothyroidism (cretinism).","Bócio e hipotireoidismo."],["n4ggit1bo","What does fluoride do and what is excess fluoride's effect?","Strengthens tooth enamel; excess causes dental fluorosis (mottled teeth).","Protege dente; mancha."],["1751vk8i0","What is the role of chromium in metabolism?","Enhances insulin action; deficiency (rare, with long-term TPN) causes glucose intolerance.","Ação da insulina."],["tash4u198","What is the role of manganese and molybdenum?","Manganese: cofactor for enzymes like superoxide dismutase (mitochondrial). Molybdenum: cofactor for xanthine oxidase, sulfite oxidase.","Cofatores enzimáticos."],["1kouc0e16","What is kwashiorkor?","Protein malnutrition with relatively adequate caloric intake causing skin lesions, edema, liver malfunction (fatty liver), and anemia.","Falta de proteína."],["1uk06bm19","Mnemonic for kwashiorkor features?","MEAL: Malnutrition, Edema, Anemia, Liver (fatty).","MEAL: edema, fígado."],["yv9ka41li","Why does kwashiorkor cause edema?","Decreased plasma oncotic pressure from low albumin.","Albumina baixa."],["1cl8qr41a","Why is there a fatty liver in kwashiorkor?","Decreased apolipoprotein synthesis prevents VLDL export of triglycerides from the liver.","Sem apolipoproteína."],["l9dxvx139","What is marasmus?","Total calorie malnutrition (protein and energy) causing tissue and muscle wasting, loss of subcutaneous fat, variable edema.","Falta de calorias."],["ojj1081ue","Key difference between marasmus and kwashiorkor?","Marasmus: marked muscle wasting, no significant edema. Kwashiorkor: edema with swollen abdomen.","Edema no kwashiorkor."],["1xbyesq1p","What is refeeding syndrome?","Electrolyte shifts when nutrition is restarted after starvation; insulin release causes hypophosphatemia, hypokalemia, hypomagnesemia, causing arrhythmias and heart failure.","Realimentação brusca."],["1ih447i63","Which electrolyte is most characteristic of refeeding syndrome?","Hypophosphatemia.","Hipofosfatemia."],["1qyi4kr15","How is ethanol metabolized?","Alcohol dehydrogenase converts ethanol to acetaldehyde (cytosol), then aldehyde dehydrogenase converts it to acetate (mitochondria). Both produce NADH.","ADH e ALDH."],["212fggovd","What kinetics does alcohol dehydrogenase follow?","Zero-order kinetics (constant amount metabolized per unit time).","Ordem zero."],["1h1ax8v70","What does fomepizole inhibit and when is it used?","Alcohol dehydrogenase; antidote for methanol or ethylene glycol poisoning.","Álcool desidrogenase; metanol."],["lw0rwisy0","What does disulfiram inhibit?","Acetaldehyde dehydrogenase, causing acetaldehyde accumulation (flushing, nausea, tachycardia, hypotension) after drinking.","ALDH."],["qg36bfnm6","Which drugs cause disulfiram-like reactions?","Metronidazole, certain cephalosporins, griseofulvin, procarbazine, first-generation sulfonylureas.","Metronidazol, cefalosporinas."],["1vrwpvnz0","Why do some East Asian people have alcohol flushing?","Reduced activity of aldehyde dehydrogenase (ALDH2 variant), causing acetaldehyde accumulation.","ALDH deficiente."],["1delwqow1","What are the effects of the high NADH/NAD+ ratio from ethanol metabolism?","Lactic acidosis, fasting hypoglycemia, hepatic steatosis, ketoacidosis tendency (OAA to malate and pyruvate to lactate).","Lactato, cetonas, esteatose."],["d5z7uy1fb","Why does ethanol cause fasting hypoglycemia?","High NADH shifts pyruvate to lactate and OAA to malate, inhibiting gluconeogenesis.","Inibe gliconeogênese."],["1vrcwmguu","Why does chronic alcohol use cause hepatic steatosis?","High NADH increases glycerol-3-phosphate (from DHAP) and fatty acid synthesis while inhibiting beta-oxidation.","Excesso de NADH."],["bkape71bc","Which microsomal enzyme is induced by chronic alcohol use?","CYP2E1 (microsomal ethanol-oxidizing system), which increases acetaminophen hepatotoxicity.","CYP2E1."],["1xptbd1yp","Why does alcohol use increase acetaminophen toxicity?","Induction of CYP2E1 increases NAPQI formation, and alcoholics often have low glutathione stores.","Mais NAPQI."],["1wbxndi1b","What is alcoholic ketoacidosis?","Ketoacidosis after binge drinking with poor food intake: high beta-hydroxybutyrate (NADH shifts acetoacetate to beta-hydroxybutyrate).","Cetose sem hiperglicemia."],["uuwem3156","Which vitamin deficiencies are common in alcoholics?","Thiamine (B1), folate, niacin, B6, vitamin A; also magnesium, zinc, phosphate deficiencies.","Tiamina, folato, magnésio."],["183j2by13","What is the recommended daily intake concept: RDA?","Recommended Dietary Allowance: average daily intake sufficient for nearly all healthy individuals.","Atende 97% da população."],["1w6fffc72","What is the BMI formula and obesity threshold?","BMI = weight (kg) / height (m)^2. Overweight 25-29.9, obese 30 or more.","Peso/altura²; 30."],["bftbgl11h","What vitamin is necessary for calcium absorption and may need supplementation in breastfed infants?","Vitamin D (400 IU/day for exclusively breastfed infants).","Vitamina D."],["1hbxf47wa","Which vitamin is low in goat milk and causes macrocytic anemia in infants fed goat milk?","Folate (also B12).","Folato."],["vxkg70e7v","Which vitamin is supplemented to prevent neural tube defects and at what dose?","Folic acid, 0.4 mg/day for all women of reproductive age (4 mg/day for high-risk women).","Folato 0,4 mg."],["82mq571kl","Which vitamin deficiency can be caused by long-term phenytoin therapy?","Folate (also vitamin D).","Folato."],["ttxxkj3ub","Which vitamin deficiency is associated with trimethoprim and methotrexate?","Folate (impaired regeneration of THF).","Folato."],["17wp15pat","Which drug can be given to reduce methotrexate toxicity?","Leucovorin (folinic acid), which bypasses DHFR.","Leucovorina."],["1ewxae51r","What type of anemia is seen in severe vitamin B6 deficiency?","Sideroblastic (microcytic) anemia.","Sideroblástica."],["17o8x4odi","Which vitamin is needed for the synthesis of serotonin, GABA, and catecholamines?","Vitamin B6.","B6."],["fsptmu1g1","What is the role of vitamin B12 in the methylmalonyl-CoA pathway?","Converts methylmalonyl-CoA to succinyl-CoA (methylmalonyl-CoA mutase).","Mutase."],["1sf4yseug","Which vitamin is a cofactor for dopamine beta-hydroxylase?","Vitamin C.","Vitamina C."],["h6i7zc13y","What vitamin deficiency causes corkscrew hairs and perifollicular hemorrhages?","Vitamin C (scurvy).","Vitamina C."],["1w3c7oa1y","What vitamin deficiency mimics B12 neurologic deficits but without anemia?","Vitamin E deficiency (and copper deficiency).","Vitamina E."],["13wbct1y1","Which vitamin deficiency causes cheilosis and corneal vascularization?","Riboflavin (B2).","B2."],["1jq0wt6je","What is the role of iron in the body?","Component of hemoglobin, myoglobin, cytochromes; stored as ferritin and hemosiderin.","Transporte de oxigênio."],["vlru1b1s0","Where is dietary iron absorbed?","Duodenum (mostly as Fe2+ via DMT1); heme iron is absorbed more efficiently.","Duodeno."],["1y036lryd","How is iron exported from enterocytes and transported?","Ferroportin exports iron (oxidized by hephaestin); transferrin carries it in blood.","Ferroportina e transferrina."],["abtrtmkvq","What regulates intestinal iron absorption?","Hepcidin, made by the liver, which degrades ferroportin; increased by inflammation and high iron.","Hepcidina."],["vfau89kix","Why does inflammation cause anemia of chronic disease?","Increased hepcidin traps iron in macrophages and decreases absorption.","Hepcidina retém ferro."],["1tzutm3kk","Lab findings in iron deficiency?","Low serum iron, high TIBC (transferrin), low ferritin, low transferrin saturation; microcytic hypochromic anemia.","Ferritina baixa, TIBC alta."],["ivi0701ms","Signs of iron deficiency besides anemia?","Pica (ice), koilonychia (spoon nails), glossitis, angular cheilitis; Plummer-Vinson syndrome (with esophageal webs).","Coiloníquia, pica."],["l5jkennz4","What is the antidote for acute iron overdose?","Deferoxamine (chelator).","Deferoxamina."],["19bla531x","Clinical features of acute iron poisoning in children?","GI bleeding (hematemesis), anion gap metabolic acidosis, shock; can be fatal; radiopaque pills on x-ray.","Vômito sanguinolento, acidose."],["19scb6t1d","Which mineral deficiency causes hypocalcemia refractory to calcium supplementation?","Hypomagnesemia (Mg is needed for PTH secretion and action).","Magnésio."],["ok90w71kr","Which mineral excess or deficiency causes muscle weakness and arrhythmias in refeeding?","Hypophosphatemia (also hypokalemia, hypomagnesemia).","Fosfato, potássio, magnésio."],["1xj52yz1q","What is the effect of a vegan diet on vitamin B12?","Risk of deficiency, since B12 is found only in animal products; supplementation is needed.","Deficiência."],["1xlpvirgl","Which vitamin is a cofactor for gamma-carboxylation and is antagonized by warfarin?","Vitamin K.","Vitamina K."],["12s7tf01a","Which vitamin is antagonized by isoniazid?","Vitamin B6.","B6."],["6i4yqv1e9","Which vitamin is converted from beta-carotene?","Vitamin A.","Vitamina A."],["exf2s8gwc","What does carotenemia cause and how is it different from jaundice?","Yellow-orange skin from excess carotene intake, with sparing of the sclerae (unlike jaundice).","Pele laranja, esclera branca."],["8f1yu0ybv","What nutritional deficiency is linked to exclusively corn-based diets?","Niacin (pellagra), unless corn is treated with alkali (nixtamalization).","Pelagra."],["b2t2uq1e7","What nutritional deficiency is linked to polished rice diets?","Thiamine (beriberi).","Beribéri."],["109ql2713","Which vitamin is a coenzyme for transketolase?","Thiamine (B1).","B1."],["1842xaze5","Which vitamin forms part of FAD for the electron transport chain complex II?","Riboflavin (B2).","B2."],["bexguvvjp","Which vitamin is required for hydroxylation of proline residues?","Vitamin C.","Vitamina C."],["1lcwbu8l0","What is the role of vitamin D binding protein?","Carries vitamin D metabolites in the blood.","Transporta vitamina D."],["8p2aml1vl","What is the main storage form of vitamin D measured to assess status?","25-hydroxyvitamin D (calcidiol).","25-OH vitamina D."],["lq3oy7rb5","Why do patients with chronic kidney disease develop vitamin D deficiency?","Reduced 1-alpha-hydroxylase activity in the kidney, so less calcitriol is formed.","Falta 1-alfa-hidroxilase."],["113litkhr","Why do patients with sarcoidosis develop hypercalcemia?","Granuloma macrophages express 1-alpha-hydroxylase, producing excess calcitriol.","Granuloma faz calcitriol."],["yt59ggaqi","What are the nutritional risks after gastric bypass surgery?","Deficiencies of B12, iron, folate, thiamine, calcium, vitamin D, copper, and fat-soluble vitamins.","B12, ferro, cálcio."],["ayybo9xre","What is the primary cause of death in severe marasmus?","Infection (immunosuppression) and electrolyte disturbances.","Infecção."],["nyu9fn6au","Which supplement is used to treat Wernicke encephalopathy?","IV thiamine (given before glucose).","Tiamina."],["13j0foqfj","Which vitamin is used in high doses to raise HDL?","Niacin (B3).","Niacina."],["na0sh7bk8","Which vitamin is used for acute promyelocytic leukemia?","All-trans retinoic acid (vitamin A derivative).","Vitamina A."],["1qlfdy6xg","Which vitamin is needed for heme synthesis (ALA synthase)?","Vitamin B6.","B6."],["67j5ad1iu","Which mineral is a cofactor for lysyl oxidase and ceruloplasmin?","Copper.","Cobre."],["1vkiosueb","Which trace element deficiency is linked to long-term TPN with impaired glucose tolerance?","Chromium.","Cromo."],["1p13osr1m","Which vitamin deficiency causes a pellagra-like rash in carcinoid syndrome?","Niacin (tryptophan is diverted to serotonin).","Niacina."]]}];
